        },
        HomePianoDes_1001001 = {
          ContentDE = "In der Dämmerung badend segelten wir durch die grenzenlose Dunkelheit – gemeinsam, immer weiter, der Morgendämmerung entgegen."
        },
        HomePianoDes_1001002 = {
          ContentDE = "Hinter Staub und Sand lauert das Schicksal."
        },
        HomePianoDes_1001003 = {
          ContentDE = "Blick niemals zurück."
        },
        HomePianoDes_1001004 = {
          ContentDE = "Die Insel war einst ein Ort der Ruhe, bis sie in Vergessenheit geriet."
        },
        HomePianoDes_1001005 = {
          ContentDE = "Wenn sich der erste Morgennebel lichtet, brichst auch du auf."
        },
        HomePianoDes_1001006 = {
          ContentDE = "Bis wir uns eines Tages wiedersehen."
        },
        HomePianoDes_1002001 = {
          ContentDE = "Niemand weiß, ob der Blick der Schicksalsgöttin ein Segen oder ein Fluch ist."
        },
        HomePianoDes_1002002 = {
          ContentDE = "Wir flehen das Schicksal an, uns gnädig zu sein."
        },
        HomePianoDes_1002003 = {
          ContentDE = "Wir flehen das Schicksal an, uns gnädig zu sein. oder wir erheben unsere Schwerter gegen es."
        },
        HomePianoDes_1003001 = {
          ContentDE = "Hand in Hand fliehen sie – einem einzigen Funken Hoffnung hinterher."
        },
        HomePianoDes_1003002 = {
          ContentDE = "Wandelnd auf der Messerklinge der Vergangenheit."
        },
        HomePianoDes_1003003 = {
          ContentDE = "Der Kampf eines eingekesselten Tieres."
        },
        HomePianoDes_1003004 = {
          ContentDE = "Wenn du all dies retten willst."
        },
        HomePianoDes_1004001 = {
          ContentDE = "Diese Tür heißt Fremde nicht willkommen."
        },
        HomePianoDes_1004002 = {
          ContentDE = "Die unerbittliche Kälte und die Schneestürme dienen als ihre treuesten Wächter."
        },
        HomePianoDes_1004003 = {
          ContentDE = "Bis das letzte Ziel erreicht ist, wird dieser Ort immer Heimat bleiben."
        },
        HomePianoDes_1004004 = {
          ContentDE = "Ein stacheliger Schlagabtausch – ein bemerkenswerter Auftakt."
        },
        HomePianoDes_1004005 = {
          ContentDE = "Herzlichen Glückwunsch – du hast die Chance gewonnen, {性别:deinem Bruder von einer anderen Mutter|deiner Schwester von einem anderen Vater} zu begegnen."
        },
        HomePianoDes_1004006 = {
          ContentDE = "Getränke, Missionen, Gerüchte, Geheimnisse – alles, was man handeln kann, wechselt hier den Besitzer."
        },
        HomePianoDes_1004007 = {
          ContentDE = "Ein Haus, in dem Geheimnisse schlummern."
        },
        HomePianoDes_1004008 = {
          ContentDE = "Zuhause, süßes Zuhause – es gibt nichts Besseres."
        },
        HomePianoDes_1005001 = {
          ContentDE = "Der erste Vorgeschmack auf Glück für {性别:einen unerfahrenen Phoxjäger|eine unerfahrene Phoxjägerin}."
        },
        HomePianoDes_1005002 = {
          ContentDE = "Der Beginn einer langen Reise."
        },
        HomePianoDes_1005003 = {
          ContentDE = "Im heulenden Sturm zählst du jeden Schritt, der dich zu ihr führt."
        },
        HomePianoDes_1005004 = {
          ContentDE = "Im Rückblick weißt du, dass es eine Geschichte der Mutigen war."
        },
        HomePianoDes_1005005 = {
          ContentDE = "Wenn du lange in einen Abgrund starrst, starrt der Abgrund auch in dich hinein."
        },
        HomePianoDes_1005006 = {
          ContentDE = "Wir lachen, wenn wir über den Tod sprechen, und weinen, während wir weiterleben."
        },
        HomePianoDes_1005007 = {
          ContentDE = "Er bringt den Tod – und ebenso das Leben."
        },
        HomePianoDes_1005008 = {
          ContentDE = "{性别:Verlorener Reisender|Verlorene Reisende}, kehre zu diesem Traum zurück – der Vogelgeist ist nie fortgegangen."
        },
        HomePianoDes_1005009 = {
          ContentDE = "{性别:Verlorener Reisender|Verlorene Reisende}, verlasse diesen Traum jetzt – der Vogelgeist ist davongeflogen."
        },
        HomePianoDes_1006001 = {
          ContentDE = "Man sagt, dass es in Icelake keinen Sommer gibt. Du siehst das anders."
        },
        HomePianoDes_1006002 = {
          ContentDE = "Selbst eine Eintagsfliege hat das Recht zu träumen."
        },
        HomePianoDes_1006003 = {
          ContentDE = "Diese Blume muss noch zu ihrer vollen Pracht erblühen."
        },
        HomePianoDes_1006004 = {
          ContentDE = "Die Kamera ist der beste Jäger – nur sie kann die flüchtige Zeit einfangen."
        },
        HomePianoDes_1006005 = {
          ContentDE = "Alles Licht eilt seinem Erlöschen entgegen."
        },
        HomePianoDes_1006006 = {
          ContentDE = "Die Geschichte ihres Lebens."
        },
        HomePianoDes_1006007 = {
          ContentDE = "Was bedeutet „Tod“?"
        },
        HomePianoDes_1006008 = {
          ContentDE = "Was bedeutet „Leben“?"
        },
        HomePianoDes_1006009 = {
          ContentDE = "Ihre Antwort."
        },
        HomePianoDes_1006010 = {
          ContentDE = "Blühend auf gefrorenem Boden."
        },
        HomePianoDes_1007001 = {
          ContentDE = "Für die bald bevorstehende erbitterte Schlacht."
        },
        HomePianoDes_1007002 = {
          ContentDE = "Vorstoß durch den Bauch des eisernen Ungetüms."
        },
        HomePianoDes_1007003 = {
          ContentDE = "Ein Lebenselixier namens Phoxichor durchströmt jede Ader Hyperboreas."
        },
        HomePianoDes_1007004 = {
          ContentDE = "Niemand weiß, woher die nächste Kugel kommen wird."
        },
        HomePianoDes_1007005 = {
          ContentDE = "Seid mutig und lebt weiter – gemeinsam."
        },
        HomePianoDes_1007006 = {
          ContentDE = "Bis die Maske fällt, weiß niemand, ob sie das Gesicht eines Engels oder eines Dämons verbirgt."
        },
        HomePianoDes_1007007 = {
          ContentDE = "„Heute Nacht regnet es in Dismania.“"
        },
        HomePianoDes_1007008 = {
          ContentDE = "Doch klarer Himmel wird kommen."
        },
        HomePianoDes_1007009 = {
          ContentDE = "Im Namen der Gerechtigkeit verhängt der Inquisitor ein feuriges Urteil."
        },
        HomePianoDes_1008001 = {
          ContentDE = "Ihre Wanderungen mögen wohl hundertmal das weite Atlasia durchquert haben."
        },
        HomePianoDes_1009001 = {
          ContentDE = "Webe Logik zu einem Netz, um eine Scherbe der Wahrheit zu fangen."
        },
        HomePianoDes_1009002 = {
          ContentDE = "Junge, leidenschaftliche Herzen schlagen für eine Zukunft in voller Farbe."
        },
        HomePianoDes_1009003 = {
          ContentDE = "Selbst das feinste Drama ist nur ein Fragment des Lebens."
        },
        HomePianoDes_1009004 = {
          ContentDE = "Wir liegen alle in der Gosse, aber einige von uns blicken zu den Sternen."
        },
        HomePianoDes_1009005 = {
          ContentDE = "Schau wieder nach oben – nur Phantome, gebrochen im zersplitterten Glas."
        },
        HomePianoDes_1009006 = {
          ContentDE = "Wenn die Götter uns verlassen haben, wo liegt dann die Erlösung?"
        },
        HomePianoDes_1009007 = {
          ContentDE = "Zum ersten Mal öffne ich mein Herz und umfange die sanfte Gleichgültigkeit der Welt."
        },
        HomePianoDes_1009008 = {
          ContentDE = "Nur der Schnee erinnert sich."
        },
        HomePianoNAme_1001001 = {
          ContentDE = "Duet Night Abyss Titelsong"
        },
        HomePianoNAme_1001002 = {
          ContentDE = "Durch das Sandreich"
        },
        HomePianoNAme_1001003 = {
          ContentDE = "Die Ruhe meiner vergangenen Tage"
        },
        HomePianoNAme_1001004 = {
          ContentDE = "Das verlassene Dorf"
        },
        HomePianoNAme_1001005 = {
          ContentDE = "Morgennebel"
        },
        HomePianoNAme_1001006 = {
          ContentDE = "Ein langer Abschied"
        },
        HomePianoNAme_1002001 = {
          ContentDE = "Der Schicksalsseher"
        },
        HomePianoNAme_1002002 = {
