        MESSAGE_LOADING_101_PC = {
          ContentDE = "Ein belebter Hafen in Nebelkai-Bezirk, das ganze Jahr über von Schiffen frequentiert. Er dient als erster Anlaufpunkt für die Sternenweber, die über den Kontinent Atlasia aufbrechen."
        },
        MESSAGE_LOADING_102_PC = {
          ContentDE = "Große Steintafeln, auf denen die Gesetze der Neun Kapitel eingraviert sind. An prominenten Orten in ganz Huaxu aufgestellt, dienen sie allen als stetige Erinnerung."
        },
        MESSAGE_LOADING_103_PC = {
          ContentDE = "Eine weite Ebene in Nebelkai-Bezirk, dicht mit hohen Schilfhalmen bewachsen, in denen man oft Smaragdfink sehen kann, wie sie durch die schwankenden Halme flattern."
        },
        MESSAGE_LOADING_104_PC = {
          ContentDE = "Eine bedeutende Handelsgilde auf den Ebenen von Nebelkai und der Hauptverband der Sternenweber.\n Am Fuße eines gewaltigen Baumes gelegen, wird die Gilde von einem mondförmigen Gerät gekrönt, das durch Weihrauch betrieben wird."
        },
        MESSAGE_LOADING_105_PC = {
          ContentDE = "Eine Küstenhöhle am westlichen Rand der Ebenen von Nebelkai. Das Echo der Gezeiten hallt endlos durch ihre Tiefen und verleiht der Höhle ihren Namen."
        },
        MESSAGE_LOADING_106_PC = {
          ContentDE = "Der Schwarzmarkt von Nebelkai, entlang einer westlichen Küste zwischen Schiffswracks gelegen.\n Ihre Abgeschiedenheit und die geringe Frequentierung ziehen opportunistische Händler an und machen sie zu einem Zentrum für illegale Geschäfte."
        },
        MESSAGE_LOADING_107_PC = {
          ContentDE = "Das alte Schlachtfeld der Schlacht von Shuli, nordwestlich von Nebelkai auf einer einsamen Insel im Meer gelegen. Einst ein zentrales Forschungsgebiet der Jishu-Sekte, wurden die meisten Konstrukte im Krieg zerstört, einige sind jedoch noch voll funktionsfähig."
        },
        MESSAGE_LOADING_108_PC = {
          ContentDE = "Ein Hochlandgebiet nordwestlich von Nebelkai. Von den entfesselten Energien Zhuyins durchzogen, ist es nun von Gritblight bedeckt und karg. Die Vegetation der Oberfläche ist kristallisiert, und schroffe Felsen durchziehen das Land — eine Landschaft, die als Gritblight-Ebene bekannt geworden ist."
        },
        MESSAGE_LOADING_109_PC = {
          ContentDE = "Eine weite Ebene in Nebelkai-Bezirk, dicht mit hohen Schilfhalmen bewachsen, in denen man oft Smaragdfink sehen kann, wie sie durch die schwankenden Halme flattern."
        },
        MESSAGE_LOADING_10_PC = {
          ContentDE = "Eine abgelegene Insel mitten im offenen Meer an der Grenze zwischen Hyperborea und Elysium. Die Elysianer errichteten dort vor einem Jahrtausend einen Schrein, doch heute zeugen nur noch Ruinen von seiner einstigen Pracht."
        },
        MESSAGE_LOADING_110_PC = {
          ContentDE = "Eine Insel im Herzen des zentralen Sees von Nebelkai, ruhig und abgeschieden unter dichtem Grün. Es heißt, dass die Wishen hier ihre Heimat haben."
        },
        MESSAGE_LOADING_111_PC = {
          ContentDE = "Die Ahnenklinik des Hauses Fu, ein Zweig des Zhuyou-Clans, bekannt für seine Heilkunst. Gelegen in einem Aprikosenhain im nördlichen Nebelkai, ist sie noch immer ein Ort, an dem Menschen Behandlung suchen."
        },
        MESSAGE_LOADING_112_PC = {
          ContentDE = "Ein Altar, errichtet von früheren Generationen, um Zhuyin zu versiegeln. Er steht über dem aufbrausenden Meer und blickt aus der Ferne auf die Gritblight-Ebene."
        },
        MESSAGE_LOADING_113_PC = {
          ContentDE = "Eine anomale Dimension, entstanden, als die Yu-Quelle durch den Fluch von Zhuyin verunreinigt wurde. Innerhalb dieser Dimension vergessen die Seelen allmählich alle weltlichen Bindungen und gehen für immer verloren."
        },
        MESSAGE_LOADING_114_PC = {
          ContentDE = "Eine anomale Dimension, entstanden, als die Yu-Quelle durch den Fluch von Zhuyin verunreinigt wurde. Innerhalb dieser Dimension vergessen die Seelen allmählich alle weltlichen Bindungen und gehen für immer verloren."
        },
        MESSAGE_LOADING_115_PC = {
          ContentDE = "Eine anomale Dimension, entstanden, als die Yu-Quelle durch den Fluch von Zhuyin verunreinigt wurde. Innerhalb dieser Dimension vergessen die Seelen allmählich alle weltlichen Bindungen und gehen für immer verloren."
        },
        MESSAGE_LOADING_116_PC = {
          ContentDE = "Eine urzeitliche mechanische Falle, lange Zeit in der Krähenlied-Hohl ruhend, wurde während Herr Qius Jagdeinsatzes versehentlich ausgelöst."
        },
        MESSAGE_LOADING_117_PC = {
          ContentDE = "Eine urzeitliche mechanische Falle, lange Zeit in der Krähenlied-Hohl ruhend, wurde während Herr Qius Jagdeinsatzes versehentlich ausgelöst."
        },
        MESSAGE_LOADING_118_PC = {
          ContentDE = "Eine urzeitliche mechanische Falle, lange Zeit in der Krähenlied-Hohl ruhend, wurde während Herr Qius Jagdeinsatzes versehentlich ausgelöst."
        },
        MESSAGE_LOADING_119_PC = {
          ContentDE = "Eine überraschend stattliche Residenz, verborgen in einem gestrandeten Wrack auf dem Dunstmarkt.\n Hier wartet Herr Qiu – Meister des Schwarzmarkts – still auf dein Eintreffen."
        },
        MESSAGE_LOADING_11_PC = {
          ContentDE = "Eine Stadt an der nördlichen Grenze des Hyperboreischen Imperiums, die untrennbar mit der Entstehung des Imperiums verbunden ist und früher ein wichtiger Phoxene-Knotenpunkt war. Die unerbittliche Kälte und die Schneestürme dienen als ihre treuesten Wächter."
        },
        MESSAGE_LOADING_12_PC = {
          ContentDE = "Das mit „Magie“ geborene Volk trägt den Namen Charon – dieser Name besitzt von Nation zu Nation eine sehr unterschiedliche Bedeutung. Hier im Hyperboreischen Imperium tragen sie den unheilvollen Titel „Kinder des Dämons“."
        },
        MESSAGE_LOADING_13_PC = {
          ContentDE = "Im Volk der Charon verfügen diejenigen, die mit besonderen Talenten geboren werden, über vielfältige magische Kräfte, die im hyperboreischen Imperium als „dämonische Künste“ gebrandmarkt werden."
        },
        MESSAGE_LOADING_14_PC = {
          ContentDE = "Diese Monster, die überall zu finden sind und oft in Rudeln durch die Wildnis ziehen, sind eine Gefahr, die man nicht unterschätzen sollte."
        },
        MESSAGE_LOADING_15_PC = {
          ContentDE = "Ein freundliches Volk, das auch als Lunos bezeichnet wird, und neben den Menschen koexistiert. Sie ähneln menschlichen Kindern, unterscheiden sich jedoch durch ihr mondhelles weißes Haar, von den sich auch der Name ableitet. Sie sind dafür bekannt, dass sie den Menschen in guter Absicht helfen wollen, aber oftmals sorgen ihre Bemühungen mehr für Chaos als für Hilfe."
        },
        MESSAGE_LOADING_16_PC = {
          ContentDE = "Eine imperiale Nation, die sich im Norden von Atlasia angesiedelt hat. Dieses Volk liebt militärische Eroberungen und alchemistische Fähigkeiten und steht in ständigem Konflikt mit der Elysischen Kirche.\nUnter der glorreichen Krone gedeiht ein Vermächtnis aus Tapferkeit und Eisen. Alle Ehre dem Kaiser."
        },
        MESSAGE_LOADING_17_PC = {
          ContentDE = "Im Süden von Atlasia befindet sich ein Königreich, das sich dem Göttlichen verschrieben hat. Es befolgt die Gebote von neun Gottheiten und wahrt eine alte, geordnete Regierungsform. Dieses prächtige, unvergängliche Land, das wie ein Stück Phoxene auf hohen Ästen thront, verspricht unvergleichliches Glück und eine strahlende Zukunft."
        },
        MESSAGE_LOADING_18_PC = {
          ContentDE = "Im Osten von Atlasia liegt ein Land, das sich durch prachtvolle Pavillons und Paläste auszeichnet, die das Landschaftsbild prägen. Dies ist das angestammte Land der Sternenweber, die auf dem ganzen Kontinent für ihr kaufmännisches Geschick bekannt sind.\nVon den Sternen geleitet erschaffen sie Schönheit aus den Gaben der Erde. Ihre erhabenen Gesänge werden zu Poesie, zu einer Ode, die der friedlichen Einsamkeit huldigt."
        },
        MESSAGE_LOADING_19_PC = {
          ContentDE = "Ducke dich und gleite durch niedrige, enge Lücken."
        },
        MESSAGE_LOADING_1_PC = {
          ContentDE = "Drücke &Slide& und anschließend &Jump&, um einen Spiralsprung über Klippen auszuführen oder weite Entfernungen zu überwinden."
        },
        MESSAGE_LOADING_1_Phone = {
          ContentDE = "Halte die Springen-Taste gedrückt und wische nach oben, um einen Spiralsprung über Klippen auszuführen oder weite Entfernungen zu überwinden"
        },
        MESSAGE_LOADING_201_PC = {
          ContentDE = "Östlich von Atlasia liegt ein Land mit prächtigen Pavillons und Palästen, die die Skyline beherrschen. Es ist das Stammland der Sternenweber, auf dem ganzen Kontinent für ihr Handelstalent bekannt.\n Von den Sternen geleitet, formen sie aus den Gaben der Erde Schönheit; ihre erhabenen Gesänge werden zur Poesie, eine Ode an die stille Einsamkeit."
        },
        MESSAGE_LOADING_202_PC = {
          ContentDE = "Ein bedeutender Hafen im Süden von Huaxu, wo Flüsse auf das Meer treffen. Nahe der alten Hauptstadt Haojing gelegen, ist er für sein mildes Klima und seine reizvollen Landschaften bekannt. Dieses Handelszentrum dient als wichtigster Anlaufpunkt für Ausländer, die Huaxu besuchen."
        },
        MESSAGE_LOADING_203_PC = {
          ContentDE = "Huaxus Bezeichnung für Charon.\n Anders als im Hyperboreischen Imperium gelten Charon hier als glückverheißendes Volk, das die Nation beschützt."
        },
        MESSAGE_LOADING_204_PC = {
          ContentDE = "Eine Katastrophe, die Huaxu heimsuchte, ausgehend von der Gritblight-Ebene und vor allem Nebelkai betreffend.\n Ihre Ausbreitung hat Handelsrouten abgeschnitten und das tägliche Leben schwer beeinträchtigt."
        },
        MESSAGE_LOADING_205_PC = {
          ContentDE = "Das höchste Gesetz, das ganz Huaxu regiert.\n Alle innerhalb seiner Grenzen müssen seinen Geboten folgen, andernfalls drohen Strafen, vollstreckt durch Bi’an oder den Magistrat von Yingtian."
        },
        MESSAGE_LOADING_206_PC = {
          ContentDE = "Als Meister der Navigation und des Handels verfügen die Sternenweber über die einzigartige Kunst der himmlischen Wegfindung, mit der sie selbst die gefährlichsten Seebedingungen überwinden. Ihr Einfluss reicht bis in die entlegensten Winkel Atlasias."
        },
        MESSAGE_LOADING_207_PC = {
          ContentDE = "Eine in ganz Huaxu verehrte Gottheit, dem einfachen Volk als Lord Argent bekannt. Sie gilt als Verkörperung des Himmlischen Weges und des in den Neun Kapiteln von Dafeng niedergelegten göttlichen Willens."
        },
        MESSAGE_LOADING_208_PC = {
          ContentDE = "Hüter und Vollstrecker Huaxus, handelnd nach dem Willen der Neun Kapitel.\n Ein göttliches Wesen mit Wolfs­haupt, tierischem Leib, weißem Fell und goldenen Hörnern.\n Werden die Neun Kapitel gebrochen, erscheint Bi’an, um das Urteil zu vollziehen."
        },
        MESSAGE_LOADING_209_PC = {
          ContentDE = "In ihrer Gestalt Bi’an ähnlich, jedoch pechschwarz gefärbt.\n Diese chaotischen Abscheulichkeiten sind jüngst nahe Nebelkai aufgetaucht – Ausgeburten der Plage von Zhuyin, jenseits der Kontrolle der Neun Kapitel.\n Sie greifen Reisende in der Wildnis wahllos an und gefährden die öffentliche Sicherheit schwer."
        },
        MESSAGE_LOADING_20_PC = {
          ContentDE = "Nutze den Spiralsprung, um dich schnell fortzubewegen – damit kannst du sogar an Orte kommen, die ansonsten nicht erreichbar sind."
        },
        MESSAGE_LOADING_210_PC = {
          ContentDE = "Eine in ganz Huaxu weit verbreitete Substanz, aus ausgewählten Zutaten mit speziellen Verfahren veredelt und in Riten der Zwiesprache mit dem Göttlichen verwendet. Überall im Land brennen Räucherbecken, ihr Duft liegt allgegenwärtig in der Luft, und viele Menschen tragen Räucherbeutel bei sich. Räucherwerk gilt als eines der prägenden Merkmale Huaxus."
        },
        MESSAGE_LOADING_211_PC = {
          ContentDE = "Eine bösartige Gottheit aus Huaxus alten Legenden, Rivale von Taihao, heute jenseits von Nebelkai versiegelt. Ihre wahnsinnige Macht ist dennoch nach außen gedrungen und hat die Plage von Zhuyin hervorgebracht."
        },
        MESSAGE_LOADING_212_PC = {
          ContentDE = "Vollstrecker innerhalb des Systems der Neun Kapitel, im Rang über Bi’an stehend. Auch sie sind aus Loongscions verwandelt. Nach ähnlicher Argumentation wie bei Bi’an vermuten Gelehrte, dass die Magistrate von Yingtian dem entsprechen, was gemeinhin als „Daimon“ bezeichnet würde."
        },
        MESSAGE_LOADING_215_PC = {
          ContentDE = "Eine von der Familie Fu, einem Zweig des Zhuyou-Clans, überlieferte Heilkunst, deren Kraft aus den Neun Kapiteln von Dafeng stammt. Der Anwender nutzt seine eigene Lebensessenz als Medium, um stagnierendes Qi und andere schädliche Krankheitsstoffe aus dem Körper des Patienten zu vertreiben. Längere Anwendung belastet den Anwender erheblich."
        },
        MESSAGE_LOADING_217_PC = {
          ContentDE = "Der Zhuyou-Clan war einst von den Neun Kapiteln von Dafeng mit der Gabe der Heilung gesegnet und genoss in Huaxu hohes Ansehen; ihm oblag die Pflege der Kranken.\n Mit dem Aufstieg der Heilkundelehre im vergangenen Jahrhundert sind die Zhuyou-Heilkünste jedoch zurückgegangen, und wahre Nachfolger innerhalb des Clans sind äußerst selten geworden."
        },
        MESSAGE_LOADING_218_PC = {
          ContentDE = "Mechanische Nexus kann eine beträchtliche Zugkraft erzeugen, wodurch er Kiesseuche von Oberflächen absorbieren oder Jishu-Sphären zu festgelegten Punkten ziehen kann."
        },
        MESSAGE_LOADING_219_PC = {
          ContentDE = "Mechanische Nexus kann nahegelegene Objekte scannen und interessante Punkte hervorheben."
        },
        MESSAGE_LOADING_21_PC = {
          ContentDE = "Nachdem du die Kampfhaltung eines Elite-Gegners vollständig gebrochen hast, kannst du „Asks Vergeltung“ entfesseln, um beträchtlichen Schaden zu verursachen.\nAsk ist der ehrwürdige Vatergott unter den Charons."
        },
        MESSAGE_LOADING_220_PC = {
          ContentDE = "Ein von der Jishu-Sekte gefertigtes Gerät. Dieser Würfel mit eingebettetem Energiekern wurde vom Schwarzmarkt eigens für Zhiliu angefertigt, um Zhuyin-Schuppen zu ernten. Er vereint starke Adsorptionskraft mit vielfältigen Funktionen."
        },
        MESSAGE_LOADING_221_PC = {
          ContentDE = "Eine geologische Seuche, die während der Plage von Zhuyin im Gebiet von Nebelkai entstand. Sie erscheint als violettes, kristallines Pulver, das sich auf Oberflächen absetzt und die Lebenskraft lebender Wesen entzieht."
        },
        MESSAGE_LOADING_224_PC = {
          ContentDE = "Einst zu den Schutzsekten Huaxus gezählt, ist die Jishu-Sekte längst in Verfall geraten. Berühmt für ihre Meisterschaft in Mechanpuppen und anderen Automatenkonstrukten, liefert sie weiterhin zivile Geräte in ganz Huaxu, doch gelten bestimmte Techniken der Mechanpuppenfertigung inzwischen als tabu."
        },
        MESSAGE_LOADING_225_PC = {
          ContentDE = "Eine Schutzsekte Huaxus, gegründet von Yang, einem der Gründungsmeister der Neun Kapitel von Dafeng. Ihre Mitglieder nutzen Weihrauch, um mit dem Göttlichen zu verkehren.\n In der Antike war die Xuanheng-Sekte die erste, die die mystischen Eigenschaften des Weihrauchs entdeckte, und sie bewahrt dieses Wissen seither als geheime Kunst."
        },
        MESSAGE_LOADING_227_PC = {
          ContentDE = "In Huaxu können unter dem Einfluss der Neun Kapitel von Dafeng die bei Tod zurückbleibenden Obsessionen Gestalt annehmen und zu Wesen werden, die als Wishen bekannt sind.\n Sie bewahren kaum Erinnerungen an ihr früheres Leben, und ihre Fähigkeit zu sprechen oder die Welt zu begreifen schwindet oft allmählich."
        },
        MESSAGE_LOADING_22_PC = {
          ContentDE = "Sprich mit Leuten in verschiedenen Städten. Regelmäßige Interaktionen können den „Eindruck”, den andere von dir haben, nach und nach beeinflussen."
        },
        MESSAGE_LOADING_23_PC = {
          ContentDE = "Wenn der Schild Schaden erleidet, wird die VTD nicht berücksichtigt. Nach einer gewissen Zeit ohne erlittenen Schaden regeneriert sich der Schild automatisch."
        },
        MESSAGE_LOADING_24_PC = {
          ContentDE = "Sobald die Kampfhaltung eines Elite-Gegners unterbrochen wird, ist er kurzzeitig handlungsunfähig und versucht, erneut seine Kampfhaltung einzunehmen. Währenddessen erleidet er erhöhten Schaden. Nutze diese Phase optimal, um schneller den Sieg zu erringen."
        },
        MESSAGE_LOADING_29_PC = {
          ContentDE = "Hieb: Verursacht höheren Schaden am Schild des Ziels. \n Durchdringung: Verursacht höheren Schaden an den LP des Ziels. \n Erschütterung: Schwächt die Kampfhaltung des Ziels weiter."
        },
        MESSAGE_LOADING_2_PC = {
          ContentDE = "Drücke in der Luft &Attack&, um einen Sturzangriff auszuführen."
        },
        MESSAGE_LOADING_2_Phone = {
          ContentDE = "Tippe in der Luft auf die Angriffstaste, um einen Sturzangriff auszuführen."
        },
        MESSAGE_LOADING_31_PC = {
          ContentDE = "Wenn du Dämonenkeile ausrüstest, kannst du deine Figuren und Waffen erheblich verstärken. Einige seltene Dämonenkeile können sogar die Fähigkeitseffekte des Trägers verzieren."
        },
        MESSAGE_LOADING_32_PC = {
          ContentDE = "Dämonenkeile sind eine Belastung für den Träger, und die maximale Belastung, die ein Träger aushalten kann, nennt man Toleranz. Wenn du deine Figuren und Waffen hochstufst, kannst du dieses Limit erhöhen und mehr Keile ausrüsten, um dir im Kampf einen größeren Vorteil zu verschaffen."
        },
        MESSAGE_LOADING_33_PC = {
          ContentDE = "Jeder Dämonenkeil verfügt über eine Affinität, die mit bestimmten Trägern in Resonanz steht – man bezeichnet dies als „Spur“. Wenn die Spur eines Keils mit der des Trägers (Figur/Waffe) übereinstimmt, wird weniger Toleranz verbraucht – wenn sie allerdings nicht zusammenpassen, ist eine größere Toleranz erforderlich."
        },
        MESSAGE_LOADING_34_PC = {
          ContentDE = "Die neueste Erfindung der Imperialen Alchemie-Akademie im Bereich der Dämonenkeil-Technologie, mit der man die Spur der Plätze verändern kann."
        },
        MESSAGE_LOADING_35_PC = {
          ContentDE = "Die speziellen Aufträge der Asphodel für {性别:Phoxjäger|Phoxjägerinnen}. Diese Missionen bieten gewöhnlich stattliche Belohnungen. Schließe sie ab, um die Kampfkraft deines Teams zu stärken."
        },
        MESSAGE_LOADING_36_PC = {
          ContentDE = "Lass dich nicht von den endlosen Wellen von Gegnern ausbremsen. Lokalisiere sofort dein Ziel, um die Mission schnell abzuschließen."
        },
        MESSAGE_LOADING_37_PC = {
          ContentDE = "Nutze Sprungpads, um den Evakuierungspunkt schneller zu erreichen, nachdem du dich um die teuflische Bombe „Großes Feuerwerk“ gekümmert hast."
        },
        MESSAGE_LOADING_38_PC = {
          ContentDE = "Orientiere dich in der Imperialen Festung an den unterschiedlichen gefärbten Kabeln, um die Verteidigungsanlagen außer Gefecht zu setzen."
        },
        MESSAGE_LOADING_39_PC = {
          ContentDE = "Klicke auf &Avoid&, um auszuweichen. Halte eine Richtung gedrückt, um in diese Richtung auszuweichen."
        },
        MESSAGE_LOADING_39_Phone = {
          ContentDE = "Tippe auf die Ausweichen-Taste, um ein Ausweichen auszuführen. Halte eine Richtung gedrückt, um in diese Richtung auszuweichen."
        },
        MESSAGE_LOADING_3_PC = {
          ContentDE = "Tippe auf &Attack& beim Gleiten, um einen Gleitangriff auszuführen."
        },
        MESSAGE_LOADING_3_Phone = {
          ContentDE = "Halte die Springen-Taste gedrückt und wische nach links, um einen Gleitangriff auszuführen."
        },
        MESSAGE_LOADING_40_PC = {
          ContentDE = "Nutze Farbstoffe, um die Farben von Figur-Outfits und Waffen zu ändern."
        },
        MESSAGE_LOADING_41_PC = {
          ContentDE = "Rüste deine Figuren mit verschiedenen Accessoires aus – so kannst du deinen ganz eigenen Stil kreieren."
        },
        MESSAGE_LOADING_42_PC = {
          ContentDE = "Besuche die Luno-Schmiedin, um Waffen und andere Gegenstände zu schmieden."
        },
        MESSAGE_LOADING_43_PC = {
          ContentDE = "Beim Erkunden der Welt kannst du auf <H>Geniemon</> stoßen. Nutze <H>Leckerei</>, um dich mit ihnen anzufreunden. Geniemon können dein Team im Kampf durch Geniemon-Unterstützung verstärken."
        },
        MESSAGE_LOADING_44_PC = {
          ContentDE = "Wenn du einen großen Fang machst, kannst du eine Chance auf <H>Auf größere Fische angeln</> auslösen! Verwende deinen aktuellen Fang als Köder und wirf die Angel erneut aus – vielleicht ziehst du einen noch selteneren Preis an Land."
        },
        MESSAGE_LOADING_45_PC = {
          ContentDE = "Wenn du besondere Nebenaufträge abschließt, kannst du einige neue Systemfunktionen freischalten."
        },
        MESSAGE_LOADING_46_PC = {
          ContentDE = "Besuche die <Highlight>Chronik der Zeit</>, um dir Geschichten aus verschiedenen Phasen im Leben einer Figur anzusehen."
