        MONSTER_PROFILE_6004013 = {
          ContentDE = "Serum sinkt schnell, solange Primarch: Korrosion lebt."
        },
        Mail_Content_100001 = {
          ContentDE = "Vielen Dank für das Ausfüllen der Umfrage! Wir haben ein kleines Geschenk für dich vorbereitet."
        },
        Mail_Content_100002 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\nvielen Dank, dass du die Umfrage ausgefüllt hast! Im Anhang findest du deine Belohnung.\nWir schätzen jedes Feedback und jede Anregung, die du uns gibst. Dein Feedback ist entscheidend, um die Gesamtqualität des Spiels weiter zu verbessern."
        },
        Mail_Content_100003 = {
          ContentDE = "Dies ist eine Test-E-Mail mit dem Bonuspaket 130004 (Dämonenkeil-Bundle der Nahkampfwaffe von Mittelstufe).\nLäuft in 1 Tag ab."
        },
        Mail_Content_100005 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin}:\n Deine nicht abgeholten Aktionsbelohnungen wurden an dein Postfach gesendet. Viel Erfolg bei deinen zukünftigen Leveln."
        },
        Mail_Content_10005 = {ContentDE = [[

 ]]},
        Mail_Content_10007 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n \n Hier findest du die Details deiner Rückerstattung aus dem zweiten geschlossenen Betatest:\n • Gesamte Aufladung:<H>{TotalRechargeMoney} CNY</> → erstattet als <H>{Phoxene} Phoxenekeime</>\n • Rückerstattung für den Monatspass: <H>{MonthlyCard} Pass(e)</>\n \n Wir danken dir herzlich für deine Unterstützung von Duet Night Abyss."
        },
        Mail_Content_10008 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n \n Vielen Dank für das Ausfüllen der Umfrage! Anbei findest du deine Belohnung.\n \n Wir schätzen jedes Feedback und jeden Vorschlag, den du uns gibst. Deine Meinung ist für uns sehr wichtig, um die Gesamtqualität des Spiels zu verbessern."
        },
        Mail_Content_10009 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n Deine <highlight>Prismatische Sanduhr (Zeitlich begrenzt)</> läuft bald ab. Bitte nutze sie rechtzeitig.\n Nach Ablauf werden sie automatisch in eine entsprechende Menge <highlight>Makellose Sanduhr</> umgewandelt."
        },
        Mail_Content_10010 = {
          ContentDE = "Du versuchst, ein Konto zu verknüpfen. Um die Sicherheit des Kontos zu gewährleisten, führe bitte die Identitätsprüfung durch. Dein Verifizierungscode: {Code}"
        },
        Mail_Content_10011 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n die Belohnungen, die du über Twitch Drops erhalten hast, wurden deinem Spielkonto zugestellt.\n Bitte hole sie über den unten stehenden Anhang ab.\n \n Vielen Dank für deine Unterstützung!\n \n – Duet Night Abyss Live-Ops"
        },
        Mail_Content_10012 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n die Belohnungen, die du über CHZZK-Drops erhalten hast, wurden deinem Spielkonto zugestellt.\n Bitte hole sie über den unten stehenden Anhang ab.\n \n Vielen Dank für deine Unterstützung!\n \n – Duet Night Abyss Live-Ops"
        },
        Mail_Content_10013 = {
          ContentDE = "Ein kleines Geheimnis für dich: Heute ist ein besonderer Tag! Wir haben so lange auf diesen Tag gewartet.\n Als die Uhr Mitternacht schlug, sind wir sofort losgerannt, um dein Geschenk zu holen! Wir haben mit Händlern gefeilscht und diese lästigen Filthoiden verjagt – alles nur, um dir diese kleine Überraschung zu bringen!\n Denn wir wollten die Allerersten sein, die sagen …\n Herzlichen Glückwunsch zum Geburtstag!\n Oh! Und du sollst dir jetzt etwas wünschen, oder? Äh ... Möge dein neues Jahr voller gemeinsamer Abenteuer sein, voller Spaß, den wir uns nicht einmal vorstellen können, und voller Geschichten über uns, die überall in Atlasia geschrieben werden!\n Warte mal – Ups! Das war unser Wunsch! Schnell, nochmal von vorn: Mach einen Wunsch in deinem Herzen! Was auch immer es ist, eines Tages wird er ganz sicher wahr werden!\n \n — Mit Liebe,\n Lunos von Atlasia"
        },
        Mail_Content_10014 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n du hast erfolgreich im Lunoloft eingecheckt. Bitte hole deine Belohnung ab."
        },
        Mail_Content_10016 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin}, \n im Anhang findest du Rebeccas Gedankenfragmente."
        },
        Mail_Content_10021 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n die Belohnungen für diese Aktion wurden deinem Konto zugestellt. Bitte hole sie in deiner Postfach ab.\n Wir wünschen dir eine angenehme Reise durch Atlasia!"
        },
        Mail_Content_100301 = {
          ContentDE = "Bei der Verteilung der Belohnungen ist ein Fehler aufgetreten. Die wiederhergestellten Belohnungen wurden zurückgefordert und ins Inventar geliefert."
        },
        Mail_Content_10031 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n Dein Monatspass läuft am <H>{Time}</> ab. Bitte hol dir deine Belohnungen rechtzeitig ab, damit du sie nicht verpasst."
        },
        Mail_Content_10032 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n  Die Gültigkeit von Bards Buch für diesen Zeitraum läuft am <H>{Time}</> ab. Bitte hol dir deine Belohnungen rechtzeitig ab, damit du sie nicht verpasst."
        },
        Mail_Content_10033 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n  Die Aktion [{EventName}] endet um <H>{Time}</> (Serverzeit). Bitte hol dir deine Belohnungen rechtzeitig ab, damit du sie nicht verpasst."
        },
        Mail_Content_10034 = {
          ContentDE = "Während die festliche Stimmung beim Festlichen Beisammensein wächst, möchte das Galea-Theater seinen Dank ausdrücken. Bitte nimm dieses kleine Dankeschön dafür an, dass du dazu beigetragen hast, Icelake wieder mit Leben zu füllen."
        },
        Mail_Content_10037 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n die täglichen Belohnungen für Verflochtene Gedanken wurden diesem Postfach hinzugefügt. Bitte rechtzeitig einsammeln."
        },
        Mail_Content_10038 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin}, deine verlorenen Belohnungen für die versteckten Missionen wurden wiederhergestellt. Da keine Belohnungswahl getroffen wurde, wurde eine automatisch ausgewählt und deinem Inventar hinzugefügt."
        },
        Mail_Content_100401 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin}, der neueste Band des Bards Buchs ist nun abgeschlossen. Alle nicht abgeholten Belohnungen wurden an dein Postfach gesendet. Vergiss nicht, sie einzusammeln!"
        },
        Mail_Content_100402 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin}, dein wiederholter Kauf des Bards Buchs wurde in Phoxene entsprechend dem Kaufwert erstattet. Vielen Dank für deine Geduld und dein Verständnis. Viel Spaß beim Spielen!"
        },
        Mail_Content_10055 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n die Belohnungen für diese Aktion wurden deinem Konto zugestellt. Bitte hole sie in deiner Postfach ab.\n Wir wünschen dir eine angenehme Reise durch Atlasia!"
        },
        Mail_Content_10056 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n vielen Dank für deine Teilnahme an den Mini-Programm-Aktion. Bitte hole deine Belohnungen in deiner Postfach ab."
        },
        Mail_Content_10058 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin}, \n vielen Dank für jedes einzelne „Like“, das du im DNArt-Fanwork-Contest vergeben hast. \n Deine Unterstützung lässt die Mühen unserer Kreativen noch heller strahlen! \n \n — Duet Night Abyss Operation Team"
        },
        Mail_Content_10059 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n die Belohnungen für diese Aktion wurden deinem Konto zugestellt. Bitte hole sie in deiner Postfach ab.\n Wir wünschen dir eine angenehme Reise durch Atlasia!"
        },
        Mail_Content_10060 = {
          ContentDE = "Dein Konto hat Unregelmäßigkeiten beim Erwerb von Gegenständen gezeigt. Um ein faires Spiel für alle Spieler zu gewährleisten, haben wir Ressourcen im Wert der durch unregelmäßige Mittel erhaltenen Gegenstände wiederhergestellt: {ResourceName} ×{Count}. Bitte halte dich an die Spielregeln. Weitere Verstöße führen zu verschärften Strafen."
        },
        Mail_Content_10061 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n dein <highlight>Team-Pass</> läuft bald ab. Bitte nutze ihn in der Aktion „Phoxjäger-Gipfel“ vor Ablauf. Nach Ablauf wird jeder Team-Pass in <highlight>1.000 Münzen</> umgewandelt."
        },
        Mail_Content_10062 = {
          ContentDE = "Sieht so aus, als hätte mein Hammer wirklich gewirkt! Das Theater hat bereits neue Kulissen aufgestellt — man kann das rhythmische Stampfen der Zuschauer durch den Saal hallen hören. Da habe ich mir gedacht… wenn ich im gleichen Rhythmus schmiede, würden die Klingen, die ich fertige, nicht noch anmutiger und lebendiger werden? Solange ich weiter schmiede und mein Handwerk verfeinere, wird der Tag kommen, an dem ich das Geheimnis deines Schwertes lüfte. Warte nur ab ..."
        },
        Mail_Content_10063 = {
          ContentDE = "Der Silvercandle-Karneval ist endlich vorbei. Was bedeutet… ich muss diese limitierten Getränke nicht mehr ausschenken. Die Leute haben ständig gesagt, dass sie sie lieben, aber in diesem Jahr ist meine Energie – genau wie der Karneval – endlich erschöpft. Ich werde ein paar Tage durchschlafen. Solange ich weg bin, kannst du gern beliebige Getränke mischen ... nur übertreib es nicht.\n Gute Nacht. Wir sehen uns in ein paar Tagen."
        },
        Mail_Content_10064 = {
          ContentDE = "Dieses Beisammensein im Galea-Theater ... es hat mich ein wenig zum Nachdenken gebracht. Ich war mir so sicher, dass das Ende jeden Moment kommen würde. Aber zu sehen, wie Menschen, die sonst so antriebslos wirkten, zusammen lachten, sobald sie sich versammelten, als hätten sie keine Sorge um eine Zukunft, in der vielleicht jeder ein Lunarian wird ... nun, das ließ mich überlegen, ob das Ende wirklich so schnell naht, wie ich dachte. Zumindest ... es wird wahrscheinlich drei Tage später eintreten, als ich vorhergesagt hatte!"
        },
        Mail_Content_10065 = {
          ContentDE = "Ich dachte immer, ein Ort wie ein Theater würde mir überhaupt nicht liegen. Aber nachdem ich mit Direktor Putsch gesprochen hatte, habe ich weit mehr gelernt, als ich erwartet hatte. Es stellt sich heraus, dass viele Opern auf den Geschichten von Entdeckern basieren – verlorene Schätze, alte Legenden, solche Geschichten ... Jetzt, wo der Karneval vorbei ist und jeder in Icelake etwas Neues gebrauchen kann, habe ich mich entschieden: Ich gehe zu den Orten, aus denen diese Geschichten stammen. Und wenn ich zurückkomme, werde ich noch mehr neugierige Geschichten mitbringen."
        },
        Mail_Content_10066 = {
          ContentDE = "Hast du das kleine rote Tuch auf der oberen linken Kerze der Kulisse gesehen? Das ist aus der Seide, die ich mitgebracht habe! Ich hoffe, es hilft dem Geschäft der Starweaver, auch wenn nur ein bisschen.\n Ich hatte vorher so viel über Icelake gehört, aber vieles entsprach überhaupt nicht meinen Vorstellungen.\n Das Opernhaus – ich dachte, es wäre wie die kleinen Bühnen, die unsere Huaxu-Truppen nutzen, aber es ist komplett anders! Ehrlich ... meine Augen kommen kaum hinterher.\n Wenn du jemals die Gelegenheit hast, Huaxu zu besuchen, lade ich dich zu einer Vorstellung ein!"
        },
        Mail_Content_101001 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n du hattest in der Aktion „%s“ noch nicht abgeholte Belohnungen. Diese wurden dir mit dieser Mail zugesandt. Bitte prüfe dein Postfach."
        },
        Mail_Content_102001 = {
          ContentDE = "{性别:Lieber Phoxjäger|Liebe Phoxjägerin},\n du hattest in der Aktion „Einsteigerleitfaden für Phoxjäger“ noch nicht abgeholte Belohnungen. Diese wurden dir mit dieser Mail zugesandt. Bitte prüfe dein Postfach."
        },
        Mail_Content_19101 = {
          ContentDE = "{性别:Kleiner Diener|Kleine Dienerin}! Hat ja lange genug gedauert. Ich war schon kurz davor, vor Warten grau zu werden! Ich habe alles für unser Phoxjäger-Team vorbereitet. Hier, nimm diesen Vorschuss, und lass uns unser Abenteuer durch den Kontinent Atlasia beginnen!"
        },
