        Mod_Upgrade_Tip = {
          ContentDE = "# erfüllt die Toleranzanforderungen nicht. Möchtest du den Dämonenkeil wirklich von # entfernen?"
        },
        Mon_DesDetail_10001001 = {
          ContentDE = "In Huaxu haben einige der Loongscions einen Bund mit den Neun Kapiteln von Dafeng geschlossen und wurden zu Hütern von Yingtian – Beschützer des Reiches. Erfüllt vom Mandat des Himmels, bestrafen sie die Bösen in seinem Namen. Für viele sind sie ehrfurchtgebietende Helden, für andere ein lebendiger Alptraum.\n Wie beim Zobel-Bi'an sind auch einige Hüter von Yingtian unter dem Einfluss der Plage von Zhuyin rasend geworden – ihr Amoklauf stellt nun eine Bedrohung für die öffentliche Sicherheit dar."
        },
        Mon_DesDetail_10002001 = {
          ContentDE = "Die ranghöchsten Vollstrecker Huaxus. In Huaxu haben einige der Loongscions einen Bund mit den Neun Kapiteln von Dafeng geschlossen und wurden zu Magistrate von Yingtian. Erfüllt vom Mandat des Himmels, bestrafen sie die Bösen in seinem Namen. Für viele sind sie ehrfurchtgebietende Helden, für andere ein lebendiger Alptraum."
        },
        Mon_DesDetail_10003001 = {
          ContentDE = "Einst Beschützer Huaxus, laufen diese Bestien nun Amok — ähnlich den Bi’an, jedoch von Kopf bis Schwanz in Schwarz gehüllt. Sie tauchten gemeinsam mit der Plage von Zhuyin auf, ihre Gedanken trübe und gewalttätig, eine Bedrohung für den Frieden des Alltags in Huaxu.\n Einige Gelehrte spekulieren, dass sie in Wahrheit Filthoiden sein könnten."
        },
        Mon_DesDetail_10004001 = {
          ContentDE = "Beschützer Huaxus und Vollstrecker des Willens der Neun Kapitel von Dafeng. Sie treten aus den schneidenden Winden hervor, um jene zu bestrafen, die gegen die heiligen Gebote der Neun Kapitel verstoßen.\n Einige Gelehrte spekulieren, dass sie in Wahrheit Filthoiden sein könnten."
        },
        Mon_DesDetail_10005001 = {
          ContentDE = "In Huaxu haben einige der Loongscions einen Bund mit den Neun Kapiteln von Dafeng geschlossen und wurden zu Hütern von Yingtian – Beschützer des Reiches. Erfüllt vom Mandat des Himmels, bestrafen sie die Bösen in seinem Namen. Für viele sind sie ehrfurchtgebietende Helden, für andere ein lebendiger Alptraum.\n Wie beim Zobel-Bi'an sind auch einige Hüter von Yingtian unter dem Einfluss der Plage von Zhuyin rasend geworden – ihr Amoklauf stellt nun eine Bedrohung für die öffentliche Sicherheit dar."
        },
        Mon_DesDetail_115 = {
          ContentDE = "Als Eliteeinheiten verfügen die Patrouillenfalken über die Autorität, reguläre Truppen zu befehligen, und können Alarmsignale weitergeben, um andere vor eindringenden Feinden zu warnen."
        },
        Mon_DesDetail_6001001 = {
          ContentDE = "Einer der am weitesten verbreiteten Filthoiden. Sie zeichnen sich dadurch aus, ihr Ziel im Sturm zu überrennen und es in Stücke zu reißen. Ihre gewaltigen Kiefer und Klauen galten einst als erhebliche Gefahr für Reisende. Während das Heulen eines Wolfs vielleicht noch eine Chance zur Flucht lässt, kündigt das heisere Brüllen eines Filthoid für Unbewaffnete oft einen unausweichlichen Tod an."
        },
        Mon_DesDetail_6002001 = {
          ContentDE = "Einer der am weitesten verbreiteten Filthoiden. Sie sind hervorragend in der Fernunterdrückung. Diese Kreaturen schleudern aus ihren gewehrähnlichen Armen überschüssiges hartes, anorganisches Material statt herkömmlicher Munition. Die Details ihrer Mutation bleiben ein Rätsel, doch ihre Anpassung an die moderne Zeit ist unverkennbar."
        },
        Mon_DesDetail_6003001 = {
          ContentDE = "Einer der am weitesten verbreiteten Filthoiden. Sie zeichnen sich durch ihre Unterstützung im Fernkampf aus. Oft in der Luft schwebend, haben ihre glatten, flexiblen Ranken einige dazu verleitet, sie unvorsichtigerweise als „niedlich“ zu bezeichnen. Wagemutige kulinarische Experimentatoren versuchten, sie zu Delikatessen zu verarbeiten – und bezahlten für ihre Naivität meist einen hohen Preis."
        },
        Mon_DesDetail_6004001 = {
          ContentDE = "Einer der am häufigsten vorkommenden großen Filthoiden. Sie zeichnen sich dadurch aus, Ziele mit ihrem mächtigen Körper zu vernichten. Trügerisch langsam und niedlich wirkend, besitzen sie eine zerstörerische Kraft, die selbst modernste Panzerungen durchdringen kann."
        },
        Mon_DesDetail_6005001 = {
          ContentDE = "Einer der am weitesten verbreiteten Filthoiden. Sie zeichnen sich darin aus, Gegner aus der Distanz zu stören. Diese Kreaturen tarnen sich durch harte, blütenblattartige Auswüchse und setzen klebrige, korrosive Sekrete ein. Sie lauern aus der Ferne und bereiten ihren Opfern einen anhaltenden Alptraum, dem man weder entkommen noch ihn abschütteln kann."
        },
        Mon_DesDetail_6006001 = {
          ContentDE = "Einer der am weitesten verbreiteten Filthoiden. Sie zeichnen sich beim Sammeln von Gegenständen aus. Oft mit mutierten Schwebe-Filthoiden verwechselt, streifen diese Kreaturen umher und verschlingen alles, was sie begehren. Ob sie von unstillbarem Phantomhunger getrieben werden oder lediglich die Gier widerspiegeln, die allen Kreaturen innewohnt, ist unbekannt."
        },
        Mon_DesDetail_6007001 = {
          ContentDE = "Einer der am weitesten verbreiteten Filthoiden. Sie sind hervorragend in der Eindämmung von Feinden. Diese Kreaturen hätten einst als Titanen des Denkens gegolten, die Brillanz in Worte fassten – statt ihre „Inspirationen“ in tatsächliche Flammen zu verwandeln."
        },
        Mon_DesDetail_6011001 = {
          ContentDE = "Einer der am weitesten verbreiteten mutierten Filthoiden. Sie zeichnen sich dadurch aus, ihr Ziel im Sturm zu überrennen und es in Stücke zu reißen. Ihre gewaltigen Kiefer und Klauen galten einst als erhebliche Gefahr für Reisende. Während das Heulen eines Wolfs vielleicht noch eine Chance zur Flucht lässt, kündigt das heisere Brüllen eines Filthoid für Unbewaffnete oft einen unausweichlichen Tod an."
        },
        Mon_DesDetail_6012001 = {
          ContentDE = "Einer der am weitesten verbreiteten mutierten Filthoiden. Sie sind hervorragend in der Fernunterdrückung. Diese Kreaturen schleudern aus ihren gewehrähnlichen Armen überschüssiges hartes, anorganisches Material statt herkömmlicher Munition. Die Details ihrer Mutation bleiben ein Rätsel, doch ihre Anpassung an die moderne Zeit ist unverkennbar."
        },
        Mon_DesDetail_6013001 = {
          ContentDE = "Einer der am weitesten verbreiteten mutierten Filthoiden. Sie sind hervorragend in der Fernunterdrückung. Oft in der Luft schwebend, haben ihre glatten, flexiblen Ranken einige dazu verleitet, sie unvorsichtigerweise als „niedlich“ zu bezeichnen. Wagemutige kulinarische Experimentatoren versuchten, sie zu Delikatessen zu verarbeiten – und bezahlten für ihre Naivität meist einen hohen Preis."
        },
        Mon_DesDetail_6014001 = {
          ContentDE = "Weit verbreitete große mutierte Filthoiden. Sie zeichnen sich dadurch aus, Ziele mit ihrem mächtigen Körper zu vernichten. Trügerisch langsam und niedlich wirkend, besitzen sie eine zerstörerische Kraft, die selbst modernste Panzerungen durchdringen kann."
        },
        Mon_DesDetail_6015001 = {
          ContentDE = "Eine Variante des Seelenbrennenden Filthoids, mutiert durch die vom Weihrauch geschwängerte Luft von Huaxu. Auf Behinderung und Eindämmung spezialisiert, wird es von Vorübergehenden oft für eine harmlose aromatische Pflanze gehalten. Einige Wesen, von der Plage von Zhuyin berührt, entzogen sich den Fesseln der Neun Kapitel von Dafeng und verwandelten sich in gefährliche Unheilsbringer."
        },
        Mon_DesDetail_6016001 = {
          ContentDE = "Eine Variante des Guerilla-Filthoids, mutiert durch die vom Weihrauch durchzogene Luft von Huaxu. Meisterhaft in der Unterdrückung auf große Distanz. Aus Rissen in seinen verknöcherten Unterarmen sprießen schlanke Zweige, an deren Spitzen sich feste Knospen bilden – sodass die Geschosse, die es abfeuert, einen unheimlichen, parfümierten Duft tragen. Einige Wesen, von der Plage von Zhuyin berührt, entzogen sich den Fesseln der Neun Kapitel von Dafeng und verwandelten sich in gefährliche Unheilsbringer."
        },
        Mon_DesDetail_6017001 = {
          ContentDE = "Eine Variante des Veloci-Filthoid, mutiert durch die vom Weihrauch geschwängerte Luft von Huaxu. Sein Kopf hat sich zu einer massiven, stigmaartigen Struktur verformt, die Beute verschlingen und zerreißen kann. Einige Wesen, von der Plage von Zhuyin berührt, entzogen sich den Fesseln der Neun Kapitel von Dafeng und verwandelten sich in gefährliche Unheilsbringer. Spezialisierte Gliedmaßen ermöglichen es ihm, sich mühelos an Wänden und Dachvorsprüngen festzuklammern. Eine Zeit lang stellten seine klaffenden Kiefer und rasiermesserscharfen Klauen eine schwere Bedrohung für Reisende dar."
        },
        Mon_DesDetail_7001001 = {
          ContentDE = "Die Standard-Scharfschützinnen der Hyperboreischen Legionen. Sie sind hervorragend in der Fernunterdrückung. Der Großteil der Legion besteht aus weiblichen Scharfschützinnen. Mit bemerkenswerter Ausdauer, Achtsamkeit und Ruhe leisten sie Feuerunterstützung aus der Distanz. Ihre maßgeschneiderten Tarnumhänge dienen nicht nur der effektiven Deckung, sondern auch als Abzeichen ihrer außergewöhnlichen Fähigkeiten."
        },
        Mon_DesDetail_7001005 = {
          ContentDE = "Das Ziel dieser Mission.\n Sie können in den Tarnung-Zustand übergehen, wodurch sie für Gegner nur schwer zu entdecken sind. Bei niedrigen LP können sie Köder beschwören, um Gegner zu verwirren."
        },
        Mon_DesDetail_7002001 = {
          ContentDE = "Die standardmäßigen Angriffstruppen der Hyperboreischen Legionen. Sie zeichnen sich im Nahkampf aus. Gekennzeichnet durch die markanten Gravuren auf ihrer Brustpanzerung, führen sie gewaltige Schwerter mit Geschick und zerschlagen alles, was sich ihnen in den Weg stellt."
        },
        Mon_DesDetail_7002005 = {
          ContentDE = "Das Ziel dieser Mission.\n Sie können Roboter einsetzen, die sie im Kampf unterstützen."
        },
        Mon_DesDetail_7003001 = {
          ContentDE = "Die standardmäßigen Expeditionstruppen der Hyperboreischen Legionen. Sie sind in unterschiedlichen Kampfdistanzen versiert, und ihre maßgeschneiderte schwere Rüstung bietet sowohl enormen Schutz als auch wichtige Unterstützung unter harschen Bedingungen. Es heißt, diese Truppen tauchten sogar in den entlegensten Wildnissen des Imperiums auf."
        },
        Mon_DesDetail_7003005 = {
          ContentDE = "Das Ziel dieser Mission.\n Sie können Landminen hinterlassen, um Feinde bei der Flucht vor einer Jagd zu behindern."
        },
        Mon_DesDetail_7004001 = {
          ContentDE = "Die standardmäßigen Sturmtruppen der Hyperboreischen Legionen, die an vorderster Front als Beschützer dienen. Sie zeichnen sich in der Nahaufklärung und in der Verteidigung gegen feindliche Angriffe aus. Ihre massiven Schilde, ein jahrhundertealter Standard, bleiben das Sinnbild ihrer Rolle."
        },
        Mon_DesDetail_7006001 = {
          ContentDE = "Sie können über dem Schlachtfeld schweben und verwundete Soldaten heilen. Sie basieren auf einem modularen Design, dessen zusammengesetzte Komponenten eine scheinbar autonome Funktionslogik ermöglichen. Ihre weitverbreitete Nutzung bestätigt eines der Grundprinzipien der Alchemie-Akademie: dass selbst wiederholte und mühsame Prozesse außergewöhnliche Wunder hervorbringen können."
        },
        Mon_DesDetail_7007001 = {
          ContentDE = "Die standardmäßigen Unterstützungsgeräte der Hyperboreischen Legionen. Sie können Gegner kurzzeitig aufhalten und einschränken. Sie basieren auf einem modularen Design, dessen zusammengesetzte Komponenten eine scheinbar autonome Funktionslogik ermöglichen. Ihre weitverbreitete Nutzung bestätigt eines der Grundprinzipien der Alchemie-Akademie: dass selbst wiederholte und mühsame Prozesse außergewöhnliche Wunder hervorbringen können."
        },
        Mon_DesDetail_7007002 = {
          ContentDE = "Diese Geräte können Gegner kurzzeitig abbremsen und unterdrücken. Sie basieren auf einem modularen Design, dessen zusammengesetzte Komponenten eine scheinbar autonome Funktionslogik ermöglichen. Ihre weitverbreitete Nutzung bestätigt eines der Grundprinzipien der Alchemie-Akademie: dass selbst wiederholte und mühsame Prozesse außergewöhnliche Wunder hervorbringen können."
        },
        Mon_DesDetail_7008001 = {
          ContentDE = "Die standardmäßigen Kommandanten der Hyperboreischen Legionen. Sie sind herausragend im Einzelkampf wie auch in der strategischen Führung. Sie haben außergewöhnliche Fähigkeiten im Kampf, in der Forschung oder im Kommando bewiesen. Ihre maßgefertigten Waffen, die auf verschiedene Distanzen ausgelegt sind, zeugen von ihrem Können und ihrem Rang. Auch wenn ihre Spezialisierungen variieren, bleibt ihre Loyalität zum Imperium unerschütterlich."
        },
        Mon_DesDetail_7009001 = {
          ContentDE = "Die standardmäßigen verstärkten Soldaten der Hyperboreischen Legionen. Sie zeichnen sich dadurch aus, feindliche Linien mit gnadenloser Effizienz zu durchbrechen. Gekleidet in die modernste Bewaffnung des Imperiums, gewährt durch die grenzenlose Gnade des Kaisers, zerlegen sie selbst die stärksten Verteidigungen. Kein Schlachtfeld ist zu verzweifelt, kein Preis zu hoch – sie erzwingen einen weiteren Sieg für den imperialen Ruhm."
        },
        Mon_DesDetail_7010001 = {
          ContentDE = "Die Spathatoi-Alchemisten, die mit den Hyperboreischen Legionen entsandt werden. Mehr als bloße Kriegsmagier, warten sie Waffen, versorgen die Verwundeten und erschaffen tödlichere Kriegsgeräte. Sie sind das Öl im Getriebe der imperialen Eroberung und sorgen dafür, dass die Kriegsmaschine niemals ins Stocken gerät."
        },
        Mon_DesDetail_7011001 = {
          ContentDE = "Die spezialisierten Scharfschützinnen der Hyperboreischen Legionen. Sie sind hervorragend in der Fernunterdrückung. Der Großteil der Legion besteht aus weiblichen Scharfschützinnen. Mit bemerkenswerter Ausdauer, Achtsamkeit und Ruhe leisten sie Feuerunterstützung aus der Distanz. Ihre maßgeschneiderten Tarnumhänge dienen nicht nur der effektiven Deckung, sondern auch als Abzeichen ihrer außergewöhnlichen Fähigkeiten."
        },
        Mon_DesDetail_7012001 = {
          ContentDE = "Die spezialisierten Angriffstruppen der Hyperboreischen Legionen. Sie zeichnen sich im Nahkampf aus. Gekennzeichnet durch die markanten Gravuren auf ihrer Brustpanzerung, führen sie gewaltige Schwerter mit Geschick und zerschlagen alles, was sich ihnen in den Weg stellt."
        },
        Mon_DesDetail_7013001 = {
          ContentDE = "Die standardmäßigen Expeditionstruppen der Hyperboreischen Legionen. Sie sind in unterschiedlichen Kampfdistanzen versiert, und ihre maßgeschneiderte schwere Rüstung bietet sowohl enormen Schutz als auch wichtige Unterstützung unter harschen Bedingungen. Es heißt, diese Truppen tauchten sogar in den entlegensten Wildnissen des Imperiums auf."
        },
        Mon_DesDetail_7014001 = {
          ContentDE = "Die spezialisierten Sturmtruppen der Hyperboreischen Legionen, die an vorderster Front als Beschützer dienen. Sie zeichnen sich in der Nahaufklärung und in der Verteidigung gegen feindliche Angriffe aus. Sie zeichnen sich in der Nahaufklärung und in der Verteidigung gegen feindliche Angriffe aus. Ihre massiven Schilde, ein jahrhundertealter Standard, bleiben das Sinnbild ihrer Rolle."
        },
        Mon_DesDetail_7015001 = {
          ContentDE = "Die standardmäßigen Unterstützungsgeräte der Hyperboreischen Legionen. Sie können Gegner kurzzeitig aufhalten und einschränken. Es handelt sich um eine verbesserte Variante der Magnetdrohnen, basierend auf Seelenbrennende Filthoiden, die auf einem modularen Design fußt, dessen zusammengesetzte Elemente eine scheinbar autonome Funktionslogik ermöglichen. Ihre weitverbreitete Nutzung bestätigt eines der Grundprinzipien der Alchemie-Akademie: dass selbst wiederholte und mühsame Prozesse außergewöhnliche Wunder hervorbringen können."
        },
        Mon_DesDetail_7016001 = {
          ContentDE = "Die standardmäßigen Fluggeräte der Hyperboreischen Legionen. Durch bahnbrechende Fortschritte im militärischen Ingenieurswesen begann eine neue Ära unkonventioneller Bewaffnung. Entworfen vom Aeolipile steht das Auge der Legion für den imperialen Anspruch, den Himmel zu beherrschen."
        },
        Mon_DesDetail_8001001 = {
          ContentDE = "Die regulären Schützen der Elysischen Kirche. Sie sind Meister der Fernkampfunterdrückung. Disziplinierte Formationen stehen für sie über Hinterhalten; sie stellen sich ihren Feinden offen und geordnet, statt aus dem Schatten heraus zu feuern. In Reih und Glied geben sie auf Befehl ihres Anführers Salven ab und opfern Fleisch und Blut für Gott, während sie Sein Urteil vollstrecken."
        },
        Mon_DesDetail_8002001 = {
          ContentDE = "Die regulären Stoßtruppen der Elysischen Kirche. Sie sind im Nahkampf unübertroffen, führen silberne Stichschwerter und bringen den Zorn Gottes im Gefecht aus nächster Nähe. Ihr gesegnetes Kettenhemd, durch den Glauben gestärkt, bewahrt sie vor Unheil. Alchemisten versuchten einst, das Geheimnis ihrer außergewöhnlichen Schutzkraft zu ergründen – und stellten überrascht fest, dass es aus gewöhnlichem Eisen besteht."
        },
        Mon_DesDetail_8003001 = {
          ContentDE = "Die regulären Priester der Elysischen Kirche. Sie zeichnen sich durch ihre Unterstützung im Fernkampf aus. Die Verse, die sie unablässig rezitieren, hüllen das Schlachtfeld ein, sobald sie durch ihre besonderen Masken gesprochen werden, und stärken die Gläubigen Elysiums. Man sagt, selbst ein Stummer könne von Gott erhört werden, solange seine Hingabe groß genug ist und er diese Maske trägt."
        },
        Mon_DesDetail_8500001 = {
          ContentDE = "Die Großkommandantin der 13. Legion des Imperiums. Eine furchterregende Macht mit unbekannten Motiven und unerschütterlichem Willen, Berenica zurückzuerobern."
        },
        Mon_DesDetail_8501001 = {
          ContentDE = "Mit außergewöhnlicher Widerstandskraft gesegnet, hat dieses Wesen unzählige Schlachten überstanden und selbst schwerste Wunden überlebt. Die gezackten Klingen und Narben, die es trägt, haben es nicht gebrochen – im Gegenteil: Sie haben seine Stärke nur gemehrt und es zu einem noch finstereren Vorboten des Untergangs geformt."
        },
        Mon_DesDetail_8502001 = {
          ContentDE = "Der Same im gefrorenen Boden, der seine Chance auf ein sanftes Vergehen in der Nacht verloren hat."
        },
        Mon_DesDetail_8503001 = {
          ContentDE = "Ein gigantischer Filthoid in den Tiefen der Glevum-Grube, der mechanisch immer wieder gräbt und alles verschlingt, was leuchtet."
        },
        Mon_DesDetail_8505001 = {
          ContentDE = "Die Wächterin des imperialen Militärgefängnisses schwingt ihre Ketten, um das Böse zu bestrafen, und ihre Flammen, um die Gerechtigkeit zu verteidigen."
        },
        Mon_DesDetail_8509001 = {
          ContentDE = "Der scharlachrote Umhang erzittert, während die eisige Brise ein Klagelied der Schneefelder anstimmt."
        },
        Mon_DesDetail_8510001 = {
          ContentDE = "Gesetz, geschmiedet aus dem Herzen. Die Schneidfäule verhüllt den Himmel in Schatten."
        },
        Mon_DesDetail_8511001 = {
          ContentDE = "Gesetz, ausgerichtet durch die Vernunft. Ein kaltes Licht bindet die unzähligen Reiche."
        },
        Mon_DesDetail_8512001 = {
          ContentDE = "Es ist das Biest aus dem Schneefeld, das Kinderheimstätten zertrümmert und die letzten Überreste des Feenschlafs zum Schmelzen bringt."
        },
        Mon_DesDetail_8513001 = {
          ContentDE = "Um die Gnade der Götter anzurufen, ritzen die Göttlichen Herolde heilige Worte in ihre Haut. Im Strahlen des Glaubens verwandelt sich Leid in heilige Gnade."
        },
        Mon_DesDetail_8514001 = {
          ContentDE = "Für manche Göttlichen Herolde sind das Predigen der Wahrheit und die Läuterung des Glaubens heilige Berufungen. Selbst Feuer und Blei werden, im Dienst der Hingabe geführt, zu Ausdrücken göttlicher Gnade."
        },
        Mon_DesDetail_8515001 = {
          ContentDE = "Der Verschlinger ist kein einzelner Filthoid, sondern eine groteske Verschmelzung – ein wimmelndes Bündel aus zusammengewachsenem Fleisch, das Tiere, Pflanzen, Filthoiden und sogar Menschen verschlingt. Mit roher Gewalt assimilieren sie alles in ihren ständig wachsenden, entstellten Körper und jagen ewig nach dem nächsten elenden Bestandteil."
        },
        Mon_DesDetail_9001001 = {
          ContentDE = "Mitglieder der Verlassenen, Stufe „Wildschwarm“. Sie zeichnen sich im Nahkampf aus. Einst gewöhnliche Charons, nun zu Kriegern geworden, mangelt es ihren Kampftechniken an Feinschliff, doch ihre in Blut geschmiedete Wut wird zur Klinge, die Ketten zerschmettert und den Hammerhieb des Feindes bricht."
        },
        Mon_DesDetail_9002001 = {
          ContentDE = "Mitglieder der Verlassenen, Stufe „Wildschwarm“. Sie sind hervorragend in der Fernunterdrückung. Fernunterdrückung und Belästigung zählen zu ihren Stärken. Wer ihre Wacht stört, trifft nicht nur auf kalte Blicke – sondern auf Pfeile aus blinden Winkeln, die dort treffen, wo Achtsamkeit nachlässt."
        },
        Mon_DesDetail_9003001 = {
          ContentDE = "Mitglieder der Verlassenen, Stufe „Rabe“. Sie beherrschen die Manipulation ihrer Umgebung und das Aufstellen von Fallen. Das Leben als Spiel betrachtend, treten diese „Spielzeugmacher“ in einem tödlichen Wettlauf mit der Zerstörung an, wobei sie ihr eigenes Leben als Einsatz riskieren. Sie verwandeln das Schlachtfeld in ihren persönlichen „Spielplatz“, legen unzählige Fallen aus und beobachten die Akteure, von denen einige den Klauen der Vernichtung entkommen. Sie arbeiten typischerweise mit den „Betrügern“ und den „Sprengfanatikern“ zusammen, um ihre Offensiven abzustimmen."
        },
        Mon_DesDetail_9005001 = {
          ContentDE = "Mitglieder der Verlassenen, Stufe „Rabe“. Sie sind wahre Meister im Umgang mit Sprengstoffen. Berühmt für ihre Hingabe an die Kunst der Explosionen, perfektionieren diese „Sprengfanatiker“ ihre Bomben bis zum letzten Moment vor der Detonation. Dieses unermüdliche Streben nach Perfektion erklärt, warum ihre Bomben kurz vor der Katastrophe anfälliger sind. Sie arbeiten typischerweise mit den „Betrügern“ und den „Spielzeugmachern“ zusammen, um ihre Offensiven abzustimmen."
        },
        Mon_DesDetail_9006001 = {
          ContentDE = "Mitglieder der Verlassenen, Stufe „Rabe“. Sie sind geschickt darin, feindliche Formationen zu stören und Chaos auf dem Schlachtfeld zu säen. Die als „Betrüger“ bekannten Wesen sind Meister der Manipulation und Täuschung. Sie nutzen Fehlinformationen, um Gegner gegeneinander auszuspielen und das Chaos auf dem Schlachtfeld zu verstärken. Mit spöttischem Grinsen genießen sie das weitreichende Unheil, das sie verursachen, oft auf Kosten von Leben, einschließlich ihres eigenen. Sie arbeiten typischerweise mit den „Sprengfanatikern“ und den „Spielzeugmachern“ zusammen, um ihre Offensiven abzustimmen."
        },
        Mon_DesDetail_9007001 = {
          ContentDE = "Mitglieder der Verlassenen, Stufe „Wildschwarm“. Sie zeichnen sich durch ihre Unterstützung im Fernkampf aus. Keine Operation der Verlassenen entfaltet sich, ohne dass ihre Agenten wie Geister Befehle flüstern und mit Informationen vom Schlachtfeld zurückkehren wie Botenfalken. Durch die dunkelsten Gassen des Imperiums bewegen sie sich und spinnen ein unsichtbares Netz aus Flüstern, das jedes Mitglied der Verlassenen verbindet."
        },
        Mon_DesDetail_9500001 = {
          ContentDE = "Ein berüchtigter und schwer fassbarer Meisterbandit!"
        },
        Mon_DesDetail_9501001 = {
          ContentDE = "Der verdächtige junge Mann voraus ist der Dieb, der Margies Geldbeutel gestohlen hat. Pack ihn jetzt!"
        },
        Mon_DesDetail_9801001 = {
          ContentDE = "Die nördliche Unterart wilder Wölfe hat sich mit blassen Winterfellen und verlängerten Gliedmaßen an die gefrorenen Weiten angepasst. Wenn du in der Wildnis „sich bewegende Schneeverwehungen“ bemerkst, weißt du, dass du längst von diesen meisterhaften Jägern umzingelt bist."
        },
        Mon_DesDetail_9802001 = {
          ContentDE = "Eine uralte und seltene Spezies, deren Legenden von Kreaturen berichten, deren Blick Epochen überdauert hat. Ihre Geweihe, getränkt im Blut vergessener Kriege, tragen das Gewicht von Kontinenten, die aufgestiegen und gefallen sind."
        },
        Mon_DesDetail_9803001 = {
          ContentDE = "Diese hyperadaptiven Nagetiere mutieren schneller, als Städte vergessen können. Sie gedeihen in den dunklen Ecken der Städte und nagen an den Geheimnissen, die wir unter Beton begraben."
        },
        Mon_DesDetail_9804001 = {
          ContentDE = "Ein Wasservogel, nur in Huaxu zu finden, gekennzeichnet durch lange Federn auf dem Kopf. Er ernährt sich von Fischen, jagt, indem er reglos auf einem Bein im flachen Wasser steht und mit seinem Schnabel zuschlägt, sobald Beute zu nah driftet. Sein Name rührt von seiner Ähnlichkeit mit einem Fischer her, der an seiner Angel posiert."
        },
        Mon_DesDetail_9805001 = {
          ContentDE = "Ein bodenbewohnender Vogel, nur in Huaxu zu finden. Obwohl seine Flügel zu klein für dauerhaftes Fliegen sind, kann er bemerkenswerte Distanzen gleiten. Zur richtigen Jahreszeit fächern die Männchen ihre Schwänze zur Balz – obwohl beide Geschlechter dasselbe leuchtende smaragdgrüne Gefieder tragen."
        },
        Mon_DesDetail_9806001 = {
          ContentDE = "Ein kleines Wildschwein, benannt nach seinem kompakten Körperbau. Sein Fleisch ist zart und fein, ohne den Wildgeschmack größerer Wildschweine – eine Delikatesse, mit der die Menschen Huaxus ihre Gäste ehren."
        },
        Mon_DesDetail_9807001 = {
          ContentDE = "Wenn du nach Einbruch der Abenddämmerung in Huaxu ein langgezogenes, schwankendes „Yip ... Yaaah“ hörst, ist es fast sicher ein Fuchs. Hühnerhüter stehen auf, um ihre Ställe zu kontrollieren; Jäger schleichen sich ins Dunkel. Doch Füchse sind Meister von Täuschung und Irreführung – ein Fang ist niemals garantiert."
        },
        Mon_DesDetail_9808001 = {
          ContentDE = "Ein großer Hirsch, nur in Huaxu zu finden, oft zu sehen beim Durchstreifen von Ebenen und bewaldeten Hängen. Die wolkenweiche Halskrause verleiht ihm seinen Namen. Sanftmütig von Natur aus – doch sollte man ihn nicht reizen, es sei denn, die Rippen können der vollen Wucht seiner Geweihe standhalten."
        },
        Mon_DesDetail_9809001 = {
          ContentDE = "Ein häufiger Singvogel Huaxus mit einem melodischen Ruf und rundem, fülligem Körper. Oft beim Hüpfen auf Ästen oder beim Herumlaufen am Boden zu beobachten. Ein von den Einheimischen sehr geschätztes Geschöpf."
        },
        Mon_FirstSeen_Label = {
          ContentDE = "Neuer Gegner"
        },
        Mon_Guide_115_01 = {
          ContentDE = "<Highlight>Patrouillenfalke</> sind Elite-Soldaten, ausgewählt aus den Patrouillen. Patrouillenfalke werden wachsam, wenn Feinde sich nähern, und lassen die Wachsamkeit allmählich nach, wenn die Bedrohung abnimmt."
        },
        Mon_Guide_115_02 = {
          ContentDE = "Wenn ein <Highlight>Patrouillenfalke</> zu lange wachsam bleibt, löst er <Highlight>Alarm</> aus und startet einen <Highlight>Countdown für eine Geiselnahme-Exekution</>."
        },
        Mon_Guide_6006001_01 = {
          ContentDE = "Wenn ein <Highlight>Träger-Filthoid</> handlungsunfähig wird, hinterlässt er ein <Highlight>Exkavator-Modul</>, das den Exkavator am Laufen hält."
        },
        Mon_Guide_6007001_01 = {
          ContentDE = "<Highlight>Seelenbrennender Filthoid</> explodiert beim Besiegtwerden und verursacht AoE-Schaden an verbündeten und feindlichen Zielen im Wirkungsbereich."
        },
        Mon_Guide_6015001_01 = {
          ContentDE = "<Highlight>Ascheblüte-Filthoid</> verursacht beim Besiegtwerden eine Explosion, die Flächenschaden an nahen verbündeten und feindlichen Einheiten zufügt."
        },
        Mon_Guide_7001005_01 = {
          ContentDE = "<Highlight>Scharfschützen-Soldat – Tarnung</> tritt periodisch in die [Tarnung] ein und erhöht die Bewegungs-GES für 4 Sek."
        },
        Mon_Guide_7001005_02 = {
          ContentDE = "Wenn <Highlight>Scharfschützen-Soldat – Tarnung</> unter 80 % seiner max. LP Schaden erleidet, wechselt es in die [Tarnung] und beschwört mehrere identische [Köder].\n[Köder]: Sehen aus wie <Highlight>Scharfschützen-Soldat – Tarnung,</> erleiden jedoch erhöhten Schaden.\n Wenn einer der [Köder] besiegt wird, wird <Highlight>Scharfschützen-Soldat – Tarnung</> mit [Trägheit] belegt. [Trägheit]: Reduziert die Bewegungs-GES für #2 s."
        },
        Mon_Guide_7002005_01 = {
          ContentDE = "Wenn <Highlight>Hackbeil-Soldat – Kampferprobt</> in den Kampf eintritt, setzt er eine <Highlight>[Heildrohne]</> ein und ruft periodisch eine <Highlight>[Magnetdrohne]</> zur Unterstützung herbei."
        },
        Mon_Guide_7002005_02 = {
          ContentDE = "<Highlight>Heildrohne</>: Verbindet kontinuierlich <Highlight>Hackbeil-Soldat – Kampferprobt</>.\n \nDas verbundene Ziel erhält Boosts auf Bewegungs-GES und ANG und regeneriert kontinuierlich LP."
        },
        Mon_Guide_7002005_03 = {
          ContentDE = "<Highlight>Magnetdrohne</>: Jagt feindliche Ziele und zerstört sich selbst. Bei der Selbstzerstörung erzeugt sie [Magnetsturm] um sich herum.\n [Magnetsturm]: Verursacht Schaden und belegt feindliche Ziele im Wirkungsbereich mit [Trägheit]. [Trägheit]: Reduziert die Bewegungs-GES für #1 s. Verursacht Schaden und belegt Ziele im Wirkungsbereich mit [Lähmung]. [Lähmung]: Ziele können sich #2 s lang weder bewegen noch angreifen."
        },
        Mon_Guide_7003005_01 = {
          ContentDE = "<Highlight>Expeditions-Soldat – Bewaffneter Angriff</> platziert periodisch eine [Landmine] an seinem aktuellen Standort."
        },
        Mon_Guide_7003005_02 = {
          ContentDE = "[Landminen] werden aktiviert, wenn feindliche Einheiten ihren Bereich betreten, und detonieren nach kurzer Verzögerung, verursachen Schaden und belegen nahe feindliche Einheiten mit [Trägheit]. [Trägheit]: Verringert die Bewegungs-GES für #1 s."
        },
        Mon_Guide_7007002_01 = {
          ContentDE = "Einige <Highlight>Magnetdrohnen II</> nähern sich Fahrzeugen und explodieren, verursachen erheblichen Schaden an Fahrzeugen und anderen feindlichen Zielen im Wirkungsbereich."
        },
        Mon_Guide_7008001_01 = {
          ContentDE = "Elitesergeant kann <Highlight>Moral-Boost</> einsetzen, um Verbündete in seiner Nähe zu inspirieren."
        },
        Mon_Guide_7008001_02 = {
          ContentDE = "Bei Inspiration durch den Sergeant erhalten Verbündete [Hohe Moral]. [Hohe Moral]: Erhöht Bewegungs-GES und verursachten Schaden, reduziert erlittenen Schaden."
        },
        Mon_Guide_7008001_03 = {
          ContentDE = "Wenn der Elitesergeant <Highlight>besiegt</> wird, verlieren Verbündete den Effekt [Hohe Moral]."
        },
        Mon_Guide_7015001_01 = {
          ContentDE = "<Highlight>Wachdrohne</> explodiert beim Besiegtwerden und verursacht AoE-Schaden an verbündeten und feindlichen Zielen im Wirkungsbereich."
        },
        Mon_Guide_8501002_01 = {
          ContentDE = "Berüchtigt wild, nutzen <Highlight>Kriegsveteranen</> ihre abnormen Fähigkeiten, um ihre Ziele unablässig zu verfolgen, sobald der Kampf beginnt."
        },
        Mon_Guide_8515001_01 = {
          ContentDE = "Wenn der <Highlight>Verschlinger</> <Highlight>Sporenexplosion</> oder <Highlight>Sengender Atem</> einsetzt, ziele auf seinen <Highlight>leuchtenden Kopf</> um ihn kurzzeitig außer Gefecht zu setzen."
        },
        Mon_Guide_9003001_01 = {
          ContentDE = "<Highlight>Spielzeugmacher</> gehören zu den „Soldaten“ der Verlassenen. Sie beherrschen die Manipulation ihrer Umgebung und das Aufstellen von Fallen.\n In <Highlight>„Mission: Vermittlung“</>, erscheinen nach der Niederlage eines Spielzeugmachers <Highlight>Sprungpads</> auf dem Rückzugsweg, um den Rückzug zu erleichtern."
        },
        Mon_Guide_9005001_01 = {
          ContentDE = "<Highlight>Sprengfanatiker</> gehören zu den „Soldaten“ der Verlassenen. Sie sind wahre Meister im Umgang mit Sprengstoffen.\n In <Highlight>„Mission: Vermittlung“</>, wird nach der Niederlage eines Sprengfanatikers die max. LP des <Highlight>Großen Feuerwerks</> um 30 % reduziert."
        },
        Mon_Guide_9006001_01 = {
          ContentDE = "<Highlight>Betrüger</> gehören zu den „Soldaten“ der Verlassenen. Sie sind geschickt darin, feindliche Formationen zu stören und Chaos auf dem Schlachtfeld zu säen.\n In <Highlight>„Mission: Vermittlung“</>werden nach der Niederlage eines Betrügers keine Elite-Feinde mehr gespawnt."
        },
        Mon_Guide_9500001_01 = {
          ContentDE = "<Highlight>Luno-Plündererin</> erscheint nur kurz, bevor sie versucht zu fliehen. Besiege sie schnell, um einen reichhaltigen Schatz zu sichern."
        },
        Mon_Guide_Strong_Blood_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Verfall</> erzeugt periodisch einen [Fäulnissumpf] um sich herum."
        },
        Mon_Guide_Strong_Blood_02 = {
          ContentDE = "[Fäulnissumpf]: Verursacht DoT an Feinden im Radius und heilt gleichzeitig Verbündete innerhalb des Bereichs."
        },
        Mon_Guide_Strong_Burst_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Explosion</> löst periodisch eine Explosion um sich selbst aus, die nahe feindliche Einheiten in die Luft schleudert."
        },
        Mon_Guide_Strong_Fade_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Verwelkung</> entfesselt periodisch 3 rotierende [Welkstrahlen]. [Welkstrahl]: Hält 10 Sek. an. Kreist um den Primarch, verursacht bei Kontakt Schaden an Zielen und reduziert deren Geist."
        },
        Mon_Guide_Strong_Frozen_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n Wenn <Highlight>Primarch – Frostbiss</> von einer Fernkampfwaffe getroffen wird, kontert es, indem es Eiszapfen auf den Angreifer schleudert, Schaden verursacht und 1 Stapelung von [Langsamkeit] anwendet. [Langsamkeit]: Reduziert Angriffsgeschwindigkeit und Bewegungs-GES für #1 s, bis zu #2-mal stapelbar."
        },
        Mon_Guide_Strong_IceOrb_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Eishölle</> beschwört periodisch ein [Eishölle] unter feindlichen Zielen. [Eishölle]: Verlangsamt Ziele innerhalb des Radius und detoniert nach #1 s, wobei AoE-Schaden an allen feindlichen Zielen im Wirkungsbereich verursacht wird."
        },
        Mon_Guide_Strong_Kamikaze_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Opfer</> verursacht beim Besiegtwerden eine Explosion, die allen feindlichen Zielen im Wirkungsbereich Schaden zufügt."
        },
        Mon_Guide_Strong_Multiple_01 = {
          ContentDE = "Einige Primarchen besitzen mehrere <Highlight>Primarch-Fähigkeiten</>."
        },
        Mon_Guide_Strong_Poison_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Korrosion</> erzeugt periodisch eine [Toxin]-Lache unter seinen Füßen. [Toxin]: Reduziert VTD und verursacht DoT bei Zielen im Wirkungsbereich.\n Zusätzlich beschleunigt <Highlight>Primarch – Korrosion</> während seines Lebens den Verfall von Serum."
        },
        Mon_Guide_Strong_Reflect_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Glimmer</> wendet periodisch [Glimmer] auf sich selbst an. [Glimmer]: Hält #1 s an. Während dieser Zeit löst er bei Schaden eine Explosion aus, die AoE-Schaden an feindlichen Zielen im Wirkungsbereich verursacht."
        },
        Mon_Guide_Strong_Revenge_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Rache</> verleiht beim Besiegtwerden nahen verbündeten Zielen [Verstärkung]. [Verstärkung]: Erhöht ATK, VTD, Bewegungs-GES und Angriffs-GES für #1 s."
        },
        Mon_Guide_Strong_Shield_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Schutz</> beschwört periodisch ein [Schutzfeld] um sich herum. [Schutzfeld]: Hält #1 s an und blockiert alle eingehenden feindlichen Kugeln und Projektile."
        },
        Mon_Guide_Strong_Threefold_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Phantom</> beschwört nach Kampfbeginn #1 [Phantom]. [Phantom]: Erleidet erhöhten Schaden und nutzt die Kampffähigkeiten des Beschwörers."
        },
        Mon_Guide_Strong_ThunderLaser_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Gewittersturm</> beschwört periodisch mehrere [Donnerhöllen] um sich herum. [Donnerhölle]: Dreht sich unaufhörlich über das Schlachtfeld und verursacht Schaden an allen feindlichen Zielen bei Kontakt."
        },
        Mon_Guide_Strong_Thunder_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Donnerschlag</> entlässt periodisch [Elektro-Kugeln], die nach außen strahlen. [Elektro-Kugel]: Entlädt alle #1 s, Elektrizität und verursacht Schaden an nahe gelegenen feindlichen Zielen. Verschwindet, nachdem es getroffen wurde."
        },
        Mon_Guide_Strong_Vampire_01 = {
          ContentDE = "Primarchen sind mächtige Wesen unter den feindlichen Kräften, die über einzigartige <Highlight>Primarchen-Fähigkeiten</> verfügen.\n <Highlight>Primarch – Blutbad</> stellt seine eigene LP wieder her, wenn es Schaden verursacht."
        },
        Mon_Guide_Title_115 = {
          ContentDE = "Patrouillenfalke"
        },
        Mon_Guide_Title_6006001 = {
          ContentDE = "Träger-Filthoid"
        },
