        Mon_Name_9810001 = {ContentDE = "Seevoogel"},
        MonsterRushEvent_Wuyou_DungeonDes01 = {
          ContentDE = "Ein mysteriöser, schwerttragender Wishen taucht plötzlich auf und versperrt dir den Weg. Vielleicht spürt er dein Talent und möchte dir einen oder zwei Tricks zeigen.\n „Pass gut auf. Ich zeige es nur einmal.“"
        },
        MonsterRushEvent_Wuyou_DungeonDes02 = {
          ContentDE = "Sonnenstrahlen fallen durch das Blätterdach, ein Windhauch streift dein Haar. Als erinnere sich der kleine Wishen an einen fernen Nachmittag, gähnt er ausgiebig.\n ... Moment, gähnen Wishen überhaupt?"
        },
        MonsterRushEvent_Wuyou_DungeonDes03 = {
          ContentDE = "Der eifrige Schwertkämpfer, der träge Hirte – ihr lautstarkes Streitgespräch hallt in deinen Ohren. Hoffentlich nehmen sie dich am Ende nicht ins Visier, du fröhlicher Reisender, gefangen in ihrem ausgelassenen Gezänk."
        },
        MonsterRushEvent_Wuyou_DungeonDes04 = {
          ContentDE = "Ein Talismanschein ... zwei ... drei ... Du siehst zu, wie der Wishen immer neue Zettel aus seinem Rücken zieht, wie ein Bühnenmagier, der unendlich viele Karten aus dem Ärmel fächert.\n „Nicht dieser ... auch nicht jener ... Wo ist mein Blitz-Talisman nur?“"
        },
        MonsterRushEvent_Wuyou_DungeonDes05 = {
          ContentDE = "Gemächlich legt dir ein Wishen seinen Strohhut in die Hände und bittet dich, ihn sicher aufzubewahren.\n Im nächsten Moment glaubst du, eine Gestalt in Anzug, die eine Axt hält, aus dem Schatten steigen zu sehen, die brüllt „Wer will sonst noch?“"
        },
        MonsterRushEvent_Wuyou_DungeonDes06 = {
          ContentDE = "Man sagt, Wishen entstehen aus unerfüllten Sehnsüchten. Du wirfst nicht nur einen Blick auf die still umher schwebenden Gefährten.\n Welche unerfüllte Wunschvorstellung hält sie wohl in dieser Welt gefangen?"
        },
        MonsterRushEvent_Wuyou_DungeonDes07 = {
          ContentDE = "Wenn Verschwinden Loslassen bedeutet, kennt die Welt der Wishen keine traurigen Abschiede.\n In den Farben der Seele schimmernde, wunderliche Geister versammeln sich hier – und morgen wird, wie immer, ein Tag voller Lärm und Wunder sein."
        },
        MonsterRushEvent_Wuyou_DungeonName01 = {
          ContentDE = "Lektionen des namenlosen Schwertkämpfers"
        },
        MonsterRushEvent_Wuyou_DungeonName02 = {
          ContentDE = "Das Gähnen des verwirrten Hirtenjungen"
        },
        MonsterRushEvent_Wuyou_DungeonName03 = {
          ContentDE = "Eine ausgelassene Farce"
        },
        MonsterRushEvent_Wuyou_DungeonName04 = {
          ContentDE = "Unerschöpfliche Zaubertricks"
        },
        MonsterRushEvent_Wuyou_DungeonName05 = {
          ContentDE = "Der gemächliche Wahnsinnige"
        },
        MonsterRushEvent_Wuyou_DungeonName06 = {
          ContentDE = "Prüfung der verschwommenen Träume"
        },
        MonsterRushEvent_Wuyou_DungeonName07 = {
          ContentDE = "Ein unbeschwerter Morgen"
        },
        MonsterRushEvent_Wuyou_PetDesc_1 = {
          ContentDE = "Ein Wishen, der zerstörerische Talismane mühelos einsetzt – das eigentliche Rätsel ist allerdings, woher er sie überhaupt hervorzieht."
        },
        MonsterRushEvent_Wuyou_PetDesc_2 = {
          ContentDE = "Er wirkt ruhig und gefasst – doch wehe dem, der ihn reizt: Die Folgen könnten weit über das Erwartete hinausgehen."
        },
        MonsterRushEvent_Wuyou_PetDesc_3 = {
          ContentDE = "Ein Meister des Schwertflugs. Seine Klingen treiben und wirbeln mit müheloser Anmut – die perfekte Kulisse für ein Foto, wenn er sie nur ausleihen würde."
        },
        MonsterRushEvent_Wuyou_PetDesc_4 = {
          ContentDE = "Er gleitet stets mit leichter, unbeschwerter Grazie dahin, und wenn du dich niedergeschlagen fühlst, könnte eine sanfte Berührung von ihm deine Stimmung heben."
        },
        MonsterRushEvent_Wuyou_PetName_1 = {
