        One = {ContentDE = "1"},
        PET_401_PASSIVE = {
          ContentDE = [[
Die Hauptfigur und die Kampfbegleiter erhalten:
 Umbro-ANG +#1, Max. LP +#2]]
        },
        PET_401_SKILL = {
          ContentDE = "Verursacht Umbro-SCH in Höhe von #1 des ANG der Hauptfigur an Gegnern innerhalb der Reichweite, mit einem zusätzlichen zufälligen attributbasierten Effekt für #2 Sek."
        },
        PET_402_PASSIVE = {
          ContentDE = [[
Die Hauptfigur und die Kampfbegleiter erhalten:
 Hydro-ANG +#1, Max. LP +#2]]
        },
        PET_402_SKILL = {
          ContentDE = "Erhöht den ANG für sich selbst und Verbündete um #1 für #2 Sek."
        },
        PET_403_PASSIVE = {
          ContentDE = [[
Die Hauptfigur und die Kampfbegleiter erhalten:
 Pyro-ANG +#1, Max. LP +#2]]
        },
        PET_403_SKILL = {
          ContentDE = "Stellt #1 Punkte Geist für sich selbst und Verbündete wieder her."
        },
        PET_404_PASSIVE = {
          ContentDE = [[
Die Hauptfigur und die Kampfbegleiter erhalten:
 Elektro-ANG +#1, Max. LP +#2]]
        },
        PET_404_SKILL = {
          ContentDE = "Gewährt sich selbst und Verbündeten #2 Punkte Ultra-Schild und wendet zufällig einen der folgenden Effekte für #1 Sek. an: +#3 ANG, +#4 VTD, +#5 Fähigkeits-SCH oder +#6 Fähigkeitsdauer."
        },
        PET_405_PASSIVE = {
          ContentDE = [[
Die Hauptfigur und die Kampfbegleiter erhalten:
 Anemo-ANG +#1, Max. LP +#2]]
        },
        PET_405_SKILL = {
          ContentDE = "Heilt sich selbst und Verbündete für #1 der max. LP der Haupfigur."
        },
        PET_406_PASSIVE = {
          ContentDE = [[
Die Hauptfigur und die Kampfbegleiter erhalten:
 Lumino-ANG +#1, Max. LP +#2]]
        },
        PET_406_SKILL = {
          ContentDE = "Verursacht Lumino-SCH in Höhe von #1 des ANG der Hauptcfigur an Gegnern in Reichweite und reduziert ihren verursachten SCH um #2 für #3 Sek."
        },
        PET_407_PASSIVE = {
          ContentDE = "Sammelradius +#3 m, erhaltene EP durch handlungsunfähige Gegner +#2 und eine Chance von #1, dass Bonus-Beute erscheint."
        },
        PET_407_SKILL = {
          ContentDE = "Verursacht SCH in Höhe von #1 des ANG der Hauptfigur an Gegnern in der Nähe. Entdeckt 1 Geniemon und 1 Truhe im Umkreis von 100 m und markiert ihre Position für 30 Sek."
        },
        PET_408_PASSIVE = {
          ContentDE = "Sprung-GES +#1, Spiralsprung-GES +#2, Gleitreibung -#3."
        },
        PET_408_SKILL = {
          ContentDE = "Reduziert den erlittenen SCH für sich selbst und Verbündeten um #1 für #2 Sek."
        },
        PET_409_PASSIVE = {
          ContentDE = "ANG +#1, max. LP +#2, VTD +#3."
        },
        PET_409_SKILL = {
          ContentDE = "Heilt sich selbst und Verbündete kontinuierlich, stellt #1 ihrer max. LP pro Sekunde für #2 Sek. wieder her."
        },
        PET_411_PASSIVE = {
          ContentDE = "Erhöht den Umbro-ANG der Hauptfigur und der Kampfbegleiter um #1 und die durch Dämonenkeile mit dem Präfix [Phönix] bereitgestellten Attributen um #2."
        },
        PET_411_SKILL = {
          ContentDE = "Verursacht Umbro-SCH in Höhe von #1 des ANG der Hauptfigur an Gegnern innerhalb der Reichweite und reduziert ihre VTD um #2 für #3 Sek."
