        Pet_IpDes_401 = {
          ContentDE = "Ein Geniemon, der häufig auf Schlachtfeldern, in Ruinen oder auf Friedhöfen auftaucht und sich von Kadavern ernährt. Mit seinen Zwillingshörnern und düsteren Gewohnheiten gilt er in vielen Gegenden als böses Omen."
        },
        Pet_IpDes_402 = {
          ContentDE = "Ein wasserliebender Geniemon, der in der Luft schwebt und seinen halbtransparenten Körper meist zusammenzieht, sodass er im Sonnenlicht kaum zu sehen ist. Erst bei Regen entfaltet er seinen Leib und blüht wie eine Blume am Himmel auf."
        },
        Pet_IpDes_403 = {
          ContentDE = "Ein Geniemon, dessen Körper größtenteils aus wärmeerzeugenden Drüsen besteht; sobald er sein Maul öffnet, strömen glühende Hitzewellen aus seinem Inneren."
        },
        Pet_IpDes_404 = {
          ContentDE = "Ein häufig in Hochländern entdeckter Geniemon, der wegen der hervorragenden Leitfähigkeit seines Fells einst stark von Menschen bejagt wurde. Trifft man ihn heute in der Wildnis, rollt er sich meist blitzschnell zu einer Kugel zusammen und flieht."
        },
        Pet_IpDes_405 = {
          ContentDE = "Ein parasitärer Geniemon, der im Inneren von Pilzen heranwächst und allmählich die Kontrolle über seinen Wirt übernimmt. Das „Puff-Puff“-Geräusch, das er bei der Bewegung macht, entsteht, wenn Luft durch den Hohlraum zwischen seinem eigentlichen Körper und dem Pilz strömt."
        },
        Pet_IpDes_406 = {
          ContentDE = "Ein flinker, schelmischer und gieriger Geniemon. Wenn du ihn siehst, prüfe bitte sofort, ob dir nicht etwas Glänzendes fehlt."
        },
        Pet_IpDes_407 = {
          ContentDE = "Ein scheuer, aasfressender Geniemon, der alles hortet, was er tragen kann: Ein Teil dient ihm als Nahrung, der Rest als Nistmaterial, mit dem er seine Kisten ausstopft."
        },
        Pet_IpDes_408 = {
          ContentDE = "Ein äußerst beweglicher Geniemon, dessen riesige Ohren ihn nicht behindern, sondern ihm vielmehr eine perfekte, stromlinienförmige Gestalt fürs Rennen verleihen."
        },
        Pet_IpDes_409 = {
          ContentDE = "Ein fauler, aber langlebiger Geniemon. Statistiken zufolge verbringt er über 98 % seines Lebens schlafend. Vielleicht ist genau das Geheimnis seiner Langlebigkeit."
        },
        Pet_IpDes_411 = {
          ContentDE = "Ein Geniemon, der häufig in verlassenen Gebäuden wie alten Burgen oder Ruinen anzutreffen ist. Aus der Ferne wirkt er wie schwebendes Irrlicht."
        },
        Pet_IpDes_412 = {
          ContentDE = "Die puddingartige Weichheit und das niedliche Aussehen machten den Geniemon Zuckerschneehasen einst auf dem ganzen Kontinent Atlasia ungeheuer beliebt. Doch seit ein Gelehrter aus Aethyrie darauf hinwies, dass die zwei schwarzen Punkte keine Augen, sondern seine Eingeweide sind, hat seine Beliebtheit nie wieder das frühere Niveau erreicht."
        },
        Pet_IpDes_413 = {
          ContentDE = "Ein von Flammen umhüllter Geniemon, der in heißen Regionen lebt. Gerade deshalb verströmt er ständig einen leichten Duft von angebratenem Fleisch."
        },
        Pet_IpDes_414 = {
          ContentDE = "Ein bedauernswerter Geniemon, der wegen der Elektrizität, die seinen ganzen Körper durchzieht, von anderen gemieden wird. Niemand kennt sein wahres Aussehen. Man sieht stets nur jene einsamen Augen, die sich hinter einem kleinen Spielzeugauto verbergen."
        },
        Pet_IpDes_415 = {
          ContentDE = "Ein lebhafter, kleiner Geniemon, der niemals lange an einem Ort bleiben kann. Er klammert sich an Löwenzahnsamen und treibt umher, auf der Suche nach einem Ziel, das gar nicht existiert."
        },
        Pet_IpDes_416 = {
          ContentDE = "Ein strahlend leuchtender Geniemon, der Reisenden gelegentlich als Lichtquelle und Wegweiser dient. Da er periodisch gleißende Blitze aussendet, sollte man ihn nicht zu lange anstarren."
        },
        Pet_IpDes_421 = {
          ContentDE = "Ein extrem seltener Geniemon mit dem glänzenden Schimmer von Obsidian, einst für ein reines Fantasiewesen aus den Liedern der Wanderbarden gehalten."
        },
        Pet_IpDes_422 = {
          ContentDE = "Ein extrem seltener Geniemon mit dem glänzenden Schimmer von Iolith, einst für ein reines Fantasiewesen aus den Liedern der Wanderbarden gehalten."
        },
        Pet_IpDes_423 = {
          ContentDE = "Ein extrem seltener Geniemon mit dem glänzenden Schimmer von Karneol, einst für ein reines Fantasiewesen aus den Liedern der Wanderbarden gehalten."
        },
        Pet_IpDes_424 = {
          ContentDE = "Ein extrem seltener Geniemon mit dem glänzenden Schimmer von Amethyst, einst für ein reines Fantasiewesen aus den Liedern der Wanderbarden gehalten."
        },
        Pet_IpDes_425 = {
          ContentDE = "Ein extrem seltener Geniemon mit dem glänzenden Schimmer von Smaragd, einst für ein reines Fantasiewesen aus den Liedern der Wanderbarden gehalten."
        },
        Pet_IpDes_426 = {
          ContentDE = "Ein extrem seltener Geniemon mit dem glänzenden Schimmer von Opal, einst für ein reines Fantasiewesen aus den Liedern der Wanderbarden gehalten."
        },
        Pet_IpDes_491 = {
          ContentDE = "Ein Geniemon, der die Form einer Heildrohne nachahmt. Bis heute haben Gelehrte das Prinzip und die Regeln der Geniemon-Mimikry noch nicht entschlüsselt. Man weiß nur, dass sich der Heildrohnen-Geniemon vollständig an die Umgebung vom Aeolipile angepasst und die günstigsten Eigenschaften für sein Überleben entwickelt hat."
        },
        Pet_IpDes_492 = {
          ContentDE = "Ein Geniemon, der die Form einer Magnetdrohne nachahmt. Bis heute haben Gelehrte das Prinzip und die Regeln der Geniemon-Mimikry noch nicht entschlüsselt. Man weiß nur, dass sich der Magnetdrohnen-Geniemon vollständig an die Umgebung vom Aeolipile angepasst und die günstigsten Eigenschaften für sein Überleben entwickelt hat."
        },
        Pet_IpDes_493 = {
          ContentDE = "Ein aasfressender Geniemon, der durch die Spalten im Erdreich wandert, dabei Nährstoffe aufnimmt und zugleich die Bodenqualität verbessert."
        },
