        PhantomTalk_1102_Chest = {
          ContentDE = "Unerwartetes Glück ... Vielleicht war es immer für dich bestimmt. "
        },
        PhantomTalk_1103_Chest = {
          ContentDE = "Nicht alle Überraschungen verstecken sich hinter dem Vorhang. Manche treten direkt ins Licht."
        },
        PhantomTalk_1104_Chest = {
          ContentDE = "Hier könnte ein Schatz liegen, {性别:mein junger Freund|meine junge Freundin} – leg ihn in deinen Vorrat."
