        PhantomTalk_120101_Chest = {
          ContentDE = "Nicht schlecht, eine unerwartete Freude entdeckt."
        },
        PhantomTalk_1201_Chest = {
          ContentDE = "Nicht schlecht, eine unerwartete Freude entdeckt."
        },
        PhantomTalk_1501_Chest = {
          ContentDE = "Eine Truhe? Zerschmettere sie, Samael! Moment, nein ... heute nicht."
        },
        PhantomTalk_1502_Chest = {
          ContentDE = "Es scheint ein Andenken zu sein ... vielleicht hinterlassen von einer Seele, die ins Nebelmeer getrieben wurde."
        },
        PhantomTalk_1503_Chest = {
          ContentDE = "Einige Schätze hier wären zu schade, um sie in der Erde zu lassen, nimm sie mit."
        },
        PhantomTalk_160101_Chest = {
          ContentDE = "Nicht schlecht, eine unerwartete Freude entdeckt."
