        PhantomTalk_1601_Chest = {
          ContentDE = "Nicht schlecht, eine unerwartete Freude entdeckt."
        },
        PhantomTalk_1801_Chest = {
          ContentDE = "Finas Freunde sagen, sie riechen den Schatz des Königs."
        },
        PhantomTalk_2101_Chest = {
          ContentDE = "Romantik braucht gelegentliche Überraschungen. Schau, hier ist eine."
        },
        PhantomTalk_2301_Chest = {
          ContentDE = "Etwas Schönes gefunden. Hehe, willst du raten, was drin ist?"
        },
        PhantomTalk_2401_Chest = {
          ContentDE = "Unerwartetes Glück auf dem Land. Genug, um ein paar Heiltränke zu kaufen."
        },
        PhantomTalk_3101_Chest = {
          ContentDE = "Unerwartete Beute? Sieht aus, als hätten wir Glück."
        },
        PhantomTalk_3102_Chest = {
          ContentDE = "Wie ich schon sagte – beim Aufräumen gibt es gelegentlich Überraschungen."
        },
        PhantomTalk_3103_Chest = {
          ContentDE = "Äh ... Oliver meint, hier liegt etwas Glänzendes in der Nähe."
        },
        PhantomTalk_3201_Chest = {
          ContentDE = "Ungerechtes Eigentum? Nimm es, das widerspricht der Gerechtigkeit nicht."
        },
        PhantomTalk_3202_Chest = {
          ContentDE = "Glück ist auch eine Möglichkeit, Reichtum anzuhäufen. Nimm diese Dinge an."
