        READSERIES_DESC_1039 = {
          ContentDE = "Unter unzähligen Akten aus dem Archivschrank hervorgekramt: Akten mit Fotos der Kinder, die jeden einzelnen Tag dokumentieren, den sie im Hypnos’ Haus verbracht haben."
        },
        READ_DESC_2000001 = {
          ContentDE = "Auf dem Sockel der Statue befinden sich verwitterte Inschriften – der verblichene Text ist wohl eine Lobeshymne auf eine Gottheit."
        },
        READ_DESC_2000002 = {
          ContentDE = "Ein vergilbter und etwas beschädigter Foliant über Alchemie, voller Anmerkungen."
        },
        READ_DESC_2000003 = {
          ContentDE = "Ein herrenloses Tagebuch, in eleganter Handschrift verfasst, jedoch ziemlich ramponiert. Einige Passagen sind schwer zu entziffern."
        },
        READ_DESC_2000004 = {
          ContentDE = "Ein herrenloses Tagebuch, in eleganter Handschrift verfasst, jedoch ziemlich ramponiert. Einige Passagen sind schwer zu entziffern."
        },
        READ_DESC_2000005 = {
          ContentDE = "Ein herrenloses Tagebuch, in eleganter Handschrift verfasst, jedoch ziemlich ramponiert. Einige Passagen sind schwer zu entziffern."
        },
        READ_DESC_2000006 = {
          ContentDE = "Eine bruchstückhafte Aufzeichnung des letzten Gesprächs zwischen Psyche und Henrik."
        },
        READ_DESC_2000007 = {
          ContentDE = "Ein traditionsreiches medizinisches Lehrbuch, in dem die Ursachen, Symptome und Therapien einer Vielzahl von Krankheiten ausführlich beschrieben werden. Viele der Behandlungsdaten sind zwar noch nicht vollständig, doch auf dem Einband steht in großen Lettern: „Es gibt keine Krankheit, die der Menschheit nicht heilen kann“ – ein Versprechen, das zukünftige Generationen von Heilern und Gelehrten erfüllen werden."
        },
        READ_DESC_2000008 = {
          ContentDE = "Ein alter, zerlesener Wälzer mit exotischem Einband. Seine Seiten sind brüchig, als könnten sie schon bei der geringsten Berührung zerfallen. Bei näherer Betrachtung handelt es sich wohl um einen Text über Pharmakologie."
        },
        READ_DESC_2000009 = {
          ContentDE = "Ein opulenter Brief an Henrik Ethelred, in einer Schublade gefunden."
        },
        READ_DESC_2000010 = {
          ContentDE = "Ein nicht abgeschickter Brief, der aus unerfindlichen Gründen auf dem Schreibtisch verstaubt."
        },
        READ_DESC_2000011 = {
          ContentDE = "Die zweite Hälfte dieses familiären Schreibens ist durch Wasserflecken verwischt und daher nicht mehr lesbar. Die verstaubte Seite und die Präsenz von Hypnos’ Haus sprechen deutlich für Henriks damalige Entscheidung."
        },
        READ_DESC_2000012 = {
          ContentDE = "Ein Fortsetzungsroman mit einem schmalzigen Titel, vor dem Hintergrund des Jahrzehnte andauernden Krieges zwischen Hyperborea und Elysium – im Mittelpunkt stehen die Abenteuer eines Jungen aus Hyperborea. Er ist bei den Jugendlichen des Imperiums sehr beliebt."
        },
        READ_DESC_2000013 = {
          ContentDE = "Das Tagebuch eines Reisenden, das lange der Witterung ausgesetzt war. Die Seiten sind durch Flecken und Verschmutzungen größtenteils unleserlich, nur die neuesten Einträge kann man noch entziffern."
        },
        READ_DESC_2000014 = {
          ContentDE = "Theos ausführliche Feldnotizen, die sämtliche Bereiche behandeln – die Umwelt, Pflanzen, Tiere und Menschen."
        },
        READ_DESC_2000015 = {
          ContentDE = "Theos ausführliche Feldnotizen, die sämtliche Bereiche behandeln – die Umwelt, Pflanzen, Tiere und Menschen."
        },
        READ_DESC_2000016 = {
          ContentDE = "Theos ausführliche Feldnotizen, die sämtliche Bereiche behandeln – die Umwelt, Pflanzen, Tiere und Menschen."
        },
        READ_DESC_2000017 = {
          ContentDE = "Ein verschlissener Brief von Annie an ihre Mutter, der durch die lange Zeit in der Tasche ramponiert, aber dennoch leserlich ist."
        },
        READ_DESC_2000018 = {
          ContentDE = "Ein in der Glevum-Grube gefundenes Tagebuch, das vermutlich überstürzt zurückgelassen wurde. Auf seinen Seiten offenbaren sich tiefe Gewissensbisse des Autors sowie einige düstere, möglicherweise ausgedachte Geheimnisse."
        },
        READ_DESC_2000019 = {
          ContentDE = "Ein vierzig Jahre altes Tagebuch, das auf einem abgelegenen Pfad in den tiefsten Tiefen der Glevum-Grube entdeckt wurde. Das hastige Gekritzel offenbart die schlichten, aber leidenschaftlichen Begierden eines jungen Mannes."
        },
        READ_DESC_2000020 = {
          ContentDE = "Eingeritzte Worte, die unter einer Aufwallung heftiger Emotionen tief in eine Wand getrieben wurden. Der Zorn des Meißelnden scheint hinter jedem Buchstaben zu atmen."
        },
        READ_DESC_2000021 = {
          ContentDE = "Eingeritzte Worte eines kaum zu entziffernden Textes, gefunden in den Spalten der Wand eines Abwasserkanals, die offenbar mit einer Frage zusammenhängen, die sich ein Bewohner dieses Ortes gestellt hat."
        },
        READ_DESC_2000022 = {
          ContentDE = "Eingeritzte Worte eines kaum zu entziffernden Textes, gefunden in den Spalten der Wand eines Abwasserkanals, die offenbar mit einer Frage zusammenhängen, die sich ein Bewohner dieses Ortes gestellt hat."
        },
        READ_DESC_2000023 = {
          ContentDE = "Ein aufwendig gestaltetes Flugblatt. Hättest du den erbärmlichen Zustand der verlassenen Grube nicht mit eigenen Augen gesehen, hätte sie dich vielleicht für einen Moment täuschen können.\n Als du dieses Flugblatt mitnimmst, ersparst du jemandem, Opfer eines Betrugs zu werden.\n Was den Köder in der Schachtel angeht – betrachte ihn als Belohnung für deine gute Tat und nimm ihn mit Stolz entgegen."
        },
        READ_DESC_2000024 = {
          ContentDE = "Ein zerknitterter Brief, der aussieht, als wäre er einmal durchnässt worden. Auf dem Umschlag steht keine Adresse, nur der Name des Empfängers."
        },
        READ_DESC_2000025 = {
          ContentDE = "Die Seiten sind im Laufe der Zeit vergilbt, aber noch unbeschädigt. Jemand muss ihn sorgfältig aufbewahrt haben.\n Auf dem Umschlag befindet sich das Porträt einer grauhaarigen Frau, in deren linkem Auge eine makellos weiße Blume blüht.\n Auf der Rückseite finden sich das Wappen der Verlassenen und die Inschrift: „Möge die Freiheit uns den Weg weisen.“"
        },
        READ_DESC_2000026 = {
          ContentDE = "Ein abgelehnter Antrag, der ein Datum von vor anderthalb Jahren trägt."
        },
        READ_DESC_2000027 = {
          ContentDE = "Ein Gespräch, das über weitergegebene Notizen geführt wurde. Das verschlissene Papier spricht dafür, dass dieser Austausch schon vor einiger Zeit stattgefunden hat."
        },
        READ_DESC_2000028 = {
          ContentDE = "Der Inhalt dieses Tagebuchs deutet auf eine gewisse Nachlässigkeit bei der Disziplin innerhalb der Verlassenen hin."
        },
        READ_DESC_2000029 = {
          ContentDE = "Ein abgelehnter Antrag, der ein Datum von vor zwei Jahren trägt."
        },
        READ_DESC_2000030 = {
          ContentDE = "Der einzige Festtag, den die in der Festung stationierten Soldaten feiern dürfen."
        },
        READ_DESC_2000031 = {
          ContentDE = "Eine knackige formulierte Evakuierungsmitteilung, die sich ganz anders liest als die üblichen Mitteilungen des Imperiums."
        },
        READ_DESC_2000032 = {
          ContentDE = "Kampfprotokolle von der Simulationskonsole in der Lonza-Festung. Sie enthalten detaillierte Angaben zu den Leistungen der imperialen Soldaten in simulierten Schlachten sowie ehrliche Beurteilungen und Empfehlungen für jede Einheit.\n Die Darstellung wechselt in den letzten Einträgen plötzlich, was darauf hindeutet, dass sie wohl von einem Mitglied der Verlassenen und nicht von jemandem aus der Legion verfasst wurden."
        },
        READ_DESC_2000033 = {
          ContentDE = "Ein inoffizielles Verzeichnis von Militärhunden, geführt von einem imperialen Hundeführer und sorgfältig tief im Stauraum eines Streitwagens versteckt.\n Ein Wasserschaden hat die letzten paar Einträge verwischt."
        },
        READ_DESC_2000034 = {
          ContentDE = "Ein Notfallprotokoll ohne jegliche Formalitäten. Es beschreibt präzise den Zustand der Verwundeten und die durchgeführten Notfallbehandlungen.\n Die Handschrift auf der Seite mit den verbleibenden medizinischen Vorräten wird immer fieberhafter, je mehr die Vorräte schwinden, und spiegelt deutlich die zunehmende Besorgnis des Verfassers wider."
        },
        READ_DESC_2000035 = {
          ContentDE = "Niederschriften einer Diskussion innerhalb der Verlassenen über einen neuen Rekruten, der nach der Besetzung der Festung aufgenommen wurde."
        },
        READ_DESC_2000036 = {
          ContentDE = "Ein verschollenes Tagebuch, das einem Mitglied der Verlassenen gehört. Den Einträgen zufolge könnte der Besitzer ein Heiler sein."
        },
        READ_DESC_2000037 = {
          ContentDE = "Ein fein säuberlich verfasster Brief, der geöffnet auf dem Schreibtisch liegt und schon gelesen wurde. Er ist an Henrik Ethelred adressiert."
        },
        READ_DESC_2000038 = {
          ContentDE = "Ein unordentlicher Haufen Mahnungen, verstreut auf dem Schreibtisch, die Henrik auffordern, seine Schulden zu begleichen. Offensichtlich hat Hypnos’ Haus schon seit einiger Zeit mit finanziellen Problemen zu kämpfen."
        },
        READ_DESC_2000039 = {
          ContentDE = "Ein Haufen abgerissener Medikamentenetiketten – auf jedem davon steht „Sedativum“. Auf die Rückseite eines dieser Etiketten wurde zornig eine Nachricht gekritzelt."
        },
        READ_DESC_2000040 = {
          ContentDE = "Ein Papierfetzen, auf den ein kurzes Gedicht gekritzelt ist."
        },
        READ_DESC_2000041 = {
          ContentDE = "Ein Ordner, der aus den Aktenschränken ausgegraben wurde. Darauf ist ein Foto von Psyche zu sehen und er enthält Informationen über ihre Zeit in Hypnos’ Haus."
        },
        READ_DESC_2000042 = {
          ContentDE = "Ein Ordner, der aus den Aktenschränken ausgegraben wurde. Darauf ist ein Foto von Elisa zu sehen und er enthält Informationen über ihre Zeit in Hypnos’ Haus."
        },
        READ_DESC_2000043 = {
          ContentDE = "Ein Ordner, der aus den Aktenschränken ausgegraben wurde. Darauf ist ein Foto von Hunt zu sehen und er enthält Informationen über seine Zeit in Hypnos’ Haus."
        },
        READ_DESC_2000044 = {
          ContentDE = "Eine Sammlung von urbanen Legenden, die ursprünglich in einer inzwischen eingestellten Boulevardzeitung erschienen sind. In einem Imperium, regiert von Alchemie und roher Gewalt, waren solche Geschichten nicht einmal den Spott am Abendbrottisch wert.\n Unter den Geschichten finden sich „Der fahrerlose Bus, in den man nach 22 Uhr niemals einsteigen sollte“ und „In Icelake gibt es keine pechschwarzen Katzen“. Die hier dargestellte Geschichte handelt von einem Mann, der die Menschheit für nichts anderes als eine Kolonie von Ameisen hält, die in Gefangenschaft gezüchtet werden."
        },
        READ_DESC_2000045 = {
          ContentDE = "Ein Pergamentbogen, auf dem das Wappen der Verlassenen prangt. Er scheint hastig zusammengeknüllt und in die Kanalisation geworfen worden zu sein. Am unteren Rand befindet sich eine einzige Zeile in eng gesetzter Schrift: „Möge uns die Rache auf unserem Weg leiten.“"
        },
        READ_DESC_2000046 = {
          ContentDE = "Ein ausführliches Protokoll, geführt von den Backstage-Mitarbeitern, in dem die Verwaltung der Requisiten im Galea-Theater während der letzten zwei Wochen dokumentiert ist."
        },
        READ_DESC_2000047 = {
          ContentDE = "Eine Medaille, ganz aus reinem Gold geschmiedet. Dem Begleitschreiben zufolge wird diese Auszeichnung nur jenen Soldaten verliehen, deren Verdienste um das Imperium als außerordentlich und unermesslich angesehen werden."
        },
        READ_DESC_2000048 = {
          ContentDE = "Diese Zeitung, vom Alter vergilbt und unter einem Haufen alten Gerümpels vergraben, berichtet von einer Tragödie, die sich vor Jahren in Icelake zugetragen hat."
        },
        READ_DESC_2000049 = {
          ContentDE = "Eine von Hand verfasste Aufzeichnung, die von Rhythm transkribiert wurde und eine Prügelei beschreibt, die vor zwei Jahren während einer Vorstellung im Galea-Theater ausgebrochen ist."
        },
        READ_DESC_2000050 = {
          ContentDE = "Dem Wortlaut nach zu urteilen, gehörte dieses Tagebuch wahrscheinlich Blues Fischer. Jede Seite ist mit Erinnerungen an seinen Alltag mit seiner Schwester gefüllt – kein Fleckchen blieb unbeschrieben."
        },
        READ_DESC_2000052 = {
          ContentDE = "Ein kleines Notizbuch, aus der Kanalisation gefischt, dessen Seiten starr sind von Schlamm und getrocknetem Blut. Die meisten Einträge sind nun unleserlich."
        },
        READ_DESC_2000053 = {
          ContentDE = "(Diese losen Seiten wurden in den Ecken des Theaters verstreut gefunden, verfasst von Parsifal. Den Gebrauchsspuren auf den Seiten nach zu urteilen, scheint dieses Skript oft gelesen worden zu sein – vielleicht in der Hoffnung, eines Tages selbst auf der Bühne zu stehen.)\n Auf dem Nordwest-Kap, weit außerhalb des Einflussbereichs der Elysischen Kirche, existierte einst ein Herzogtum namens Yashnia, ein schmaler Landstreifen, der dem Hyperboreischen Imperium auf der anderen Seite des Meeres gegenüberlag. Yashnia war ein wichtiger Handelsplatz und diplomatischer Knotenpunkt und schwebte unsicher zwischen der Kirche und dem Imperium – bis die Kirche es vor mehr als drei Jahrhunderten annektierte.\n Obwohl von kleiner Größe, bestand das Herzogtum über Generationen hinweg. Die Herzöge klammerten sich durch eine blutige Historie an die Macht: Intrigen am Hof, Adelsmorde und politische Attentate. In den folgenden Jahrhunderten wurde das blutige Vermächtnis Yashnias von Wanderbarden für ihre Dramen und Balladen ausgeschlachtet. Selbst das Imperium – obwohl es offiziell untersagt ist, die Ermordung von Mitgliedern des Königshauses zu dramatisieren – lässt solche Theaterstücke aufführen, weil es sie als angemessene Anklage sieht, die blutige Vergangenheit der Kirche an den Pranger zu stellen. Unter diesen Werken ist „Momiji: Eine Chronik der Rebellion“ nach wie vor eines der beliebtesten Stücke und wird für seine mitreißende Musik, seine aufwendige Choreografie und seine spannenden Schlachtdarstellungen gelobt."
        },
        READ_DESC_2000057 = {
          ContentDE = "Eine Hymne, die beim Silberkerzen-Karneval gesungen wird und von seiner legendären Entstehung erzählt: Soranus, der jüngere Bruder von Dis I., dem ersten Kaiser von Hyperborea, der von den Charon erschlagen wurde. Doch nach dem Sieg wählte Dis I. nicht den Weg der Vergeltung, sondern den des Friedens und veranstaltete ein großes Fest.\n Es heißt, dass der heutige Silberkerzen-Karneval seinen Ursprung in diesem Fest hat."
        },
        READ_DESC_2000067 = {
          ContentDE = "Ein von Hand gekritzeltes Flugblatt, das mit seiner krakeligen Schrift so wild anmutet, dass man die Schrift fast schreien hören kann. Zeile für Zeile wird die Silberkerzen-Hymne angeprangert und die Wahrheit in ihr Gegenteil verkehrt."
        },
        READ_DESC_2000068 = {
          ContentDE = "Die Getränkekarte von der Asphodel – jedes Glas ist vollmundig und duftet herrlich. Schon nach einem Schluck wirst du wiederkommen, um mehr zu trinken."
        },
        READ_DESC_2000069 = {
          ContentDE = "Gerüchte über die obersten Ränge der Verlassenen – ihre Glaubwürdigkeit ist zweifelhaft, aber sie sind kurzweilig genug, um sich damit zu amüsieren."
        },
        READ_DESC_2000070 = {
          ContentDE = "Die folgenden Ausführungen stammen aus den Schriften von Comnena, einer Gelehrten aus Aethyrie. Ihre Geschichten sind notorisch schwer zu verstehen und unterscheiden sich an einigen Stellen von den offiziellen Aufzeichnungen des Hyperboreischen Imperiums – und daher sind sie selten an anderen Orten als in den Regalen von Sammlern zu finden. Diese Folianten werden tatsächlich häufiger zur Dekoration gekauft, als um sie wirklich zu studieren. Ein einzelner Druck steht schon mal fünf Jahre lang im Regal, bevor er endlich den Laden des Buchhändlers verlässt."
        },
        READ_DESC_2000072 = {
          ContentDE = "Ein früher Bericht eines Überlebenden über die Plage von Zhuyin, der von einem Bauern aus den Bergdörfern um Nebelkai verfasst wurde."
        },
        READ_DESC_2000073 = {
          ContentDE = "Ein zerfledderter, stark bekritzelter Band. Der Verfasser scheint jede Menge Fallstudien gesammelt zu haben, um den Lesern zu vermitteln, wie man aus einer Diskussion als Sieger hervorgeht ... und doch liegt das Buch nun verlassen da, achtlos von jemandem zur Seite gestellt."
        },
        READ_DESC_2000074 = {
          ContentDE = "Es scheint sich um einen Lobgesang auf die Jishu-Sekte zu handeln, obwohl der Text ziemlich konfus ist und kaum Sinn ergibt. Du kannst fast hören, wie ihn jemand in deinem Kopf schräg und laut grölt."
        },
        READ_DESC_2000075 = {
          ContentDE = "Ein Fortsetzungsroman mit einem langweiligen Titel. Er handelt von einem jungen Mann namens Zhao Hao, der zum Hohen Kanzler von Loongyuan gewählt wird. Ein Buch, das sich bei den jungen Leserinnen und Lesern von Huaxu großer Beliebtheit erfreut."
        },
        READ_DESC_2000076 = {
          ContentDE = "Eine mit Tusche gemalte Landschaft von Huaxu, reich verziert und mit Siegeln übersät. Neben der Unterschrift des Künstlers steht ein einzelnes Couplet – und bei näherer Betrachtung wirken einige seiner Figuren ein bisschen fehl am Platz."
        },
        READ_DESC_2000077 = {
          ContentDE = "Diese fantastischen Geschichten soll ein alter Mann namens Onkel Feng vorgetragen haben. Sie erwiesen sich als so unterhaltsam, dass sie von späteren Generationen in einem einzigen Buch zusammengefasst wurden. Manche Erwachsene finden zwar einige Textpassagen etwas verstörend, aber die Sammlung wird trotzdem weiterhin in Huaxu gedruckt und erfreut sich bei Kindern nach wie vor großer Beliebtheit."
        },
        READ_DESC_2000078 = {
          ContentDE = "Ein Notizbuch, das von einer unbekannten Person in der Nähe des Zhuyin-Altars zurückgelassen wurde, und dessen Tinte an einigen Stellen schon verwischt ist. Darin wird ausführlich beschrieben, was der Verfasser hier erleben musste. Niemand kann wissen, in welcher Verzweiflung er diese letzten Worte geschrieben hat."
        },
        READ_DESC_2000079 = {
          ContentDE = "Eine Liste, die nur eine Seite lang ist und wahrscheinlich beiläufig zwischen dem Be- und Entladen von Fracht verfasst wurde."
        },
        READ_DESC_2000080 = {
          ContentDE = "Die Handschrift ist verworren, der Text voller hastiger Streichungen und Schmutzflecken. Man kann auf der gesamten Seite fast spüren, wie aufgewühlt der Verfasser war. Auf dem Deckblatt steht nur ein einziges Wort: „Feng.“"
        },
        READ_DESC_2000081 = {
          ContentDE = "Eine kulturwissenschaftliche Studie, die ein Wissenschaftler aus einem fernen Land verfasst hat, und die sich mit Huaxus einzigartigem Verständnis von Leben und Tod beschäftigt."
        },
        READ_DESC_2000082 = {
          ContentDE = "Eine inoffizielle Übersicht über Schriftzeichen, die in den letzten Jahren häufig in Huaxu-Babynamen verwendet wurden, mit kurzen Erläuterungen zu ihrer Bedeutung. Die Quellen sind nebulös und die Genauigkeit zweifelhaft – am besten als Lektüre für zwischendurch oder einfach zum Spaß geeignet."
        },
        READ_DESC_2000083 = {
          ContentDE = "Ein Vertrag aus dem Jahr X von Dafeng, in dem ein Darlehen aufgeführt ist, das der Händler She Yuqing von Li Laoqian aufgenommen hat. Er hat ein ordnungsgemäßes Format und die Bedingungen sind klar und deutlich formuliert – obwohl eine „0“ im Multiplikator von einer deutlich kleineren Hand eingetragen wurde, doch der Unterschied ist so minimal, dass selbst die schärfsten Augen ihn nicht erkennen können."
        },
        READ_DESC_2000084 = {
          ContentDE = "In diesem Handbuch, das von Mitgliedern der Xuanheng-Sekte zusammengestellt wurde, sind die ordnungsgemäßen Abläufe für die Räucherzeremonie im Argent-Loong-Tempel beschrieben."
        },
        READ_DESC_2000085 = {
          ContentDE = "Ein Band aus Luoxiangs Fallberichten. Als kommunale Mediatorin nutzt Luoxiang ihr Wissen über die Neun Kapitel von Dafeng, um alltägliche Streitigkeiten beizulegen, und hat ihre Erfahrungen in dieser Artikelserie zusammengefasst. Das bodenständige und praxisorientierte Buch hat sich unerwartet zu einem beliebten Lesestoff für jeden Haushalt entwickelt."
        },
        READ_DESC_2000086 = {
          ContentDE = "Dieses Werk gehört zu Xu Xingkes Sammlung „Fußspuren“. Es wurde von der Gemeinde Huaxu in Auftrag gegeben, und der bekannte Reiseschriftsteller hält darin seine Gedanken zu den vielen Regionen seiner Heimat fest."
        },
        READ_DESC_2000087 = {
          ContentDE = "Diese Chronik, die von den Sternenwebern selbst verfasst wurde, dokumentiert das Leben ihrer Mitglieder in biografischer Form. Im Laufe der Jahre und mit dem Wechsel der Generationen stellt sich jeder Nachfolger dieser Aufgabe aufs Neue."
        },
        READ_DESC_2000088 = {
          ContentDE = "Ein Verzeichnis der Projektvorschläge, die von Mitgliedern der Archäologischen Gesellschaft von Greenwich eingereicht wurden, mit handschriftlichen Anmerkungen von Herrn Qiu."
        },
        READ_DESC_2000089 = {
          ContentDE = "Ein Notizbuch im Taschenformat, das Lunocarp immer bei sich trägt – jetzt schon beim siebten Band. Darin befinden sich Geistesblitze, die gleich nach einem Funken der Inspiration oder nach langem Nachdenken aufgeschrieben wurden. Und auf den jüngsten Seiten ist der Einfluss ihrer aktuellen Muse unverkennbar: Snow der „Dämonenkönig“, ein Reisender aus dem fernen Hyperborea."
        },
        READ_DESC_2000090 = {
          ContentDE = "Eine kurze formelle Weisung von Ewiger Frühling."
        },
        READ_DESC_2000091 = {
          ContentDE = "Ein Brief, adressiert an den Anführer einer Huaxu-Handelskarawane, der offenbar von einem seiner ehemaligen Schüler geschrieben wurde."
        },
        READ_DESC_2000092 = {
          ContentDE = "Eine Erzählung von Herrn Qiu höchstpersönlich, in der er schildert, wie er den Schwarzmarkt zu dem gemacht hat, was er heute ist."
        },
        READ_DESC_2000096 = {
          ContentDE = "Ein Tagebuch, zurückgelassen in der Glevum-Grube. Der Tonfall lässt darauf schließen, dass der Verfasser ein Gelehrter sein könnte."
        },
        READ_DESC_2000097 = {
          ContentDE = "Ein Tagebuch, zurückgelassen in der Glevum-Grube, mit dunkelroten Flecken übersät. Die Handschrift entspricht der des zuvor gefundenen Tagebuchs. Der letzte Teil ist vollkommen unübersichtlich, als hätte man ihn in großer Eile auf das Papier gekritzelt."
        },
        READ_DESC_2000098 = {
          ContentDE = "Eine Handschriftlich verfasste Notiz, mit kräftigen und energischen Strichen, die unverkennbar die Strenge einer älteren Hand widerspiegeln."
        },
        READ_DESC_20600 = {
          ContentDE = "Eine Sammlung von geheimnisvollen Seiten, die durch Zufall entdeckt wurden. Einige sind filigrane Schriftrollen aus feinstem Pergament, andere frisch gedruckte Blätter, auf denen die Tinte noch klar und dunkel erscheint. Einige sind lediglich abgerissene Fragmente aus zur Hälfte gefüllten Notizbüchern. Ob mit sauberer Schrift verfasst oder kaum lesbar hingeschmiert, sie haben alle eins gemeinsam: Sie enthalten jeweils einen Hinweis auf den Aufenthaltsort eines versteckten Schatzes."
        },
        READ_FUNCTION_20600 = {
          ContentDE = "Verlorenes Blatt"
        },
