        RESOURCE_DESC_10022 = {
          ContentDE = "In Aethyrie steht Obsidian für Inspiration, geboren aus der Nacht. Jede*r Charon-Gelehrte aus Aethyrie erhält diesen Schlüssel beim Abschluss. Was er bedeutet, weiß nur die Person selbst."
        },
        RESOURCE_DESC_10023 = {
          ContentDE = "Die Dunkelmond-Sekte, die sich von den Neun Großen abwendet, verehrt den „Abgrund“. Ihre Sammlung an Lehren gilt selbstverständlich als Tabu. Doch sind Tabus verführerisch. Wer es wirklich will, dem öffnet sich jederzeit die Tür zu einer neuen Welt."
