        RESOURCE_DESC_PHANTOM = {
          ContentDE = "Ein Siegel zur Beschwörung von Gefährten, Stütze im gemeinsamen Kampf, Vertrauen auf demselben Weg, ein wortloses Versprechen.\n Wenn dein Gebet die Sehnsucht trägt, wird jene Person – so wie du es dir wünschst – an deiner Seite erscheinen."
        },
        RESOURCE_DESC_ROOT = {
          ContentDE = "Gedankenfragmente, aus dem Flugsand der Erinnerung herausgesiebt. Sie tragen die Erinnerung an jemanden, aus der Vergangenheit oder aus einer Zukunft, die noch kommen wird."
