        RESOURCE_TEXT_121 = {
          ContentDE = "„Ähm ... Bestellung bestätigt. Komm unbedingt vorbei, um dir deine tägliche Dosis Phoxene zu holen ... *Gähn* ... Jetzt zurück zu meinem Nickerchen ... Zzzzz ...“\n \n – Luno-Dienerin"
        },
        RESOURCE_TEXT_122 = {
          ContentDE = "„Ähm ... Bestellung bestätigt. Komm unbedingt vorbei, um dir deine tägliche Dosis Phoxene zu holen ... *Gähn* ... Jetzt zurück zu meinem Nickerchen ... Zzzzz ...“\n \n – Luno-Dienerin"
        },
