        RLBlessingGroup_Active = {
          ContentDE = "Kann aktiviert werden"
        },
        RLBlessingGroup_Desc_1 = {
          ContentDE = "Verstärkungen der Nahkampfwaffen"
        },
        RLBlessingGroup_Desc_101 = {
          ContentDE = "Jeder Docht dieses Sets erhöht zusätzlich die KRIT-Rate um <Highlight>15 %</> und den KRIT-SCH um <Highlight>15 %</> bei Nahkampfwaffen.\n Das Verursachen von Schaden mit Nahkampfwaffen hat eine Chance von <Highlight>10 %</>, 1 Stapelung [Schmelz-Feuerglut] anzuwenden."
        },
        RLBlessingGroup_Desc_102 = {
          ContentDE = "[Schmelz-Feuerglut] verursacht alle <Highlight>1</> s DoT in Höhe von <Highlight>35 %</> des ANG der Figur."
        },
        RLBlessingGroup_Desc_103 = {
          ContentDE = "Verlängert die Dauer von [Schmelz-Feuerglut] auf <Highlight>10</> s, bis zu <Highlight>20</>-mal stapelbar."
        },
        RLBlessingGroup_Desc_104 = {
          ContentDE = "Ziele, die von [Schmelz-Feuerglut] betroffen sind, erleiden alle <Highlight>5 </> s einen Treffer durch [Schmelz-Feuerglutsäbel]. Wenn du mit Nahkampfwaffen SCH verursachst, besteht eine Chance von <Highlight>10 %</>, zusätzlich [Schmelz-Feuerglutsäbel] auszulösen."
        },
        RLBlessingGroup_Desc_2 = {
          ContentDE = "Verstärkungen der Fernkampfwaffen"
        },
        RLBlessingGroup_Desc_201 = {
          ContentDE = "Jeder Docht dieses Sets erhöht zusätzlich die KRIT-Rate um <Highlight>15 %</> und den KRIT-SCH um <Highlight>15 %</> bei Fernkampfwaffen.\n Erhöht den Sammelradius. Gewährt nach dem Aufsammeln von Beute für <Highlight>3</> s Immunität gegen Trefferstarre."
        },
        RLBlessingGroup_Desc_202 = {
          ContentDE = "Wenn du mit einer Fernkampfwaffe SCH verursachst, wird [Meergebundener Mond] aktiviert und es werden <Highlight>3</> zusätzliche [Mini-Meergebundene Monde] gespawnt (kann einmal alle <Highlight>10</> s ausgelöst werden)."
        },
        RLBlessingGroup_Desc_203 = {
          ContentDE = "Das Einsammeln eines [Mini-Meergebundener Mond] gewährt 1 [Verschleierter Mond]."
        },
        RLBlessingGroup_Desc_204 = {
          ContentDE = "Beim Einsatz von [Verschleierter Mond] werden <Highlight>3</> [Stinger] in einem fächerförmigen Muster abgefeuert. Das Aufsammeln von Beute gewährt 1 Stapelung [Phantomdrift]."
        },
        RLBlessingGroup_Desc_3 = {
          ContentDE = "Verstärkungen der Fähigkeiten"
        },
        RLBlessingGroup_Desc_301 = {
          ContentDE = "Jeder Docht dieses Sets erhöht das max. Schild um <Highlight>10 %</>.\n Erhöht den Fähigkeits-SCH um <Highlight>25 %</>."
        },
        RLBlessingGroup_Desc_302 = {
          ContentDE = "Erhält 1 Stapelung von <Highlight>[Glanz]</> pro Sekunde (max. 60). Bei 60 Stapelungen verbraucht das Einsetzen einer Fähigkeit alle <Highlight>[Glanz]</> und gewährt <Highlight>[Strahlung]</> für 10 s</>, wodurch der Fähigkeits-SCH um <Highlight>50 %</> erhöht wird."
        },
        RLBlessingGroup_Desc_303 = {
          ContentDE = "Solange du unter [Strahlung] stehst, löst du alle 2 s 1 [Emission] aus, die Gegnern im Umkreis von <Highlight>6</> m einmal Fähigkeits-SCH in Höhe von <Highlight>810 %</> des ANG der Figur zufügt."
        },
        RLBlessingGroup_Desc_304 = {
          ContentDE = "Verlängert die Dauer der [Strahlung] auf <Highlight>20</> s."
        },
        RLBlessingGroup_Desc_4 = {
          ContentDE = "Spezialisiertes beschworenes Objekt"
        },
        RLBlessingGroup_Desc_401 = {
          ContentDE = "Jeder Docht dieses Sets erhöht den SCH des beschworenen Objekts um <Highlight>10 %</>.\n Bei jeder Beschwörung eines beschworenen Objekts außer dem Lumi-Zweigs wird 1 [Lumi-Saat] beschworen.\n [Lumi-Saat]: Detoniert, wenn ein Gegner innerhalb von <Highlight>3</> m auftaucht, und verursacht SCH in Höhe von <Highlight>600 %</> des ANG. Hält <Highlight>10</> s an; gleichzeitig können maximal <Highlight>10</> existieren."
        },
        RLBlessingGroup_Desc_402 = {
          ContentDE = "Jede [Lumi-Saat] hat eine Chance von <Highlight>40 %</>, sich in [Lumi-Blatt] zu entwickeln, wenn es beschworen wird.\n [Lumi-Blatt]: Detoniert, wenn ein Gegner innerhalb von <Highlight>3</> m auftaucht, und verursacht SCH in Höhe von <Highlight>1000 %</> des ANG. Hält <Highlight>10</> s an; gleichzeitig können maximal <Highlight>10</> existieren."
        },
        RLBlessingGroup_Desc_403 = {
          ContentDE = "[Lumi-Blatt] erzeugt bei der Detonation 1 [Lumi-Holz]. Erhält die Figur Heilung, erleiden Gegner im Umkreis von <Highlight>6</> SCH in Höhe von <Highlight>4000 </> der Heilungsmenge.\n [Lumi-Holz]: Heilt Verbündete im Umkreis von <Highlight>10</> um <Highlight>5 %</> der max. LP pro Sekunde. Hält <Highlight>10</> s an; gleichzeitig kann nur 1 existieren."
        },
        RLBlessingGroup_Desc_404 = {
          ContentDE = "Verdoppelt die Chance für alle Effekte, die [Lumi-Saat] beschwören können. [Lumi-Holz] fügt Gegnern in Reichweite pro Sekunde einmal SCH in Höhe von <Highlight>650 %</> des ANG zu."
        },
        RLBlessingGroup_Desc_5 = {
          ContentDE = "Verstärkungen der Mobilität"
        },
        RLBlessingGroup_Desc_501 = {
          ContentDE = "Jeder Docht dieses Sets erhöht den max. Geist um <Highlight>10 %</>.\n Jeder Stapelung von [Umbraler Verschlinger] erhöht ANG der Figur um <Highlight>1 %</>."
        },
        RLBlessingGroup_Desc_502 = {
          ContentDE = "Das Verursachen von Schaden gewährt <Highlight>5</> Stapelungen von [Umbraler Verschlinger]. (maximal einmal alle <Highlight>5</> s ausgelöst)."
        },
        RLBlessingGroup_Desc_503 = {
          ContentDE = "Stellt <Highlight>2</> Punkte Geist pro Sekunde für jeweils 10 Stapelungen von [Umbraler Verschlinger] wieder her."
        },
        RLBlessingGroup_Desc_504 = {
          ContentDE = "[Pulver], [Windflügel] und [Klingenflügel] verursachen beim Schaden zusätzlich einen Treffer, der SCH in Höhe von <Highlight>1 % × ANG der Figur × Max. Geist</> zufügt."
        },
        RLBlessingGroup_Desc_6 = {ContentDE = "Suchrakete"},
        RLBlessingGroup_Desc_601 = {
          ContentDE = "Jeder Docht dieses Sets erhöht die Fähigkeitsreichweite zusätzlich um <Highlight>10 %</>.\n Die max. Anzahl der [Glühkäfer] wird um <Highlight>1</> erhöht. [Glühkäfer] verursachen nun Flächenschaden in einem Radius von <Highlight>2</> m."
        },
        RLBlessingGroup_Desc_602 = {
          ContentDE = "Wenn du einen Glühkäfer erhältst, besteht eine Chance von <Highlight>30 %</>, eine größere Variante zu spawnen."
        },
        RLBlessingGroup_Desc_603 = {
          ContentDE = "Die max. Anzahl der [Glühkäfer] wird um <Highlight>1</> erhöht. Größere Varianten teilen sich bei einem Treffer in <Highlight>3</> normale [Glühkäfer]."
        },
        RLBlessingGroup_Desc_604 = {
          ContentDE = "Wenn [Glühkäfer] SCH verursacht, erhöht den erlittenen SCH dauerhaft um <Highlight>12 %</>, bis zu <Highlight>5</>-mal stapelbar."
        },
        RLBlessingGroup_Desc_7 = {
          ContentDE = "Verstärkt die Überlebensfähigkeit und gewährt den Status Zorn."
        },
        RLBlessingGroup_Desc_701 = {
          ContentDE = "Jeder Docht dieses Sets erhöht die Fähigkeitsdauer zusätzlich um <Highlight>10 %</>.\n Beim Besiegen eines Gegners werden die max. LP um <Highlight>0,5 %</> erhöht, bis zu <Highlight>50 %</>."
        },
        RLBlessingGroup_Desc_702 = {
          ContentDE = "Stellt <Highlight>1 %</> der max. LP pro Sekunde wieder her. Der Effekt wird um <Highlight>0,33 %</> für jeweils <Highlight>25 %</> verlorene LP erhöht."
        },
        RLBlessingGroup_Desc_703 = {
          ContentDE = "Fügt Gegnern in Reichweite alle 3 Sekunden SCH in Höhe von <Highlight>50 %</> der max. LP der Figur zu. Für jeweils <Highlight>25 %</> verlorene LP wird der Effekt um <Highlight>16,7 %</> erhöht."
        },
        RLBlessingGroup_Desc_704 = {
          ContentDE = "Bei mehr als <Highlight>40 %</> LP werden alle [Vamprose]-Effekte, die auf dem aktuellen LP-Prozentsatz basieren, für die Berechnung so behandelt, als lägen nur <Highlight>40 %</> LP vor. Auch bei Moral- und Entschlossenheitseffekten wird der LP-Prozentsatz für die Berechnung auf <Highlight>40 %</> begrenzt."
        },
        RLBlessingGroup_Desc_unknown = {
          ContentDE = "Dieser Segen bleibt im Nebel verborgen"
        },
