        RLBlessing_ActivateGroup = {
          ContentDE = "Aktiviere den Artefakt-Set-Effekt"
        },
        RLBlessing_Desc_101 = {
          ContentDE = "Erhöht ANG der Nahkampfwaffen um <Highlight>#1</>."
        },
        RLBlessing_Desc_102 = {
          ContentDE = "Erhöht die Auslöserate der Nahkampfwaffen um <Highlight>#1</>"
        },
        RLBlessing_Desc_103 = {
          ContentDE = "Erhöht den Standardangriff-SCH der Nahkampfwaffen um <Highlight>$1</>."
        },
        RLBlessing_Desc_104 = {
          ContentDE = "Wenn du Gegner innerhalb von <Highlight>$2</> m besiegst, stellst du <Highlight>$1</> LP wieder her."
        },
        RLBlessing_Desc_105 = {
          ContentDE = "Erlittener SCH durch Gegner im Umkreis von <Highlight>$2</> m oder durch Gegner mit [Schmelz-Feuerglut] wird um <Highlight>$1</> reduziert."
        },
        RLBlessing_Desc_106 = {
          ContentDE = "Wenn du SCH erleidest, wird <Highlight>1</> Stapelung von [Schmelz-Feuerglut] auf Gegner im Umkreis von <Highlight>8</> m angewendet. Kann einmal alle <Highlight>$1</> s ausgelöst werden."
        },
        RLBlessing_Desc_107 = {
          ContentDE = "Erhöht die <Highlight>KRIT-Rate</> der Nahkampfwaffen um <Highlight>#1</>."
        },
        RLBlessing_Desc_108 = {
          ContentDE = "Erhöht den <Highlight>KRIT-SCH</> der Nahkampfwaffe um <Highlight>#1</>."
        },
        RLBlessing_Desc_109 = {
          ContentDE = "Erhöht den SCH der Nahkampfwaffen beim <Highlight>Sturzangriff, geladenen Angriff und Gleitangriff </> um <Highlight>$1</>."
        },
        RLBlessing_Desc_110 = {
