        RLTreasure_Desc_10305 = {
          ContentDE = "Ersetzt alle Artefakte durch zufällige Artefakte, möglicherweise mit höherer Seltenheit,"
        },
        RLTreasure_Desc_10306 = {
          ContentDE = "Erhöht der verursachte SCH um <Highlight>$1</> pro Artefakt im Besitz."
        },
        RLTreasure_Desc_10307 = {
          ContentDE = "Erhöht den Durchschlag gegen alle Elemente um <Highlight>$1</> für jede Art von Docht, die du besitzt, bis zu einem Maximum von <Highlight>$2</>."
        },
        RLTreasure_Desc_10308 = {
          ContentDE = "Reduziert die Anzahl der Dochte desselben Typs, die benötigt werden, um Effekte eines Sets zu aktivieren, um <Highlight>1</>."
        },
        RLTreasure_Desc_10309 = {
          ContentDE = "Wenn du keinen Wiederbelebungsversuch mehr hast, kannst du Glut ×<Highlight>@1</> ausgeben, um <Highlight>1</> zusätzlichen Wiederbelebungsversuch zu erhalten."
        },
        RLTreasure_Desc_10310 = {
          ContentDE = "Wenn Nahkampfangriffe SCH verursachen, werden 8 Schwertwellen entfesselt, die jedem getroffenen Gegner Lumino-SCH in Höhe von <Highlight>$1</> des ANG der Figur zufügen. Abklingzeit: <Highlight>$2</> s."
        },
        RLTreasure_Desc_10311 = {
          ContentDE = "Wenn eine Fähigkeit SCH verursacht, löst sie eine Explosion um den Anwender aus, die allen Gegnern in der Nähe Umbro-SCH in Höhe von <Highlight>$1</> des ANG der Figur zufügt. Abklingzeit: <Highlight>$2</> s."
        },
        RLTreasure_Desc_10312 = {
          ContentDE = "Wenn ein Gegner SCH erleidet, werden 12 zielverfolgende Projektile abgefeuert, die bei einem Treffer Anemo-SCH in Höhe von <Highlight>$1</> des ANG der Figur verursachen. Abklingzeit: <Highlight>$2</> s."
        },
        RLTreasure_Desc_10313 = {
          ContentDE = "Wenn ein beschworenes Objekt erscheint, löst es an seinem Erscheinungsort einen Angriff aus, der bei getroffenen Gegnern Hydro-SCH in Höhe von <Highlight>$1</> des ANG der Figur verursacht. Abklingzeit: <Highlight>$2</> s."
        },
        RLTreasure_Desc_10314 = {
          ContentDE = "Wenn Fernkampfangriffe SCH verursachen, fügt sie Gegnern in einem kegelförmigen Bereich vor ihr zusätzlichen Pyro-SCH in Höhe von <Highlight>$1</> des ANG der Figur zu. Abklingzeit: <Highlight>$2</> s."
        },
        RLTreasure_Desc_10315 = {
          ContentDE = "Beim Einsatz einer Fähigkeit werden 3 Bolzenwellen beschworen, die jeweils Elektro-SCH in Höhe von <Highlight>$1</> des ANG der Figur verursachen. Abklingzeit: <Highlight>$2</> s."
        },
        RLTreasure_Desc_10316 = {
          ContentDE = "Wenn der verursachte SCH unter <Highlight>$1</> liegt, wird einmal zusätzlicher wahrer SCH in Höhe von <Highlight>$2</> verursacht."
        },
        RLTreasure_Desc_11101 = {
          ContentDE = "Solange du einen Schild hast, wird der erlittene SCH um <Highlight>$1</> reduziert."
        },
        RLTreasure_Desc_11201 = {
          ContentDE = "Solange du einen Schild hast, wird der verursachte SCH um <Highlight>$1</> erhöht."
        },
        RLTreasure_Desc_12101 = {
          ContentDE = "Die Aktualisierungskosten bei der Auswahl werden um <Highlight>@1</> erhöht. Der Effekt endet nach <Highlight>@2</> Etappen und gewährt Glut ×<Highlight>@3</>."
        },
        RLTreasure_Desc_12102 = {
          ContentDE = "Preise bei der mysteriösen Händlerin werden um <Highlight>@1</> erhöht. Der Effekt endet nach <Highlight>@2</> Etappen und gewährt Glut ×<Highlight>@3</>."
        },
        RLTreasure_Desc_12201 = {
          ContentDE = "Verursachter SCH wird um <Highlight>$1</> reduziert. Der Effekt endet nach <Highlight>@1</> Etappen und gewährt Glut ×<Highlight>@2</>."
        },
        RLTreasure_Desc_13101 = {
          ContentDE = "Wenn du SCH verursachst, besteht eine Chance von <Highlight>$1</>, zusätzlich Pyro-SCH in Höhe von <Highlight>$2</> des ANG der Figur zu verursachen."
        },
        RLTreasure_Desc_13102 = {
          ContentDE = "Wenn du SCH verursachst, besteht eine Chance von <Highlight>$1</>, zusätzlich Hydro-SCH in Höhe von <Highlight>$2</> des ANG der Figur zu verursachen."
