        RLTreasure_Desc_13103 = {
          ContentDE = "Wenn du SCH verursachst, besteht eine Chance von <Highlight>$1</>, zusätzlich Anemo-SCH in Höhe von <Highlight>$2</> des ANG der Figur zu verursachen."
        },
        RLTreasure_Desc_13104 = {
          ContentDE = "Wenn du SCH verursachst, besteht eine Chance von <Highlight>$1</>, zusätzlich Elektro-SCH in Höhe von <Highlight>$2</> des ANG der Figur zu verursachen."
        },
        RLTreasure_Desc_14101 = {
          ContentDE = "Erhöht den verursachten SCH um <Highlight>$2</> und verringert die Fähigkeitseffizienz um <Highlight>$1</>."
        },
        RLTreasure_Desc_14201 = {
          ContentDE = "Erhöht den verursachten SCH um <Highlight>$2</> und verringert den Nahkampfwaffe-SCH um <Highlight>$1</>."
        },
        RLTreasure_Desc_14202 = {
          ContentDE = "Erhöht den verursachten SCH um <Highlight>$2</> und verringert den Fernkampfwaffe-SCH um <Highlight>$1</>."
        },
        RLTreasure_Desc_14301 = {
          ContentDE = "Erhöht den verursachten SCH um <Highlight>$2</> und den erlittenen SCH um <Highlight>$1</>."
        },
        RLTreasure_Desc_15101 = {
          ContentDE = "Wenn [Kampfhaltung] des Gegners über <Highlight>$1</> ist, stellt deine Figur beim Verursachen des SCH <Highlight>$2</> Punkte Geist wieder her. Abklingzeit: <Highlight>$3</>s."
        },
        RLTreasure_Desc_15201 = {
          ContentDE = "Wenn [Kampfhaltung] des Gegners unter <Highlight>$1</> fällt, wird der verursachte SCH um <Highlight>$2</> erhöht."
        },
        RLTreasure_Desc_Unknown = {
          ContentDE = "Dieses Artefakt bleibt in Nebel gehüllt."
        },
        RLTreasure_Desc_Unlock = {
          ContentDE = "Dieses Artefakt bleibt in Nebel gehüllt."
        },
        RLTreasure_IPDesc_10101 = {
          ContentDE = "Ihr Kerzenlicht vertreibt die Kälte und malt Hoffnung und Lächeln in die Gesichter der Kinder. Aber auch die irdischen Flammen erlöschen irgendwann, also entzündet sie immer wieder neues Licht.\n In den Tiefen des heiligen Sees schmiedete eine Dochtschmiedin eine ewige Flamme – nur um festzustellen, dass niemand mehr in der Dunkelheit auf ihr Licht wartet."
        },
        RLTreasure_IPDesc_10102 = {
          ContentDE = "Jedes Mal, wenn sie sich treffen, beschwert sich der Illusionist mit der Vogelmaske: „Feste Preise verderben den ganzen Spaß! Wo bleibt der Nervenkitzel des Zufalls und des Geheimnisses?“\n Die Händlerin befolgt den Rat und verstreut Rabattcoupons, die sie für ihren Laden entworfen hat, in den Abgrund. Der Illusionist schüttelt bestürzt den Kopf: „Deine Freundlichkeit sorgt für schlechtere Unterhaltung als dein Geschäft.“"
        },
        RLTreasure_IPDesc_10103 = {
          ContentDE = "Sie ist die gläubigste aller Gläubigen, richtet jedes Wort und jede Tat akribisch an der göttlichen Lehre aus und bewahrt sich perfekte Frömmigkeit, selbst wenn kein sterbliches Auge sie sehen kann. Den Kämpfenden bietet sie Hilfe an, den Mittellosen gibt sie großzügig, und selbst Andersdenkenden gibt sie geduldigen Rat und mahnt sie, die Barmherzigkeit der Großen Neun zu schätzen."
        },
        RLTreasure_IPDesc_10104 = {
          ContentDE = "„Was ist, wenn die Götter nicht so perfekt sind, wie du glaubst? Wäre deine Hingabe dann noch wichtig?“ die Menschen herausgefordert.\n „Natürlich“, lächelt sie heiter. \"Wahrer Glaube sucht keine Belohnung, diszipliniert es. Solange meine Handlungen mit meinem Gewissen übereinstimmen, macht es keinen Unterschied, ob die Götter echt oder ungerecht sind.\""
        },
        RLTreasure_IPDesc_10105 = {
          ContentDE = "Diese Hymne ist allen bekannt – sie preist die barmherzigen Götter, die verlorene Seelen leiten. Gläubige von Elysium summen ihre herzzerreißende Melodie in den Abgrund und flehen die Götter an, sie aus dem Leid ins gelobte Land zu führen. Die vergoldete Melodie trägt sie in den ewigen Schlummer, während sie immer noch von der Erlösung träumen."
        },
        RLTreasure_IPDesc_10106 = {
          ContentDE = "Abyssoiden nähern sich von allen Seiten. Der Ritter stürmt allein in die Dunkelheit und bahnt sich einen Weg der Hoffnung. Nachdem sich die Abyssoiden zurückgezogen haben, zieht der Heilerpriester den gebrochenen Körper des Ritters aus der schwarzen Leere.\n „Ich werde sie retten“, schwört der Heilerpriester. Es ist die Pflicht eines Heilers, die Wunden der Tapferen zu heilen."
        },
        RLTreasure_IPDesc_10107 = {
          ContentDE = "Der Weg ist beschwerlich, und die Wahrheit tut immer weh. Wenn die Abendglocke läutet, warum weigert sich der wandernde Vogel, in sein Nest zurückzukehren?\n Weil er weiß, dass kein Turm den Mittelpunkt des Kontinents markiert und keine Götter alle Antworten kennen. Er beschließt, seinen eigenen Weg zu gehen, auch wenn er dafür lebenslang Fesseln tragen muss."
        },
        RLTreasure_IPDesc_10108 = {
          ContentDE = "„Jeder Gewinn hat seinen Preis.“ Dieses Klischee wird in einem Spiel doch interessanter.\n Der Illusionist wirft seinen Spielzeugball in die Schachtel. „Gute oder schlechte Nachrichten zuerst?“"
        },
        RLTreasure_IPDesc_10109 = {
          ContentDE = "„Jeder Gewinn hat seinen Preis.“ Dieses Klischee wird in einem Spiel doch interessanter.\n Der Illusionist wirft seinen Spielzeugball in die Schachtel. „Gute oder schlechte Nachrichten zuerst?“"
        },
        RLTreasure_IPDesc_10110 = {
          ContentDE = "„Jeder Gewinn hat seinen Preis.“ Dieses Klischee wird in einem Spiel doch interessanter.\n Der Illusionist wirft seinen Spielzeugball in die Schachtel. „Gute oder schlechte Nachrichten zuerst?“"
        },
        RLTreasure_IPDesc_10111 = {
          ContentDE = "„Jeder Gewinn hat seinen Preis.“ Dieses Klischee wird in einem Spiel doch interessanter.\n Der Illusionist wirft seinen Spielzeugball in die Schachtel. „Gute oder schlechte Nachrichten zuerst?“"
        },
        RLTreasure_IPDesc_10112 = {
          ContentDE = "„Jeder Gewinn hat seinen Preis.“ Dieses Klischee wird in einem Spiel doch interessanter.\n Der Illusionist wirft seinen Spielzeugball in die Schachtel. „Gute oder schlechte Nachrichten zuerst?“"
        },
        RLTreasure_IPDesc_10113 = {
          ContentDE = "„Jeder Gewinn hat seinen Preis.“ Dieses Klischee wird in einem Spiel doch interessanter.\n Der Illusionist wirft seinen Spielzeugball in die Schachtel. „Gute oder schlechte Nachrichten zuerst?“"
        },
        RLTreasure_IPDesc_10114 = {
          ContentDE = "Vergiss auf deiner Reise nicht die tapferen kleinen Gefährten, die dir in den Abgrund folgen. Öffne ein Leckerli, um ihren Mut zu belohnen!"
        },
        RLTreasure_IPDesc_10201 = {
          ContentDE = "Wasser, Verpflegung, ein Feuerstein ... und eine zerknitterte Karte. Ihr Besitzer hat einmal versucht, den Weg mit Holzkohle nachzuzeichnen – Linien, die sich kreuzen, überlappen und sogar über den Rand der Karte hinausgehen. Die Striche drehen sich in sinnlosen Kreisen, bevor sie abrupt aufhören und nur ein schiefes Fragezeichen übrig bleibt."
        },
        RLTreasure_IPDesc_10202 = {
          ContentDE = "Wasser, Verpflegung, ein Feuerstein ... und eine zerknitterte Karte. Ihr Besitzer hat einmal versucht, den Weg mit Holzkohle nachzuzeichnen - Linien, die sich kreuzen, überlappen und sogar über den Rand der Karte hinausgehen. Die Striche drehen sich in sinnlosen Kreisen, bevor sie abrupt aufhören und nur ein schiefes Fragezeichen übrig bleibt."
        },
        RLTreasure_IPDesc_10203 = {
          ContentDE = "Mein eifriges Kind, sei der Erste, der den Gipfel erklimmt und den Weg erhellt;\n Mein tapferer Krieger, sei der Erste, der den Kampf durchbricht und den Weg bahnt;\n Mein reinster Jünger, sei der Erste, der in die Hölle springt und das Land reinigt."
        },
        RLTreasure_IPDesc_10204 = {
          ContentDE = "Oh doppelgesichtige Gottheit, erhöre unser Gebet – mögen Klingen diese weißen Flügel zerschneiden, mögen Dolche dieses schlagende Herz durchbohren, damit wir dieses falsche Schicksal überwinden und darauf warten können, dass der Vollmond seinen Lauf umkehrt."
        },
        RLTreasure_IPDesc_10205 = {
          ContentDE = "Der kleine Vogel im Käfig, verdammt und ruhelos, kein Kissen aus Blättern, keine Träume bei Sonnenuntergang, nicht einmal der Tod kann dir Frieden geben. Also wach auf, beiß ins Leid, schluck den Schmerz hinunter und sieh zu, wie das Schicksal die Hände zur Niederlage hebt."
        },
        RLTreasure_IPDesc_10206 = {
          ContentDE = "Um dein Handwerk zu beherrschen, musst du zuerst deine Bestimmung finden und sie dann mit unerbittlicher Konzentration verfolgen."
        },
        RLTreasure_IPDesc_10207 = {
          ContentDE = "Wenn andere ihre Köpfe senken, erhebe deine Augen. Wenn andere knien, steh aufrecht. Wenn andere loben, frage. Wenn andere jubeln, wüte. \n Nur dann wirst du die Ketten des Vollmonds sprengen und die Wahrheit sehen, die das Schicksal verbirgt."
        },
        RLTreasure_IPDesc_10209 = {
          ContentDE = "Der Vogel sehnt sich danach, aufzusteigen, aber der Abgrund kennt keinen Himmel. Er sucht nach einem Ast, um sich auszuruhen, aber er findet nur die knorrigen Glieder der Angst."
        },
        RLTreasure_IPDesc_10210 = {
          ContentDE = "Verloren in einem Zyklus nach dem anderen, verzweifelt bei jedem Schritt. die Richtung ist verloren, die Zeit ist ungeschehen, das Selbst ist ausgelöscht. Der müde Reisende stapft durch die endlose Dunkelheit, begleitet von Einsamkeit und Angst, nicht ahnend, dass in den tieferen Schatten ein Augenpaar jeden seiner Schritte verfolgt."
        },
        RLTreasure_IPDesc_10211 = {
          ContentDE = "Ein Zettel ist zu einer unbekannten Zeit in deinen Rucksack gewandert. Vielleicht solltest du etwas vorsichtiger sein. Zum Glück enthält er weder Gift noch einen Fluch, sondern nur einen aufrichtigen Segen: „Gute Reise und viel Glück! – Dein Freund“"
        },
        RLTreasure_IPDesc_10212 = {
          ContentDE = "Alle Dinge sind miteinander verbunden. Die Anwendung von Logik, sowohl durch Induktion als auch durch Deduktion, kann zu unerwarteten Enthüllungen führen."
        },
        RLTreasure_IPDesc_10213 = {
          ContentDE = "Der Flammenwächter-Priester ist ein Meister der Nekromantie, der tote Seelen in seine Macht einwebt. Für ihn sind die Verstorbenen Verbündete ... bis zum Abgrund. Wessen Schatten dehnen sich im Kerzenlicht? Warum schreien ihre Seelen in Qualen? Und warum ... haben sie ihm gesagt, er solle umkehren?"
        },
        RLTreasure_IPDesc_10214 = {
          ContentDE = "Der Flammenwächter-Priester ist ein Meister der Nekromantie, der tote Seelen in seine Macht einwebt. Für ihn sind die Verstorbenen Verbündete ... bis zum Abgrund. Wessen Schatten dehnen sich im Kerzenlicht? Warum schreien ihre Seelen in Qualen? Und warum ... haben sie ihm gesagt, er solle umkehren?"
        },
        RLTreasure_IPDesc_10215 = {
          ContentDE = "Der Flammenwächter-Priester ist ein Meister der Nekromantie, der tote Seelen in seine Macht einwebt. Für ihn sind die Verstorbenen Verbündete ... bis zum Abgrund. Wessen Schatten dehnen sich im Kerzenlicht? Warum schreien ihre Seelen in Qualen? Und warum ... haben sie ihm gesagt, er solle umkehren?"
        },
        RLTreasure_IPDesc_10216 = {
          ContentDE = "Der Flammenwächter-Priester ist ein Meister der Nekromantie, der tote Seelen in seine Macht einwebt. Für ihn sind die Verstorbenen Verbündete ... bis zum Abgrund. Wessen Schatten dehnen sich im Kerzenlicht? Warum schreien ihre Seelen in Qualen? Und warum ... haben sie ihm gesagt, er solle umkehren?"
        },
        RLTreasure_IPDesc_10217 = {
          ContentDE = "Der Flammenwächter-Priester ist ein Meister der Nekromantie, der tote Seelen in seine Macht einwebt. Für ihn sind die Verstorbenen Verbündete ... bis zum Abgrund. Wessen Schatten dehnen sich im Kerzenlicht? Warum schreien ihre Seelen in Qualen? Und warum ... haben sie ihm gesagt, er solle umkehren?"
        },
        RLTreasure_IPDesc_10218 = {
          ContentDE = "Der Flammenwächter-Priester ist ein Meister der Nekromantie, der tote Seelen in seine Macht einwebt. Für ihn sind die Verstorbenen Verbündete ... bis zum Abgrund. Wessen Schatten dehnen sich im Kerzenlicht? Warum schreien ihre Seelen in Qualen? Und warum ... haben sie ihm gesagt, er solle umkehren?"
        },
        RLTreasure_IPDesc_10219 = {
          ContentDE = "Der Flammenwächter-Priester ist ein Meister der Nekromantie, der tote Seelen in seine Macht einwebt. Für ihn sind die Verstorbenen Verbündete ... bis zum Abgrund. Wessen Schatten dehnen sich im Kerzenlicht? Warum schreien ihre Seelen in Qualen? Und warum ... haben sie ihm gesagt, er solle umkehren?"
        },
        RLTreasure_IPDesc_10301 = {
          ContentDE = "Wasser, Verpflegung, ein Feuerstein ... und eine zerknitterte Karte. Ihr Besitzer hat einmal versucht, den Weg mit Holzkohle nachzuzeichnen - Linien, die sich kreuzen, überlappen und sogar über den Rand der Karte hinausgehen. Die Striche drehen sich in sinnlosen Kreisen, bevor sie abrupt aufhören und nur ein schiefes Fragezeichen übrig bleibt."
        },
        RLTreasure_IPDesc_10302 = {
          ContentDE = "Wasser, Verpflegung, ein Feuerstein ... und eine zerknitterte Karte. Ihr Besitzer hat einmal versucht, den Weg mit Holzkohle nachzuzeichnen - Linien, die sich kreuzen, überlappen und sogar über den Rand der Karte hinausgehen. Die Striche drehen sich in sinnlosen Kreisen, bevor sie abrupt aufhören und nur ein schiefes Fragezeichen übrig bleibt."
        },
        RLTreasure_IPDesc_10303 = {
          ContentDE = "„Warum hast du mich gerettet?“ Die wulstigen Augen des wiederbelebten Ritters drohen aus seinem geisterhaften Gesicht zu entweichen. „Ich wollte mit unversehrter Seele sterben – bevor mich der Wahnsinn holt!“\n Gegen alle Heilung kehrte er in die Schatten zurück. Der Ritter tritt zurück in die Dunkelheit, sein Körper ist durch die unermüdliche Fürsorge des Heilerpriesters kaum noch zu retten. Wer braucht jetzt sein Schwert?"
        },
        RLTreasure_IPDesc_10304 = {
          ContentDE = "„Wenn diese sture Ladenbesitzerin sich weigert, ihre Gewohnheiten zu ändern, werde ich mich besonders um die Kunden kümmern.“ Der Illusionist verteilte ein Kartenspiel auf dem Tisch und drehte sich um. „Nur zu – such dir so viele aus, wie du willst!“"
        },
        RLTreasure_IPDesc_10305 = {
          ContentDE = "Er ist lieber als „der Illusionist“ als als „der Freak“ bekannt. In dieser trostlosen, eintönigen Leere ist das Heraufbeschwören von Freude sein einziges Bestreben – der Preis für diese Freude spielt keine Rolle, denn er hat nichts mehr zu verlieren."
        },
        RLTreasure_IPDesc_10306 = {
          ContentDE = "Reichtum ist am besten in Hülle und Fülle – doch bloße Anhäufung ist einfach langweilig. Lass Reichtum edlere Formen annehmen, lass die Massen ein Loblied auf meine Großzügigkeit singen! Nimm dieses Geschenk an ... und füge meiner Legende eine weitere Strophe hinzu."
        },
        RLTreasure_IPDesc_10307 = {
          ContentDE = "Wahres Wissen erfordert ein Festmahl aus Seiten – koste jeden Text, oder du wirst nicht verstehen."
        },
        RLTreasure_IPDesc_10308 = {
          ContentDE = "Die Wahrheit gedeiht in der Einfachheit. Gründliches Nachdenken und sorgfältiges Überlegen können selbst bei begrenztem Wissen unschätzbare Erkenntnisse bringen."
        },
        RLTreasure_IPDesc_10309 = {
          ContentDE = "Endlose Dunkelheit droht dich zu verschlingen, doch wie durch ein Wunder flackert eine schwache Flamme aus der Glut wieder auf. Wenn der Abgrund wirklich einen Willen hat ... vielleicht weigert er sich sogar, deine Geschichte hier enden zu lassen."
        },
        RLTreasure_IPDesc_10310 = {
          ContentDE = "Ein Ritter mit einer silbernen Klinge schnitt durch die Ränge der Gegner, sein Strahlen ergoss sich wie ein aufgehender Vollmond über das Schlachtfeld. Die erschöpften Soldaten bewegten sich noch einmal unter seinem Schein.\n Ah ... die Führung der Schicksalsgöttin! Bewegt von diesem Wunder weinte das Volk vor Freude. Der Glaube verlieh den müden Gliedern neue Kraft, und so erhoben sie sich und folgten dem Licht ins Gefecht."
        },
        RLTreasure_IPDesc_10311 = {
          ContentDE = "Als die Dunkelheit den heiligen See zum ersten Mal entweihte, traten die tapfersten Ritter von Elysium hervor.\n Die meisten kehrten nie zurück. Diejenigen, die überlebten, verloren ihre Träume für immer – In dem Moment, in dem sich ihre Augen schlossen, holte der Abgrund sie zurück und zog ihre Gedanken in die Dunkelheit."
        },
        RLTreasure_IPDesc_10312 = {
          ContentDE = "Am Vorabend der Schlacht legte ein junger Ritter, der vor Kraft und Entschlossenheit strotzte, eine silberne Rüstung an, um die heiligen Zeichen zu verbergen, die sich wie Flügel über seinem Rücken entfalteten. Ein letzter Sieg für Elysium – das war alles, was er wollte, bevor er dem Ruf folgte.\n Doch der Triumph erwies sich als hohl. Ein kolossaler Filthoid zerriss Elysiums Reihen, und der Ritter verschwand spurlos. Manche sagen, dass ihn Flügel in den Himmel trugen und er seine Heimat verließ. Andere glauben, dass der dunkle Mond seinen Geist einforderte und er eins mit der Bestie wurde."
        },
        RLTreasure_IPDesc_10313 = {
          ContentDE = "Ihre Zehen berührten die Oberfläche des heiligen Sees und ließen das Wasser kräuseln, als würde ein dunkler Mond aus der Tiefe auftauchen, lichtlos und still. Wenn dieser See wirklich in das Reich des Glücks führte, warum bot er dann nicht einmal ein Spiegelbild?\n Im Nu entstand eine heftige Strömung, und die Zweifel des Heiligen wurden zusammen mit ihm vom pechschwarzen Strudel verschlungen."
        },
        RLTreasure_IPDesc_10314 = {
          ContentDE = "Die Adlige forderte, dass göttliches Blut durch ihre Adern fließt, dass sie geboren wurde, um sich zu opfern, um ihr Volk zu retten.\n Am Tag der Krönung zündete sie ihr langes Haar an und verwandelte den heiligen Ritus in eine flammende Hinrichtung. Der Tempel und alle Adligen darin wurden zu Asche. Die Flammen loderten zum Himmel, heller als die Sonne. Die Menschen, die unten schufteten, hielten ehrfürchtig inne, um das Licht zu sehen.\n Sie brannte. Sie gab. Sie rettete."
        },
        RLTreasure_IPDesc_10315 = {
          ContentDE = "Ich habe das Zeitalter der Dunkelheit erlebt, als sich die Ketzer erhoben, um den Turm in den Ruin zu stürzen.\n Da sah ich es: Tausende von Dornen stürzten von seinen Höhen herab und hüllten den Himmel in dornige Schatten. Habt keine Angst, ihr Gläubigen. Die Götter bestrafen nur die Schuldigen. Wenn die Dornen jede Sünde erwürgt haben, wird sich ein neues Zeitalter erheben – blutgetränkt, aber strahlend von der versprochenen Gnade."
        },
        RLTreasure_IPDesc_10316 = {
          ContentDE = "Sie sah, wie sich die Dunkelheit anschlich. Aber der Weg war schon verloren – wie konnte sie es ertragen, ihnen noch mehr zu nehmen?\n Also bot sie ein schimmerndes Bonbon an – einen flüchtigen Traum, vielleicht eine Lüge – irgendetwas, das ihrer Freundin ein Lächeln ins Gesicht zaubern könnte.\n Wenn es das tat, und sei es nur ein einziges Mal, war das genug."
        },
        RLTreasure_IPDesc_11101 = {
          ContentDE = "Mit neunzehn betrat er zum ersten Mal das Schlachtfeld. Die langen Klauen eines Filthoids durchbohrten den Körper eines Kameraden, den er kaum kennengelernt hatte, und hinterließen auf seinem zu spät erhobenen Schild eine blühende, scharlachrote Blume. Und einer schwache Kratzer, den kein Schrubben beseitigen konnte.\n Wofür kämpft er also noch? Für den Glauben, für die Gerechtigkeit oder einfach nur, um die Vergangenheit hinter sich zu lassen."
        },
        RLTreasure_IPDesc_11201 = {
          ContentDE = "Mit vierzehn Jahren und an seinem ersten Trainingstag wählte er dieses Schwert aus dem Stapel der Anfängerausrüstung des Händlers. Altmodisch, stichelten seine Freunde. „Pistolen sind viel praktischer!“ \n „Ritter tragen keine Pistolen“, entgegnete er, und hob die Klinge wie in den Märchenbüchern über den Kopf. „Für Elysium!“"
        },
        RLTreasure_IPDesc_12101 = {
          ContentDE = "Suche nicht nach makellosen Wegen, denn die Weisheit wandelt dazwischen. Schlage zu, wenn die Zeit reif ist, oder verliere, was hätte sein können."
        },
        RLTreasure_IPDesc_12102 = {
          ContentDE = "Töricht ist, wer materielle Dinge begehrt, denn Begierde macht verdorben. Derjenige, der ernten will, soll zuerst die Kosten der Aussaat bedenken."
        },
        RLTreasure_IPDesc_12201 = {
          ContentDE = "Unerschütterliche Geduld ist die höchste Tugend. Warte wie das Gras auf den Morgentau, denn die göttliche Gnade wird als Frühlingsregen herabkommen. Wirf weltliche Sorgen ab und gehe den strahlenden Pfad mit frommem Herzen."
        },
        RLTreasure_IPDesc_13101 = {
          ContentDE = "Kein sanftes Glühen, kein knisterndes Lagerfeuer. \n Wie ein wütendes Inferno brenne ich durch alles, was sich mir in den Weg stellt."
        },
        RLTreasure_IPDesc_13102 = {
          ContentDE = "Nicht der sanfte Regen des Frühlings, nicht der plätschernde Bach.\n Ich bin der Tsunami, der Städte ertränkt und kein Hindernis stehen lässt."
        },
        RLTreasure_IPDesc_13103 = {
          ContentDE = "Ich bin weder eine sanfte Brise noch ein flüsternder Wind.\n Ich werde der heulende Sturm sein, der Dächer zerreißt und alle Barrieren durchbricht."
        },
        RLTreasure_IPDesc_13104 = {
          ContentDE = [[
Kein Flackern des Lichts, kein Funke in der Dunkelheit.
 Ich bin der stille Donner, der die Nacht spaltet und alle in Angst und Schrecken versetzt, die vor mir stehen.]]
        },
        RLTreasure_IPDesc_14101 = {
          ContentDE = "Seit ihrer Kindheit vergötterte sie ihre Schwester – die brillante Ritterin, die jede Herausforderung meistern konnte.\n Obwohl Legenden davor warnten, dass niemand lebend aus dem Abgrund unter dem heiligen See zurückkehren würde, bewies ihre Schwester, dass sie falsch lag.\n Sie lebte ... in schrecklicher Stille."
        },
        RLTreasure_IPDesc_14201 = {
          ContentDE = "Die Erwachsenen flüstern, dass meine Schwester die Götter im heiligen See beleidigt hat und sie ihr zur Strafe ein Stück ihrer Seele genommen haben. \n Nein, meine Schwester ist eine wahre Ritterin, fromm und ehrenhaft. Ihre Seele ist dort aus Versehen verloren gegangen. Wenn niemand sonst glauben will, werde ich sie zur Einsicht bringen.\n Der Abgrund wartet auf mich, aber ich werde mit dem fehlenden Stück zurückkehren."
        },
        RLTreasure_IPDesc_14202 = {
          ContentDE = "Schwester ... bist du das? Was ist mit dir passiert? Warum richtest du dein Schwert auf mich? \n „Lügnerin ... Lügnerin ...“ Der dunkle Schatten wiederholt es mit schriller, durchdringender Stimme: „Es gibt keine Gerechtigkeit, nur Lügen.“ \n Alles kommt ihr wieder in den Sinn – der geflüsterte Wunsch ihrer Schwester, den Orden zu verlassen und ein einfaches Leben zu führen."
        },
        RLTreasure_IPDesc_14301 = {
          ContentDE = "Der Schatten verblasst, als hätte es ihn nie gegeben. Endlich sieht sie – das fehlende Stück ihrer Schwester ist für immer verschwunden. Wurde meine Anbetung zu deinem Fluch?\n Wenn ich nicht so überglücklich gewesen wäre, als du auserwählt wurdest, wärst du dann noch hier? War ich es, die dein Leben beendet hat?\n Ihre klagenden Schreie hallen in der Stille des Abgrunds wider."
        },
        RLTreasure_IPDesc_15101 = {
          ContentDE = "Warum schleppt sie ihren geschundenen Körper durch dieses endlose Labyrinth, obwohl sie weiß, dass alles umsonst ist?\n Denn egal, wo sie sich versteckt, Kathy findet sie immer. Weil Flynn, egal wie absurd die Ausrede ist, nie wütend wird. Weil sie immer noch das blutbefleckte Abzeichen in der Hand hält – schwer mit dem Gewicht des unerschütterlichen Vertrauens von jemandem.\n Denn jetzt ... trägt sie etwas in sich, vor dem sie nicht weglaufen kann."
        },
        RLTreasure_IPDesc_15201 = {
          ContentDE = "Ihr ganzes Leben lang hat sie den Weg einer Drückebergerin gewählt. Sie übersprang die Auswahl der Heiligen Baumakademie und strebte nach ihrem Eintritt in den Ritterorden nicht ein einziges Mal eine Beförderung an.\n Niemand steigt für immer auf. Es ist besser, dort zu bleiben, wo sie am Anfang stand, als einem Gipfel hinterherzujagen, von dem sie zwangsläufig fallen würde."
        },
        RLTreasure_Name_10101 = {
          ContentDE = "Ewiges Licht des Künstlers"
        },
        RLTreasure_Name_10102 = {
          ContentDE = "Coupon der mysteriösen Händlerin"
        },
        RLTreasure_Name_10103 = {
          ContentDE = "Heilige heilende Seife"
        },
