        SKILL_10102_DESC = {
          ContentDE = "Auslöserate +<H>#1</>. Wenn ein Hydro-Figur mit dieser Waffe einen Bonuseffekt auslöst, erhalten alle anderen Verbündeten +<H>#2</> ANG für <H>#3</> Sek."
        },
        SKILL_10103_DESC = {
          ContentDE = "Angriffsreichweite +<H>#1</>. Wird mit dieser Waffe ein KRIT gelandet, besteht eine Chance von <H>#2</>, <H>#3</> Punkte Geist wiederherzustellen. Kann einmal alle <H>#4</> Sek. ausgelöst werden."
        },
        SKILL_10104_DESC = {
          ContentDE = "VTD +<H>#1</>. Wird mit dieser Waffe ein SCH verursacht, wird ein Bonuseffekt ausgelöst, mit einer Chance von <H>#3</>, den Schild des Ziels um <H>#2</> der VTD des Anwenders zu reduzieren."
        },
        SKILL_10105_DESC = {
          ContentDE = "Angriffs-GES +<H>#1</>. Wird mit dieser Waffe ein geladener Angriff ausgeführt, besteht eine Chance von <H>#2</>, die Abk. der Resonanz-Unterstützung um <H>#3</> Sek. zu verkürzen."
        },
        SKILL_10201_DESC = {
