        },
        SKILL_110304_NAME = {ContentDE = "Konzert"},
        SKILL_150001_DESC = {
          ContentDE = "<H>[Nur verfügbar, wenn als Kampfbegleiter eingesetzt]</>\n Erhöht den ANG für sich selbst und Lumino-Verbündete."
