        Two = {ContentDE = "2"},
        UIGUIDE_AMMO = {
          ContentDE = "Es besteht die Chance, Munitionsvorräte zu erhalten, indem du Gegner besiegst, Truhen öffnest oder zerbrechliche Objekte zerstörst. Mit diesen Vorräten kannst du die Geschosse für Fernkampfwaffen auffüllen."
        },
        UIGUIDE_ATTACK = {
          ContentDE = "Drücke &Attack&, um Nahkampfangriff auszuführen."
        },
        UIGUIDE_CHARGEATTACK = {
          ContentDE = "Halte &Attack& gedrückt, um einen geladenen Angriff auszuführen."
        },
        UIGUIDE_EXECUTION_01 = {
          ContentDE = "Starke Gegner behalten ihre Kampfhaltung bei, die durch Angriffe <Highlight>geschwächt</> werden kann. Die Gegner <Highlight>verlieren das Gleichgewicht</>, wenn ihre Haltung bis zu einem bestimmten Grad geschwächt ist, und sobald sie vollständig geschwächt ist, werden sie für kurze Zeit <Highlight>betäubt</>."
        },
        UIGUIDE_EXECUTION_02 = {
          ContentDE = "Betäubte Gegner werden verwundbar und zeigen ihre Schwäche. In diesem Moment <H>kann man sich ihnen nähern, um einen mächtigen Schlag auszuführen</>. Einige Daimons bezeichnen dies als <H>Asks Vergeltung</>, was sowohl Zerstörung als auch Gelegenheit bringt.</>"
        },
        UIGUIDE_FALLATTACK = {
          ContentDE = "Drücke &Attack& in der Luft, um einen Sturzangriff auszuführen."
        },
        UIGUIDE_GUN = {
          ContentDE = "Fernkampfwaffen eignen sich ideal, um Gegner in der Ferne oder auf erhöhter Position zu besiegen. Beachte die Begrenzungen von Magazin und Munition."
        },
        UIGUIDE_HPSHIELD = {
          ContentDE = [[
Wenn eine Figur angegriffen wird, wird zuerst das <Highlight>Schild</> verbraucht.
 Sobald das <Highlight>Schild</> aufgebraucht ist, verringern weitere Angriffe die <Highlight>LP</>.]]
        },
        UIGUIDE_PARTIALDAMAGE_01 = {
          ContentDE = "Einige Gegner haben leuchtende Teile, die zerstörbar sind, und jedes Teil hat seine <Highlight>eigene LP</>."
        },
        UIGUIDE_PARTIALDAMAGE_02 = {
          ContentDE = "Wenn die LP eines zerstörbaren Teils auf 0 reduziert werden, gerät der Gegner in den <Highlight>Gebrochenen Zustand</>, der die <Highlight>Kampfhaltung des Gegners deutlich schwächt</>."
        },
        UIGUIDE_PARTIALDAMAGE_03 = {
          ContentDE = "Wenn ihre Kampfhaltung bis zu einem bestimmten Grad geschwächt ist, wird der Gegner <Highlight>das Gleichgewicht verlieren</>."
        },
        UIGUIDE_PARTIALDAMAGE_04 = {
          ContentDE = "Sobald die Kampfhaltung eines Gegners vollständig geschwächt ist, wird er für kurze Zeit <Highlight>betäubt</>. <Highlight>Während der Haltungserholung</> <Highlight>wird die Schwachstelle des Gegners aufgedeckt</> und er erleidet deutlich mehr Schaden."
        },
        UIGUIDE_PARTIALDAMAGE_05 = {
          ContentDE = "Die Rüstung von Kristallophage ist zerstörbar, und jedes Teil hat seine <Highlight>eigene LP</>."
        },
        UIGUIDE_PARTIALDAMAGE_06 = {
          ContentDE = "Solange <Highlight>irgendeine</> Rüstung vorhanden ist, bleibt Kristallophage <Highlight>unbesiegbar</>. Wenn die LP eines zerstörbaren Teils auf 0 reduziert werden, gerät Kristallophage in den <Highlight>Gebrochenen Zustand</> und verliert das Gleichgewicht."
        },
        UIGUIDE_PARTIALDAMAGE_07 = {
          ContentDE = "Wenn Kristallophage <Highlight>das Gleichgewicht verliert</>, wird es für kurze Zeit <Highlight>betäubt</> und <Highlight>verliert seine Unverwundbarkeit</>."
        },
        UIGUIDE_PARTIALDAMAGE_08 = {
          ContentDE = "Wenn die gesamte Rüstung zerstört ist, wird Kristallophage <Highlight>vollständig betäubt</> und seine <Highlight>Schwachstelle aufgedeckt</>. Wenn du <Highlight>Asks Vergeltung</> in diesem Moment auf seinen <Highlight>Kopf</> einsetzt, <Highlight>wird es sofort besiegt</>."
