        UIGuide_LockMonster_PC = {
          ContentDE = "Drücke &LockMonster&, um einen <H>Boss-Gegner</> anzuvisieren. Drücke erneut, um abzubrechen."
        },
        UIGuide_LockMonster_Phone = {
          ContentDE = "Tippe auf &LockMonster&, um einen <H>Boss-Gegner</> anzuvisieren. Tippe erneut, um abzubrechen."
