        UIGuide_LongLin_2 = {
          ContentDE = "Nutze den Ziehmodus der Mechanischen Nexus, um <H>Gritblight</> zu entfernen."
        },
        UIGuide_LongLin_3 = {
          ContentDE = "Sobald das Gritblight vollständig beseitigt ist, zieht die aktivierte Zhuyin-Schuppe Filthoiden an. Gleichzeitig taucht in der Nähe mehr Gritblight auf und verdichtet sich allmählich."
        },
        UIGuide_LongLin_4 = {
