        UIGuide_ModTendency_3 = {
          ContentDE = "Wenn du einen Dämonenkeil in einem <H>neutralen</> Platz ausrüstest, wird die erforderliche Toleranz <H>nicht geändert</>. Wenn du einen <H>neutralen</> Dämonenkeil in einem beliebigen Platz ausrüstest, wird die erforderliche Toleranz <H>nicht geändert</>."
        },
        UIGuide_ModTendency_4 = {
          ContentDE = "Wenn du einen Dämonenkeil in einem Platz mit der <H>gleichen Spur</> ausrüstest, wird die erforderliche Toleranz aufgrund der Synergie zwischen dem Dämonenkeil und dem Träger <H>gesenkt</>."
