        UIGuide_ModTendency_5 = {
          ContentDE = "Wenn du einen Dämonenkeil in einem Platz mit <H>unterschiedlichen Spuren</> ausrüstest, wird die erforderliche Toleranz aufgrund der gegenseitigen Abstoßung zwischen dem Dämonenkeil und dem Träger <H>erhöht</>."
        },
        UIGuide_MonsterExitMechanism_1 = {
          ContentDE = "Auf dieser Passage erscheinen regelmäßig Gegner. Die Passage kann nur versiegelt werden, indem du <H>bestimmte Schwachstellen mit geeigneten Mitteln angreifst</>."
