        UIGuide_MonsterExitMechanism_2 = {
          ContentDE = "Auf dieser Passage erscheinen regelmäßig Gegner. Du kannst entweder <H>mit bestimmten Geräten interagieren</> oder <H>alle Gegner besiegen</>, um die Passage zu versiegeln."
        },
        UIGuide_Online_01_01 = {
          ContentDE = "Wenn du alleine oder zusammen mit Freunden eine private Mission spielst, können andere Spieler unterwegs <H>nicht beitreten</>."
        },
        UIGuide_Online_01_02 = {
          ContentDE = "Wenn du alleine oder zusammen mit Freunden eine öffentliche Mission spielst, können andere Spieler unterwegs <H>beitreten</>."
        },
        UIGuide_Online_02_01 = {
          ContentDE = "Im Einzelspieler-Modus beginnt eine private Mission sofort, nachdem du sie ausgewählt hast."
        },
        UIGuide_Online_02_02 = {
          ContentDE = "Im Mehrspieler-Modus müssen alle Mitglieder eine private Mission <H>innerhalb von 10 Sekunden bestätigen</>. Sobald alle bestätigt haben oder die Zeit abgelaufen ist, beginnt die Mission."
        },
        UIGuide_Online_03_01 = {
          ContentDE = "Im Einzelspieler-Modus sucht das System <H>10 Sekunden lang</> nach öffentlichen Missionen, bei denen du einsteigen kannst; wird keine passende Mission gefunden, wird die Mission von Beginn an gestartet. Die Suche kann jederzeit innerhalb des 10-Sekunden-Zeitraums abgebrochen werden."
        },
        UIGuide_Online_03_02 = {
          ContentDE = "Im Mehrspieler-Modus sucht das System <H>10 Sekunden lang</> nach öffentlichen Missionen, bei denen dein Team einsteigen kann. Wird eine passende Mission gefunden, startet sie, sobald <H>alle Teammitglieder zugestimmt haben</>. Wird keine passende Mission gefunden, startet dein Team die Mission von Anfang an. Die Suche kann innerhalb der <H>10 Sekunden</> jederzeit von einem Teammitglied abgebrochen werden."
        },
        UIGuide_Online_04_01 = {
          ContentDE = "Die Ziele der Missionen sind im Einzelspieler- und Mehrspieler-Modus gleich. Aber die <H>Schwierigkeit</> <H>erhöht sich</> mit der Anzahl der Spieler. Je größer das Team ist, desto mehr Gegner erscheinen, und desto höher sind ihre Stufen."
        },
        UIGuide_Online_04_02 = {
          ContentDE = "Am Ende jeder Runde einer jeden Mission ∞ erfolgt eine Abstimmung. Spieler, die für das Weitermachen stimmen, ziehen in die nächste Runde ein, während diejenigen, die sich für den Rückzug entscheiden, ausscheiden. Die Auswahl eines Spielers <H>hat keinen Einfluss auf die der anderen</>."
        },
        UIGuide_Online_04_03 = {
          ContentDE = "Sobald ein Teammitglied den Evakuierungspunkt erreicht hat, beginnt ein <H>30-sekündiger</> Countdown. Die Mission wird automatisch abgeschlossen, sobald der Timer abgelaufen ist, und wenn alle Teammitglieder während des Countdowns den Evakuierungspunkt erreichen, wird die Mission sofort abgeschlossen."
        },
        UIGuide_Online_05_01 = {
          ContentDE = "Jedes Teammitglied hat eine begrenzte Anzahl von Wiederbelebungschancen. Wenn du besiegt wirst, startet ein 20-Sekunden-Timer. Wenn du vor Ablauf der Zeit nicht „Wiederbeleben“ auswählst, scheitert die Mission."
        },
        UIGuide_Online_05_02 = {
          ContentDE = "Wenn ein Teammitglied sich bei einem Mehrspieler-Auftrag für eine Wiederbelebung entscheidet, können ihm andere Spieler helfen, indem sie sich ihm nähern und so die Wiederbelebung beschleunigen."
        },
        UIGuide_Online_06_01 = {
          ContentDE = "Teams, die vor Beginn einer öffentlichen Mission gebildet wurden, bleiben auch nach Ende der Mission bestehen, während Spieler, die erst während der Mission eingestiegen sind, das Team nach der Mission automatisch verlassen."
        },
        UIGuide_OverloadShield = {
          ContentDE = "Bonusschild eines Charakters, der auf bestimmte Weisen erhalten wird. Ultra-Schild wird <H>zuerst verbraucht</>, wenn man Schaden erleidet. Die Obergrenze von Ultra-Schild erhöht sich mit steigender <H>Figurenstufe</>."
        },
        UIGuide_PerfectDodge = {
          ContentDE = "Wenn du starken Gegnern im Kapitel Dämmerung gegenüberstehst, <H>verlangsamen</> nahe Gegner kurzzeitig, wenn du im letzten Moment eines gegnerischen Angriffs <H>Ausweichst</>."
        },
        UIGuide_PetPan_01 = {
          ContentDE = "Paniemon – die klügsten aller Geniemon! Du findest ihre Spuren überall."
