        UIGuide_SpecialDestructible_1 = {
          ContentDE = "Einige Objekte können nur durch <H>spezielle Bonuseffekte</> oder <H>besonderen Fähigkeits-SCH</> zerstört werden, die einen bestimmten Schaden verursachen."
        },
        UIGuide_SpecialDestructible_2 = {
          ContentDE = "Beispielsweise kann man das <H>Kryolit</>, das einige Truhen bedeckt, mit <H>dem Bonuseffekt: Erschütterung, dem Bonuseffekt: Pyro oder Fähigkeiten mit Pyro-SCH</> zerschmettern.\n (Du kannst die <H>Elemente</> der Figuren und der Waffe und die <H>Auslöserate</> der Bonuseffekte in der Bewaffnung ansehen.)"
        },
        UIGuide_SpecialDestructible_3 = {
          ContentDE = "Einige Objekte können nur durch <H>spezielle Bonuseffekte</> oder <H>besonderen Fähigkeits-SCH</> zerstört werden, die einen bestimmten Schaden verursachen.\n <H>Umbro-Reben</>, die einige Truhen umschlingen, können mit dem <H>Bonuseffekt: Hieb, dem Bonuseffekt: Lumino oder Fertigkeiten mit Lumino-SCH</> zerstört werden.\n (Du kannst die <H>Elemente</> der Figuren und der Waffe und die <H>Auslöserate</> der Bonuseffekte in der Bewaffnung ansehen.)"
        },
        UIGuide_SpecialDestructible_4 = {
          ContentDE = "Einige Objekte können nur durch <H>spezielle Bonuseffekte</> oder <H>besonderen Fähigkeits-SCH</> zerstört werden, die einen bestimmten Schaden verursachen.\n <H>Kies</>, der einige Truhen bedeckt, kann mit dem <H>Bonuseffekt: Erschütterung</> zerschmettert werden.\n (Du kannst die <H>Elemente</> der Figuren und der Waffe und die <H>Auslöserate</> der Bonuseffekte in der Bewaffnung ansehen.)"
        },
        UIGuide_SpecialDestructible_5 = {
