        UI_AcceptEntrust = {ContentDE = "Annehmen"},
        UI_Accessory_Desc_10001 = {
          ContentDE = "Küken JoeJoe, die Hauptfigur von „JoeJoes wundersame Abenteuer“, einem bekannten Märchen vom Kontinent Atlasia, erzählt in dem Buch seine eigene Geschichte: Jeden Tag erwacht es an einem neuen Ort, freundet sich mit neuen Gefährten an und begibt sich auf bizarre Abenteuer, um den Sinn des Kükenseins zu entdecken und gleichzeitig die Pläne des Bösewichts zu durchkreuzen."
        },
        UI_Accessory_Desc_10002 = {
          ContentDE = "ACHTUNG: NICHT ESSBAR!"
        },
        UI_Accessory_Desc_10003 = {
          ContentDE = "Belebt, liebenswert, lebhaft, wunderschön ... Es gibt keine Worte auf der Welt, die dem magischen Reiz dieser Katzenohren gerecht werden."
        },
        UI_Accessory_Desc_10004 = {
          ContentDE = "Diese tragbare Edition von Cinder, durchdrungen von der reichen Inspiration und Leidenschaft der Luno-Schmiedin, erinnert einen stets an das lodernde Feuer, das Cinder unermüdlich entfacht."
        },
        UI_Accessory_Desc_10005 = {
          ContentDE = "Ein Symbol der Eleganz, die Verkörperung der Anmut – oder vielleicht nur ein Schmetterling, der seine Flügel nicht mehr schlagen kann."
        },
        UI_Accessory_Desc_10006 = {
          ContentDE = "In jedem Zeitalter üben Drachen eine unwiderstehliche Faszination aus – mächtig, ungezähmt und schwer zu fassen erscheinen sie fern und geheimnisvoll zugleich. Gerade dieses vage, nebelhafte Bild macht sie zur perfekten Leinwand für grenzenlose Vorstellungen."
        },
        UI_Accessory_Desc_10007 = {
          ContentDE = "Unter der Eierschale ist wieder nur Eierschale, unter der Eierschale ist nichts als Eierschale und auf keinen Fall Luno, ganz bestimmt nicht!"
        },
        UI_Accessory_Desc_10008 = {
          ContentDE = "So geht es mir heute genau."
        },
        UI_Accessory_Desc_10012 = {
          ContentDE = "Mit diesem Teil bist du außerordentlich geschickt darin, schwierige Probleme zu „bohren“."
        },
        UI_Accessory_Desc_10013 = {
          ContentDE = "Eine Maske, die den Ahnen von Huaxu ehrt. Wenn du sie trägst, entsteht vor dir die epische Vision unzähliger gerüsteter Krieger mit verhüllten Gesichtern, die den Kosmos gestalteten, um ein Reich ewigen Friedens zu schaffen."
        },
        UI_Accessory_Desc_10014 = {
          ContentDE = "Früher diente diese Maske als Medium für die Kommunikation mit den Göttern, um ihren Segen zu erbitten. Heute richten diejenigen, die nach der Gnade des Göttlichen suchen, ihre Gebete aus der Ferne zum Hohen Turm von Elysium."
        },
        UI_Accessory_Desc_10024 = {
          ContentDE = "Die gewählte Nummer ist nicht erreichbar. Nicht heute, nicht morgen ... und niemals."
        },
        UI_Accessory_Desc_10026 = {
          ContentDE = "Werbeanzeigen sind heute überall und in fast jedem Aspekt des Lebens vorgedrungen."
        },
        UI_Accessory_Desc_10028 = {
          ContentDE = "Ein Funke Genialität."
        },
        UI_Accessory_Desc_10029 = {
          ContentDE = "Eines der Werbegeschenke von „Geschichten von Icelake“."
        },
        UI_Accessory_Desc_10030 = {
          ContentDE = "Ein feiner kleiner Schirm, der Wind und Regen schützen sollte – leider fällt die Größe etwas kleiner aus als auf den Verkäuferfotos."
        },
        UI_Accessory_Desc_10031 = {
          ContentDE = "Selbst geschmolzene Flammen können fromme Tränen und Gebete nicht versengen."
        },
        UI_Accessory_Desc_10032 = {
          ContentDE = "Ein seidiges Flattern, der im Lüftchen tanzt – wartend, den nächsten glücklichen Haarstrang zu zieren."
        },
        UI_Accessory_Desc_10033 = {
          ContentDE = "Jede Axt, die in einen See fällt, zielt höchstwahrscheinlich auf den Schädel einer unschuldigen Nymphe."
        },
        UI_Accessory_Desc_10034 = {
          ContentDE = "zZZ...zZZ...zZZ...zZZ...zZZ..."
        },
        UI_Accessory_Desc_10035 = {
          ContentDE = "Katzen-Kopfschmuck"
        },
        UI_Accessory_Desc_10036 = {
          ContentDE = "Es klappert der Geweihe!"
        },
        UI_Accessory_Desc_10037 = {
          ContentDE = "So geht es mir heute genau."
        },
        UI_Accessory_Desc_10049 = {
          ContentDE = "Eine von Auroraleuchtem gegossene Kleinkrone, Zeugin ehrlicher Gelübde von Wärme und Liebe."
        },
        UI_Accessory_Desc_10050 = {
          ContentDE = "Der kleine Vogel hat sein gemütliches Nest verlassen. Welche Geschichte wird er dieses Mal mitbringen?"
        },
        UI_Accessory_Desc_10052 = {
          ContentDE = "Bei den Leuten aus Huaxu haucht eine Zuneigung für ein robustes Geschöpf aus vergangenen Zeiten – ein Gefühl, das heute in dieses Schmuckstück eingewebt ist."
        },
        UI_Accessory_Desc_10053 = {
          ContentDE = "Kein sengender Sonnenbrand kann uns davon abhalten, einen ganzen Sommer in unserem Blick zu tragen."
        },
        UI_Accessory_Desc_10056 = {
          ContentDE = "Was geschehen ist, kann nicht rückgängig gemacht werden."
        },
        UI_Accessory_Desc_10057 = {
          ContentDE = "Einige wurden nach dem Bericht des erfahrenen Reisenden zu echten Fans der Phoxfuchses. Diese Kopfbedeckung zu tragen, ist eine der Möglichkeiten, wie man das zeigen kann."
        },
        UI_Accessory_Desc_11002 = {
          ContentDE = "Wenn die Feuerwerke blühen, heben sie meine Seele in ein einsames Sternenmeer."
        },
        UI_Accessory_Desc_11003 = {
          ContentDE = "Ein Samenkorn des Sommers rieselt aus den Wolken, wo Gischt und sengender Sand zu einer flüchtigen Ewigkeit erblühen."
        },
        UI_Accessory_Desc_20001 = {
          ContentDE = "Weisheit, präzise von diesem runden Rahmen umschlossen, die Weisheitsaura des Trägers stark verstärkend."
        },
        UI_Accessory_Desc_20002 = {
          ContentDE = "Augen sind für uns nichts weiter als Hindernisse, um die Welt wahrhaft zu beobachten und wahrzunehmen."
        },
        UI_Accessory_Desc_20003 = {
          ContentDE = "Ein Schmetterling, der durch Stürme flattert und eine stille Wache hält für diejenigen, die vom Grollen des Donners beunruhigt sind – bis der Sturm verstummt und die Angst nachlässt."
        },
        UI_Accessory_Desc_20004 = {
          ContentDE = "Nach der Überlieferung bestimmter Charon-Stämme entsteht dieser nebelgeborene Schmetterling jeden Tag aus den weißen Blüten der Mutter Embla – nur um dann in den dämmernden Nebeln des Vaters Ask zu vergehen."
        },
        UI_Accessory_Desc_20005 = {
          ContentDE = "Eine schnelle Hilfe bei plötzlichem Unwohlsein."
        },
        UI_Accessory_Desc_20006 = {
          ContentDE = "Giftiger Rauch, Feuer, Rauch, Sand und Staub ... Diese schlichte Struktur verdeutlicht, dass das Erhalten der Überlebenschance niemals einfach ist."
        },
        UI_Accessory_Desc_20007 = {
          ContentDE = "Der Sehnsucht nach dem Himmel konnten die irdischen Grenzen nicht entrinnen. Die ausgestreckten Flügel erzählen Bände über die Sehnsucht nach Freiheit."
        },
        UI_Accessory_Desc_20008 = {
          ContentDE = "Er lässt das Publikum immer wieder fragen, ob im nächsten Moment eine Taube oder eine Rose sich enthüllen wird."
        },
        UI_Accessory_Desc_20010 = {
          ContentDE = "Dieser falsche Schnurrbart verleiht seinem Träger eine Aura von Ernsthaftigkeit und Weisheit – er verlangt jedoch gelegentliche Anpassungen, um sicherzustellen, dass er fest auf seinem Platz bleibt."
        },
        UI_Accessory_Desc_20011 = {
          ContentDE = "Erweitere deine Perspektive und sieh, wie sich die Welt vor deinen Augen entfaltet."
        },
        UI_Accessory_Desc_20026 = {
          ContentDE = "Auch wenn die Vergangenheit nicht wiedererlebt werden kann, lass weder deine Träume noch die Spuren deines Daseins im Schweigen verblassen."
        },
        UI_Accessory_Desc_20027 = {
          ContentDE = "Ein purpurrotes Amulett schwingt neben dem Monokel im Wind – als hätte irgendein Gelehrter, an irgendeinem Ort, gerade eine Seite umgeblättert."
        },
        UI_Accessory_Desc_20028 = {
          ContentDE = "Spüre diese frische, lebensvolle, heitere Luft."
        },
        UI_Accessory_Desc_20029 = {
          ContentDE = "Das Seelenfenster schließen."
        },
        UI_Accessory_Desc_20030 = {
          ContentDE = "In der Vergangenheit nutzte jemand es, um sich in einen Dämon zu verwandeln und der Flut des Lichts zu widerstehen. Nun beiseitegeworfen – damit es die Götter nicht erneut provoziert."
        },
        UI_Accessory_Desc_20031 = {
          ContentDE = "Oink, oink – oiiiink!"
        },
        UI_Accessory_Desc_20036 = {
          ContentDE = "Auch durch verschleierte Sicht lässt sich der Glanz der Welt noch spüren."
        },
        UI_Accessory_Desc_20039 = {
          ContentDE = "Weisheit, perfekt gerahmt. Diese spiegelnden Brillen verstärken die Intelligenz-Aura enorm ... oder zumindest lassen sie dich unglaublich nachdenklich wirken."
        },
        UI_Accessory_Desc_20040 = {
          ContentDE = "Was schimmert da in ihren Augen – Tränen oder die sanften Wellen des Mondscheins?"
        },
        UI_Accessory_Desc_20041 = {
          ContentDE = "Kinder, seid ihr bereit für eure Geschenke?"
        },
        UI_Accessory_Desc_20043 = {
          ContentDE = "Ein Schutz vor blendendem Licht und Staub, offenlegend, was echt ist und was nicht."
        },
        UI_Accessory_Desc_21002 = {
          ContentDE = "Schwebe zwischen den Sternen und lausche dem Flüstern vergangener Jahrhunderte."
        },
        UI_Accessory_Desc_21003 = {
          ContentDE = "Surfe über die Wellen und rase über die Brandung hinweg."
        },
        UI_Accessory_Desc_30001 = {
          ContentDE = "Ein Leuchtfeuer, das du bei dir behalten sollst. Eine ständige Trostquelle auf deiner Reise."
        },
        UI_Accessory_Desc_30002 = {
          ContentDE = "Mit Zirruswolken, die Sonne und Mond wälzen, tausend Gedanken darin verstreut; mit einer Kalebasse, die ein Universum birgt, zehntausend Verse darin verborgen."
        },
        UI_Accessory_Desc_30003 = {
          ContentDE = "Das Leben ist wie eine einsame Fahrt durch die unendliche Dunkelheit der Nacht. Der Fluss weint, mit dornigen Dickichten an seinen traurigen Ufern."
        },
        UI_Accessory_Desc_30004 = {
          ContentDE = "Ein nach Aeolipile-Design gefertigter Behälter zur sicheren Aufbewahrung von Phoxichor. Noch immer extrem beliebt – selbst wenn er leer ist."
        },
        UI_Accessory_Desc_30005 = {
          ContentDE = "Ein Leuchtfeuer in den Tiefen – heller als Angst, stabiler als Atem."
        },
        UI_Accessory_Desc_30006 = {
          ContentDE = "An Türen aufhängtes Hausvordachlicht, für die Verlorenen, die Verspäteten und jene, die noch auf der Suche nach ihrem Heimweg sind."
        },
        UI_Accessory_Desc_30007 = {
          ContentDE = "Es hat eine Magie, die einen einfach nicht aufhören lässt, es zu schwingen."
        },
        UI_Accessory_Desc_30008 = {
          ContentDE = "Dunkelheit und Licht, in Jade eingeschlossen; Himmel und Erde, in Bogen ausgerichtet."
        },
        UI_Accessory_Desc_30009 = {
          ContentDE = "Wirf es. Vertraue ihm. Versuche es erneut, wenn es dein Leben ruiniert."
        },
        UI_Accessory_Desc_30010 = {
          ContentDE = "Erhalten durch spezielle Aktion."
        },
        UI_Accessory_Desc_30016 = {
          ContentDE = "An einem Vollmond geschmiedet, strahlt dieses berühmte Säbel stetig. Kippe die Klinge sanft – Mondlicht wellt sich über das Stahlblatt."
        },
        UI_Accessory_Desc_30017 = {
          ContentDE = "Wenn das Märchenbuch schließt, beginnt die wahre Magie – mit dem Mut, den uns seine Geschichten schenken, umarmen wir eine weit von Perfektion entfernte Welt."
        },
        UI_Accessory_Desc_30018 = {
          ContentDE = "Ein sanfter Schimmer teilt die Nacht, und der sanfte Schein des Mondes führt dich nach Hause."
        },
        UI_Accessory_Desc_30019 = {
          ContentDE = "Eingehüllt in die herzlichen Erinnerungen der Kinder schlummert der Schneemann durch die lange Winternacht."
        },
        UI_Accessory_Desc_30020 = {
          ContentDE = "Halte die Gewalt der Himmel in deiner Hand."
        },
        UI_Accessory_Desc_40001 = {
          ContentDE = "Auch die feinsten Feuchtigkeitsänderungen entgehen der Wahrnehmung eines Phoxfuchsschwanzes nicht. Erfahrene Reisende beobachten oft, ob ein Phoxfuchs in der Regennacht alleine tanzt – um so zu bestimmen, wann die Wolken sich auflösen und das Mondlicht zurückkehren wird."
        },
        UI_Accessory_Desc_40002 = {
          ContentDE = "Die Klinge schützt und verletzt zugleich; sie trägt die Würde und den Glauben all ihrer früheren Besitzer. Über Jahrzehnte hat sie die Ermahnungen aus alter Zeit bis in die Gegenwart weitergetragen."
        },
        UI_Accessory_Desc_40003 = {
          ContentDE = "Gib mir einen Hebel, und ich werde die Welt umkehren. Oder zumindest diesen Reifen."
        },
        UI_Accessory_Desc_40004 = {
          ContentDE = "Nicht jeder Held trägt Rüstung. Manche tragen Gusseisen."
        },
        UI_Accessory_Desc_40005 = {
          ContentDE = "Versinke in der Dunkelheit und jage dem Licht nach."
        },
        UI_Accessory_Desc_40006 = {
          ContentDE = "Der mächtigste Rucksack aller Reiche – zumindest laut der Dämonenkönigin des Lichts."
        },
        UI_Accessory_Desc_40007 = {
          ContentDE = "Umarme auf den Flügeln des Windes die Freiheit am Horizont."
        },
        UI_Accessory_Desc_40008 = {
          ContentDE = "Bei den Leuten aus Huaxu haucht eine Zuneigung für ein robustes Geschöpf aus vergangenen Zeiten – ein Gefühl, das heute in dieses Schmuckstück eingewebt ist."
        },
        UI_Accessory_Desc_40009 = {
          ContentDE = "Zwar wirken sie zerbrechlich, doch solche Flügel können Kinder sicher durch die härtesten Winter tragen."
        },
        UI_Accessory_Desc_40010 = {
          ContentDE = "Ein alter Umhang, einst getränkt von Fantasien um „Helden“. Vielleicht wird er eines Tages wieder das Licht erblicken, oder auch nie."
        },
        UI_Accessory_Desc_40011 = {
          ContentDE = "Jingle Bells, Jingle Bells, jingle all the way ..."
        },
        UI_Accessory_Desc_40014 = {
          ContentDE = "Oh Flügel, weich wie die eines Kükens, tragt meine Sehnsucht und fliegt zum Horizont, wo das Licht wartet."
        },
        UI_Accessory_Desc_40016 = {
          ContentDE = "Einige wurden nach dem Bericht des erfahrenen Reisenden zu echten Fans der Phoxfuchses. Dieses Hüftteil zu tragen, ist eine der Möglichkeiten, wie man das zeigen kann."
        },
        UI_Accessory_Desc_60002 = {
          ContentDE = "Winke den Sternen zum Abschied."
        },
        UI_Accessory_Desc_70001 = {
          ContentDE = "Ein Schmetterling flattert, der den Mittsommer aus seinem Schlummer weckt."
        },
        UI_Accessory_Desc_70002 = {
          ContentDE = "Der Weg in die Zukunft sieht quakend rosig aus."
        },
        UI_Accessory_Desc_80001 = {
          ContentDE = "Mit Stiefmütterchen beladen, erwarten die Schmetterlinge das Erscheinen des Sterns, um die große Ouvertüre des Balls einzuleiten."
        },
        UI_Accessory_Desc_80002 = {
          ContentDE = "Blasen blühen, wenn die Fischschwärme hervorrauschen, um dem fröhlichen Lied des Ozeans beizutreten."
        },
        UI_Accessory_Desc_90001 = {
          ContentDE = "Berenicas Lieblingsumhang. Wenn der Meereswind weht, rasselt er wie ein Seevogel, der schweigend seine Federn spreizt."
        },
        UI_Accessory_Desc_90002 = {
          ContentDE = "Obwohl das Tüllmaterial keinen wirksamen Windschutz bot, liebte Rebecca schlicht die Leichtigkeit, von einem hauchdünnen Gewand umhüllt zu sein."
        },
        UI_Accessory_Desc_90003 = {
          ContentDE = "Die von ihrem Rücken herabhängenden Gliedmaßen sind keine bloßen Schmuckstücke – geschickt und zielstrebig bewegen sie sich mit ihrem Willen eins und sind die perfekten Komplizen einer Meisterdiebin. Sie haben durch die Schatten jeder Stadt getanzt und sich unter dem Schleier der Nacht erfreut."
        },
        UI_Accessory_Desc_90004 = {
          ContentDE = "Geflochtenes Leder, fest wie Ketten. Trag ihr Gewicht und bestraf alles Böse."
        },
        UI_Accessory_Desc_90005 = {
          ContentDE = "Einhundert Frühlinge, heiter und still; kein Wogen stört den ruhigen Willen. Jahre mögen fließen, Jahreszeiten erneuern sich; doch das Herz bleibt beständig und treu."
        },
        UI_Accessory_Desc_90006 = {
          ContentDE = "Gefertigt von der Kaiserlichen Alchemie-Akademie ausschließlich für die angesehensten Alchimisten. Dieser Umhang ist ein Zeichen höchster Ehre und Anerkennung."
        },
        UI_Accessory_Desc_90007 = {
          ContentDE = "Ein Umhang, den Outsider genäht und gepatcht hat. Seine kreuzweise durchlöcherten Stellen und der zerrissene Schnitt wurden auf mysteriöse Weise zu einem Symbol für Stil und Selbstbewusstsein unter den Kindern von Mist Aken."
        },
        UI_Accessory_Desc_90008 = {
          ContentDE = "Um einen ganzen Text von Hand abzuschreiben, überredete der Junge seinen Freund, ihm seinen ersten Umhang zu nähen – genäht aus dem verblassten Samt eines alten Theatervorhangs. Er war weder edel noch verziert, doch wenn er ihn trug, erinnerte er ihn an die galanten Ritter aus den Stücken. Doch das alles lag ... schon sehr, sehr lange zurück."
        },
        UI_Accessory_Desc_90009 = {
          ContentDE = "„Es ist nur ein Umhang. Ich mochte den Look, also habe ich ihn angezogen. Das ist alles.“"
        },
        UI_Accessory_Desc_90010 = {
          ContentDE = "Ein alter Umhang, einst getränkt von Fantasien um „Helden“. Lynn sperrte ihn weg – vielleicht wird er eines Tages wieder das Licht erblicken, oder auch nie."
        },
        UI_Accessory_Desc_90011 = {
          ContentDE = "Ein Umhang der 6. Legion, erkämpft durch Rhythms unermüdliche Anstrengungen. Er markierte ihren ersten Schritt auf dem Weg zu ihrem Traum ... und ihren letzten."
        },
        UI_Accessory_Desc_90012 = {
          ContentDE = "Sein Saum flattert im kalten Wind und erinnert an den sanften weißen Sand der Purgatorio-Insel und an zwei Kinder, die Hand in Hand durch den Schaum wateten."
        },
        UI_Accessory_Desc_91001 = {
          ContentDE = "Kopfschmuck von Berenica\n „Wünsche? Ich ... habe keine speziellen Wünsche. Jeden Morgen dein Lächeln zu sehen, würde mir schon ausreichen.“"
        },
        UI_Accessory_Desc_91002 = {
          ContentDE = "Kopfschmuck von Tabethe\n „... Hey ... hey, lass mich mit dir kämpfen! Ich langweile mich zu Tode und meine Tentakel müssen sich strecken!“"
        },
        UI_Accessory_Desc_91003 = {
          ContentDE = "Kopfschmuck von Hilda\n „Ob Fliegen oder Filthoiden – für mich sind sie alle nur Schmutz, der beseitigt werden muss. Kampf ist also nichts anderes als eine besonders befriedigende Form der Reinigung.“"
        },
        UI_Accessory_Desc_91004 = {
          ContentDE = "Kopfschmuck von Fushu\n „‚Im lichten Schatten der Aprikosenblüten wird im Mörser Arznei bereitet, Frühling um Frühling, Herbst um Herbst.‘\n Wie haben die alten Aprikosenbäume im hinteren Garten von der Halle der Vergänglichkeit dieses Jahr wohl geblüht? Ob sich am Ende wieder Kinder beim Pflücken der Früchte versehentlich verletzen?“"
        },
        UI_Accessory_Desc_91005 = {
          ContentDE = "Kopfschmuck von Yuming\n „Bittest du mich um Hilfe als Freund? Oder siehst du mich nur als Waffe, die du nach Belieben einsetzen kannst?“"
        },
        UI_Accessory_Desc_91006 = {
          ContentDE = "Kopfschmuck von Psyche\n „In der Welt dort draußen wachsen bestimmt viele wundersame Blumen und Kräuter, die ich noch nie gesehen habe ... und echte Schmetterlinge werden zwischen ihnen tanzen, nicht wahr?“"
        },
        UI_Accessory_Desc_91007 = {
          ContentDE = "Kopfschmuck von Rebecca\n „Jede Zutat küssen und umarmen, sie verschlingen, ihren Duft aufsaugen, und schließlich miteinander verschmelzen, um ein langanhaltendes Aroma zu erzeugen – das ist die wahre Form der Liebe ... Stimmst du mir nicht zu?“"
        },
        UI_Accessory_Desc_91008 = {
          ContentDE = "Kopfschmuck von Truffle und Filbert\n „Nur satt wird man stark! Mit leerem Bauch kann man nicht kämpfen!“"
        },
        UI_Accessory_Desc_91009 = {
          ContentDE = "Kopfschmuck von Lynn\n „Sie ist meine Vorgesetzte. Sie gibt Befehle, ich führe sie aus. Mehr braucht es nicht.“"
        },
        UI_Accessory_Equip = {ContentDE = "Ausrüsten"},
        UI_Accessory_Equipped = {
          ContentDE = "Ausgerüstet"
        },
        UI_Accessory_Name_10001 = {
          ContentDE = "Küken JoeJoe"
        },
        UI_Accessory_Name_10002 = {
          ContentDE = "Küken JoeJoe: Opakes weiß"
        },
        UI_Accessory_Name_10003 = {
          ContentDE = "Küken JoeJoe: Karamell"
        },
        UI_Accessory_Name_10004 = {
          ContentDE = "Küken JoeJoe: Azur"
        }
      }
    end
  },
