        UI_Skin_CharHasnotGottenReminder = {
          ContentDE = "<H>%s</> noch nicht erhalten. Willst du <H>%s</> ×1 wirklich beanspruchen?"
        },
        UI_Skin_Des_0010 = {
          ContentDE = "Die Glocke schlägt am kürzesten Tag des Jahres, und Wünsche werden der Nacht anvertraut, um im Sternenlicht in den morgigen Tag getragen zu werden."
        },
        UI_Skin_Des_0011 = {
          ContentDE = "Enthüllte Schönheit, Anmut ist ihr Begleiter."
        },
        UI_Skin_Des_1101 = {
          ContentDE = "Schwarz ist die Farbe der Nacht – ein ruhiger, wachsamer Schleier, der über die Welt gebreitet ist. Schwarz ist die Farbe des Schattens – ein Mantel, unter dem man immer in der Nähe derer bleiben kann, die einem am Herzen liegen. Berenica bevorzugt dies."
        },
        UI_Skin_Des_1103 = {
          ContentDE = "Ein Schatten in Bewegung. Ein tollpatschiger Schauspieler auf der Bühne. Eine Geschichte, erzählt von einem Narren."
        },
        UI_Skin_Des_1104 = {
          ContentDE = "Vergoldete Couture – maßgeschneidert, pompös – mehr als nur Kleidung; ein Statussymbol."
        },
        UI_Skin_Des_1501 = {
          ContentDE = "Die Doktrin der Elysischen Kirche ist nicht nur in Stoff eingenäht – sie ist in die Seele graviert, ein Zeugnis für ein Mädchen, das seine Wut immer wieder abschüttelt und sich erneut geduldig und entschlossen erhebt."
        },
        UI_Skin_Des_1502 = {
          ContentDE = "Gazeartige Schleier, verwoben aus Dämmerung und Morgenrot, führen jede Seele über den tränenreichen Fluss – zum Nebelmeer, wo alle wiedergeboren werden."
        },
        UI_Skin_Des_1503 = {
          ContentDE = "Der Regen perlt von den wallenden Gewändern ab, sammelt sich an der Spitze des Schwertes und löst sich dann in der Welt der schwebenden Klingen auf."
        },
        UI_Skin_Des_1601 = {
          ContentDE = "Treibend durch die Nacht und das Meer, in weißen Gewändern, der Morgendämmerung entgegen. Wann hat dieser herrliche Mond angefangen zu existieren? Mein Glas erhebend fragte ich den azurblauen Himmel."
        },
        UI_Skin_Des_1801 = {
          ContentDE = "Die Nachtigall heftet sich schneeweiße Federn an den Schwanz, und ihre zarten Flügel tragen ihre Träume in die Wolken."
        },
        UI_Skin_Des_2101 = {
          ContentDE = "Die Tentakel der Quallen gleiten wie ein Schleier in die Tiefe, lassen das Herz eines Liebhabers im Dunkeln vor Sehnsucht erbeben."
        },
        UI_Skin_Des_210102 = {
          ContentDE = "Unter Schichten aus Schleiern wird Liebe im Flüstern gestanden und mit dem Tod die Ewigkeit berührt."
        },
        UI_Skin_Des_2301 = {
          ContentDE = "Was windet sich in der Dunkelheit – Verschwörung, Chaos, Verbrechen? Nichts dergleichen. Nur Tentakel."
        },
        UI_Skin_Des_2401 = {
          ContentDE = "Duftende Kräuternoten durchströmen weiße Ärmel, flüsternd vom Wiedererwachen des Lebens in der Verwelkung."
        },
        UI_Skin_Des_240101 = {
          ContentDE = "Gezeiten, die den Staub hinwegspülen, Wellen, die das Herz beruhigen."
        },
        UI_Skin_Des_3101 = {
          ContentDE = "Die Wärme des Schießpulvers klammert sich an die matte Uniform – getrieben vom Pulsschlag des leidenschaftlichen Blutes."
        },
        UI_Skin_Des_3103 = {
          ContentDE = "Flammende Fäden in Rot und Weiß verknüpfen die Träumereien eines Wahnsinnigen – und verweben den unschuldigen Traum eines Jungen."
        },
        UI_Skin_Des_3201 = {
          ContentDE = "Ketten und Dornen symbolisieren die Vergeltung für Sünden – und fesseln das gerechte Feuer, das in uns lodert."
        },
        UI_Skin_Des_3301 = {
          ContentDE = "Ein multifunktionaler Helm, hergestellt aus einem Topf – eine robuste Rüstung für ein Plündermädchen."
        },
        UI_Skin_Des_4101 = {
          ContentDE = "Ein sternenbesprenkeltes Blau schimmert auf ihrer Uniform – ein Wille, sie zu beschützen, und ein in die Zukunft gerichteter Blick."
        },
        UI_Skin_Des_4102 = {
          ContentDE = "Sonnenschein ergießt sich wie geschmolzenes Gold über prächtigen Brokat – der Anbruch der Revolution, reflektiert in ihren goldenen Augen."
        },
        UI_Skin_Des_4201 = {
          ContentDE = "Der Donner des Himmels dröhnt durch seine Gestalt. Dafengs Mandat befolgend, findet die Sünde keinen Zufluchtsort – und er selbst auch nicht."
        },
        UI_Skin_Des_4202 = {
          ContentDE = "Eine Medaille strahlt mit einem genialen Verstand darüber. Eine Uniform lässt das Herz eines normalen Mannes darunter höher schlagen."
        },
        UI_Skin_Des_4301 = {
          ContentDE = "Sie trägt weder Rüstung noch Krone – und doch strahlt ihre Präsenz eine gebieterische Furcht aus."
        },
        UI_Skin_Des_5101 = {
          ContentDE = "Weiße Wolken wehen durch die Straßen und tragen den Duft von Malz und Kaminfeuer mit sich – getrieben vom Wind zu jedem leeren Magen."
        },
        UI_Skin_Des_510101 = {
          ContentDE = "Warmen Sonnenschein sammeln, fein verarbeiten und verschwenderisch verteilen!"
        },
        UI_Skin_Des_5102 = {
          ContentDE = "Einfache Gewänder können die blutroten Klagelaute dunkler Gassen nicht zum Verstummen bringen – aber sie bewahren einen Funken Sternenlicht vor der Grausamkeit der Welt."
        },
        UI_Skin_Des_5301 = {
          ContentDE = "Ein Schmetterling ruht in ihrer Armbeuge, erfüllt von Träumen, die den Winterfrost überdauert haben."
        },
        UI_Skin_Des_530101 = {
          ContentDE = "In einer Mittsommernacht, unter funkelnden Sternen, ein Wald, in dem Stiefmütterchen und Schmetterlingsflügel einen zarten Reigen tanzten – ein Anblick, den sie nie zuvor gesehen hatte."
        },
        UI_Skin_Des_5401 = {
          ContentDE = "Üppiges Grün, sich erhebend aus Rauch und Pulverdampf – leicht wie wildes Gras, und ebenso unbeugsam."
        },
        UI_Skin_Forbid = {
