        UI_WEAPON_DESC_10101 = {
          ContentDE = "Die Waffe, die Berenica trägt. Eine Klinge mit goldenen Verzierungen. Die Klinge besteht aus einem seltenen schwarzen Metall. Dies ist eindeutig keine Waffe eines der Dorfbewohner der Purgatorio-Insel.\n "
        },
        UI_WEAPON_DESC_10102 = {
          ContentDE = "Mögen ausgelassene Festlichkeiten deine Einsamkeit lindern."
        },
        UI_WEAPON_DESC_10103 = {
          ContentDE = "Ein Schwert von unbekannter Herkunft. Ein Schwert, das bereits seit Urzeiten existiert. Vielleicht wird es eines Tages zum Schlüssel für die Verbindung zwischen Vergangenheit und Gegenwart."
        },
        UI_WEAPON_DESC_10104 = {
          ContentDE = "Die beste Verteidigung ist ein starker Angriff – aber vergiss nicht die Bedeutung von ausreichender Erholung."
        },
        UI_WEAPON_DESC_10105 = {
          ContentDE = "Ich werde eine Reise jenseits des Sandes antreten, genau wie du."
        },
        UI_WEAPON_DESC_10198 = {
          ContentDE = "Ein Schwert, veredelt mit den neuesten Technologien zur Oberflächenbehandlung – beliebt bei Rittern, die für ihre Loyalität und Disziplin bekannt sind."
        },
        UI_WEAPON_DESC_10199 = {
          ContentDE = "Ein gewöhnliches Schwert. Aus dem billigsten Metall hergestellt, also ist es nicht schlimm, wenn es zerbricht."
        },
        UI_WEAPON_DESC_10201 = {
          ContentDE = "Küss mich! Knutsch mich! Bevor der morgige Tag anbricht, bevor junge Herzen altern und bevor der Tod uns scheidet."
        },
        UI_WEAPON_DESC_10202 = {
          ContentDE = "Eine Stangenwaffe, die die Sternenweber aus ihrer Heimat mitgebracht haben – Huaxu. Form und Farbe der Klinge sind von einer besonderen Pflanze in Huaxu inspiriert, die man Weide nennt. In Huaxu symbolisiert diese Pflanze normalerweise die „Heimat“. Die Sternenweber sind zwar gerade damit beschäftigt, jeden Zentimeter von Atlasia mit Sternenhimmeln zu überziehen, aber irgendwann werden sie in ihre grüne Heimat mit den üppigen Weiden zurückkehren."
        },
        UI_WEAPON_DESC_10203 = {
          ContentDE = "Die Jahre vergehen, und die Erdenbewohner werden immer durchschnittlicher."
        },
        UI_WEAPON_DESC_10204 = {
          ContentDE = "Einst vergrub ich einen Samen in der gefrorenen Erde und hoffte auf einen Erntemond, der vielleicht niemals kommen würde."
        },
        UI_WEAPON_DESC_10205 = {
          ContentDE = "Eine Sense, die vom Ritterorden der Heiligen Iris der Elysischen Kirche geführt wird. „Heilige Erhebung!“ Geheiligt sei das Licht der göttlichen Barmherzigkeit, das die andauernde Narretei der Unweisen zerschmettert."
        }
      }
    end
  },
  {
    MinKey = "UI_WEAPON_DESC_10206",
    MaxKey = "UI_Warning_Age_Title",
    Loader = function()
      return {
        UI_WEAPON_DESC_10206 = {
          ContentDE = "Verfall ist das Ende des Lebens; akzeptiere ihn, und du wirst in einen ewigen und friedlichen Hafen segeln."
        },
        UI_WEAPON_DESC_10207 = {
          ContentDE = "Die Wut des Ozeans einfangend, bringt sein azurblauer Kristall die Gnadenbitte des Feindes zum Verstummen, bevor sie die Ruhe dieses Reiches stören kann. Die Gnadengesuche des Feindes sind dissonante Klänge, die erstickt werden müssen, bevor sie aus der Partitur dieses Reiches entweichen können."
        },
        UI_WEAPON_DESC_10208 = {
          ContentDE = "Eine Taube, die schwor, die Würde zu verteidigen, und jede Feder für den Frieden opfert."
        },
        UI_WEAPON_DESC_10209 = {
          ContentDE = "Die blutgetränkte Klinge sticht direkt ins Herz. Ehe die sengende Lava sich verfestigt, bleibt ein kurzer Moment, den man zur Flucht nutzen kann."
        },
        UI_WEAPON_DESC_10298 = {
          ContentDE = "Eine Lanze, die mit den neuesten Verfahren der Oberflächenbehandlung veredelt wurde – beliebt bei unerschütterlichen Wachen, die standhaft ihre Stellung halten."
        },
        UI_WEAPON_DESC_10299 = {
          ContentDE = "Eine gewöhnliche Lanze. Aus dem billigsten Metall hergestellt, also ist es nicht schlimm, wenn sie zerbricht."
        },
        UI_WEAPON_DESC_10301 = {
          ContentDE = "Brenn, brenn, brenn! Dieses läuternde Feuer wird alles Böse auf der Welt verzehren."
        },
        UI_WEAPON_DESC_10302 = {
          ContentDE = "Nur unvergleichliche Stärke kann eiserne Gesetze schmieden."
        },
        UI_WEAPON_DESC_10303 = {
          ContentDE = "Eine makellose Klinge, die mit einem lautlosen Schrei durch die Luft schneidet – immer darauf wartend, mit Blut befleckt zu werden."
        },
        UI_WEAPON_DESC_10304 = {
          ContentDE = "Durchtrenne die Echos längst vergangener Äonen; lass an ihrer Stelle den Frieden der Zeitalter aufsteigen."
        },
        UI_WEAPON_DESC_10398 = {
          ContentDE = "Ein Großschwert, das mit den neuesten Verfahren zur Oberflächenbehandlung veredelt wurde – beliebt bei stillen Gefolgsleuten, die ihren Dienst ohne ein Hinterfragen verrichten."
        },
        UI_WEAPON_DESC_10399 = {
          ContentDE = "Gewöhnliches Großschwert. Aus dem billigsten Metall hergestellt, also ist es nicht schlimm, wenn es zerbricht."
        },
        UI_WEAPON_DESC_10401 = {
          ContentDE = "Ein einsamer Wolfshund hat nur seine Zähne. Vor ihm liegt das Labyrinth des Schicksals, unter ihm der verbrannte Boden seiner Heimat."
        },
        UI_WEAPON_DESC_10402 = {
          ContentDE = "Als die dunkle Flut heranrollte, reckte der Träger diese goldenen Klingen als Opfergabe empor – ein letztes Gebet an einen stillen Gott, der keine Antwort gab."
        },
        UI_WEAPON_DESC_10403 = {
          ContentDE = "Im Moment bist du das Raubtier – in der Tiefe lauernd, auf den Angriff wartend."
        },
        UI_WEAPON_DESC_10498 = {
          ContentDE = "Zwei Klingen, die mit den neuesten Verfahren zur Oberflächenbehandlung veredelt wurden – beliebt bei namenlosen Attentätern, die in ihrem Kielwasser nur Stille nach sich ziehen."
        },
        UI_WEAPON_DESC_10499 = {
          ContentDE = "Ein Katana, das mit den neuesten Verfahren zur Oberflächenbehandlung veredelt wurde – beliebt bei Leuten, die ihren Weg lieber alleine beschreiten."
        },
        UI_WEAPON_DESC_10501 = {
          ContentDE = "Ein alter Traum mit Blick auf die Zukunft."
        },
        UI_WEAPON_DESC_10502 = {
          ContentDE = "Der Himmel gewährt allem, was wächst, seine Gnade; der Regen spendet Barmherzigkeit, wo das Leben noch fließt."
        },
        UI_WEAPON_DESC_10503 = {
          ContentDE = "Es sind nicht nur Gefühle, die das menschliche Herz fesseln. Diese sich windende Peitschenklinge ist fesselnder als Worte und schneidet tiefer als Vertrauen."
        },
        UI_WEAPON_DESC_10504 = {
          ContentDE = "Ausgetrocknete Korallen liegen verstreut am stillen Ufer – Fragmente, in denen sich die zerbrochenen Träume des Meeres wiegen."
        },
        UI_WEAPON_DESC_10598 = {
          ContentDE = "Eine Peitschenklinge, die mit den neuesten Verfahren zur Oberflächenbehandlung veredelt wurde – beliebt bei denen, die sich am Gemetzel ergötzen."
        },
        UI_WEAPON_DESC_10599 = {
          ContentDE = "Eine gewöhnliche Peitschenklinge. Aus dem billigsten Metall hergestellt, also ist es nicht schlimm, wenn es zerbricht."
        },
        UI_WEAPON_DESC_10601 = {
          ContentDE = "Eine einzigartig geformte Klinge aus der bekannten Tragödie Momiji: Eine Chronik der Rebellion. Ihr blutrot gefärbter Griff soll das Blut eines Königs in sich tragen – erschlagen von genau der Hand, die ihn zu beschützen geschworen hatte."
        },
        UI_WEAPON_DESC_10602 = {
          ContentDE = "In den Augen des Sterbenden sinkt ein einzelnes purpurrotes Blütenblatt herab – schwerelos, lautlos und endgültig."
        },
        UI_WEAPON_DESC_10603 = {
          ContentDE = "Eingraviert in den Griff in verwitterter Schrift: „Gelobt sei die Elysische Kirche.“ Möge die heilige Gnade der Großen Neun auf den unglückseligen Boden von Yashnia herniedersinken."
        },
        UI_WEAPON_DESC_10698 = {
          ContentDE = "Ein Katana, das mit den neuesten Verfahren zur Oberflächenbehandlung veredelt wurde – beliebt bei Leuten, die ihren Weg lieber alleine beschreiten."
        },
        UI_WEAPON_DESC_10699 = {
          ContentDE = "Ein gewöhnliches Katana. Aus dem billigsten Metall hergestellt, also ist es nicht schlimm, wenn es zerbricht."
        },
        UI_WEAPON_DESC_110101 = {
          ContentDE = "„Null“. Der Ursprung. Der Anfang von allem."
        },
        UI_WEAPON_DESC_150101 = {
          ContentDE = "„Die Göttin wandte sich erneut an den siebten Heiligen: ‚Mit diesem Schwert schmiede ich diesen Pakt mit dir und deinen Nachkommen. Wer unerschütterliche Entschlossenheit zeigt, soll meinen Segen empfangen, und damit den Schutz dieses Schwertes.‘“"
        },
        UI_WEAPON_DESC_20101 = {
          ContentDE = "Durch die Kugel der Wahrheit enthüllt sich die Realität."
        },
        UI_WEAPON_DESC_20102 = {
          ContentDE = "Ein Trugschluss, herausgerissen aus dem Strudel des Todes – eine Wahrheit, die nie hätte sein dürfen."
        },
        UI_WEAPON_DESC_20103 = {
          ContentDE = "Das Grollen göttlicher Orakel soll durch die Schädel aller Ketzer hallen."
        },
        UI_WEAPON_DESC_20198 = {
          ContentDE = "Eine Pistole, die mit den neuesten Verfahren zur Oberflächenbehandlung veredelt wurde – beliebt bei allen, die gerne unter freiem Himmel reisen."
        },
        UI_WEAPON_DESC_20199 = {
          ContentDE = "Eine gewöhnliche Pistole. Aus dem billigsten Metall hergestellt, also ist es nicht schlimm, wenn es zerbricht."
        },
        UI_WEAPON_DESC_20201 = {
          ContentDE = "In den sich windenden Ebenen des Todes zieht jeder Fehler den nächsten nach sich – und dann noch einen."
        },
        UI_WEAPON_DESC_20203 = {
          ContentDE = "Die endlose Weite des Ozeans pulsiert unaufhörlich im Rhythmus des Lebens – üppig, überschwänglich und unerschütterlich."
        },
        UI_WEAPON_DESC_20205 = {
          ContentDE = "Das Grollen göttlicher Orakel soll durch die Schädel aller Ketzer hallen."
        },
        UI_WEAPON_DESC_20296 = {
          ContentDE = "Doppelpistolen, die mit den neuesten Verfahren zur Oberflächenbehandlung veredelt wurden – beliebt bei allen, die gerne unter freiem Himmel reisen."
        },
        UI_WEAPON_DESC_20298 = {
          ContentDE = "Gewöhnliche Doppelpistolen. Aus dem billigsten Metall hergestellt, also ist es nicht schlimm, wenn es zerbricht."
        },
        UI_WEAPON_DESC_20301 = {
          ContentDE = "Die Bußfertigen sollen nicht länger zu den Sternen aufblicken – der Himmel schenkt ihnen kein Gehör, und die Sterne gewähren ihnen keine Absolution."
        },
        UI_WEAPON_DESC_20302 = {
          ContentDE = "Abenddämmerung, rote Tanzschuhe und Tau auf Rosen; ein Luftzug streift die Schläfen, das entrüstete Kreischen schneller Schüsse und der Geruch von Schießpulver ... Alle bezeugen ein Fest der Projektile."
        },
        UI_WEAPON_DESC_20303 = {
          ContentDE = "Die wahrhaftigste Rückkehr zur Natur besteht darin, zu Asche zu zerfallen und in der wartenden Erde zu versinken."
        },
        UI_WEAPON_DESC_20304 = {
          ContentDE = "Bronze härtet den stählernen Rahmen; inmitten von Dornen, eine Seele, geschmiedet für den Anspruch auf Heldentum."
        },
        UI_WEAPON_DESC_20305 = {
          ContentDE = "Hellfire reitet auf eintausend silbernen Geschossen, die auf den Boden herabregnen, das Edikt der Götter in die Herzen aller Ketzer einätzend."
        },
        UI_WEAPON_DESC_20398 = {
          ContentDE = "Ein Granatwerfer, der mit den neuesten Verfahren zur Oberflächenbehandlung veredelt wurde – beliebt bei furchtlosen Belagerungsbrechern."
        },
        UI_WEAPON_DESC_20399 = {
          ContentDE = "Ein Granatwerfer, gefertigt unter Verwendung der neuesten Schmelz- und Vergoldungstechniken. Dieses Modell ist eine klare Empfehlung von Schmiedemeistern. Die perfekte Balance zwischen Qualität und Erschwinglichkeit macht es zu einer beliebten Wahl bei Reisenden in ganz Atlasia."
        },
        UI_WEAPON_DESC_20401 = {
          ContentDE = "Erst wenn der letzte Schrei verklungen ist ... kann wieder Ruhe in die Welt einkehren."
        },
        UI_WEAPON_DESC_20402 = {
          ContentDE = "Stecke Blumensamen in den Körper, damit die Zerstörung von innen heraus erblühen kann."
        },
        UI_WEAPON_DESC_20403 = {
          ContentDE = "Eine Feuerwaffe, die vom Ritterorden der Heiligen Iris der Elysischen Kirche eingesetzt wird. Heilige Erhebung! Wir geloben, die Botschaft der Großen Neun in ganz Atlasia zu verbreiten."
        },
        UI_WEAPON_DESC_20405 = {
          ContentDE = "– Hmm? Das Ende von Atlasia? So sei es. Es gibt schlimmere Schicksale, als in Flammen und Feuerwerk unterzugehen."
        },
        UI_WEAPON_DESC_20498 = {
          ContentDE = "Eine Schrotflinte, die mit den neuesten Verfahren zur Oberflächenbehandlung veredelt wurde – beliebt bei erfahrenen Jägern in der Wildnis."
        },
        UI_WEAPON_DESC_20499 = {
          ContentDE = "Eine gewöhnliche Schrotflinte. Aus dem billigsten Metall hergestellt, also ist es nicht schlimm, wenn es zerbricht."
        },
        UI_WEAPON_DESC_20501 = {
          ContentDE = "Wenn Kugeln durch Fleisch pflügen und die Seele versengen, wie lange können Güte, Integrität und Tapferkeit bestehen?"
        },
        UI_WEAPON_DESC_20502 = {
          ContentDE = "Eine Waffe, die vom „Raben“ der Verlassenen benutzt wird. Vernimm den Zorn der Verbannten! Die Totenglocke des Imperiums läutet!"
        },
        UI_WEAPON_DESC_20503 = {
          ContentDE = "Ein Flammenwerfer, die vom Ritterorden der Heiligen Iris der Elysischen Kirche eingesetzt wird. Heilige Erhebung! Möge das heilige Feuer uns umhüllen. In deinem Namen schwören wir, alles Böse zu verbrennen."
        },
        UI_WEAPON_DESC_20504 = {
          ContentDE = "Ein Maschinengewehr, das vom Ritterorden der Heiligen Iris der Elysischen Kirche geführt wird. „Heilige Erhebung!“ Sollten wir nur den ersten Schimmer der Morgendämmerung erblicken, auch wenn unser Weg mit Dornen übersät ist, werden wir ihn als süße Wohltat begrüßen."
        },
        UI_WEAPON_DESC_20506 = {
          ContentDE = "Durch die sich teilenden Wolken nimmt ein gemalter Flug seine Form an, wo sich Pfauen auf Seide treffen, um sich gegenseitig mit ihrer Anmut zu umwerben."
        },
        UI_WEAPON_DESC_20507 = {
          ContentDE = "Der junge Seemann, immer zu sehr damit beschäftigt, den Mast vor dem Sturm zu sichern, nahm die versteckten Liebesbotschaften unter den Wellen niemals wahr – nicht ahnend, dass jedes Lied der Meerjungfrau eine nur für ihn bestimmte Serenade war."
        },
        UI_WEAPON_DESC_20509 = {
          ContentDE = "Aus einer schneebedeckten Feder flocht ich einen schmalen Käfig und schloss die wilde Welt darin ein."
        },
        UI_WEAPON_DESC_20510 = {
          ContentDE = "Mein Schwert wirbelte den silbernen Mond auf, sich widerspiegelnd in einem Strom von Träumen; in der Stille der Zeit, ein weiterer Herbst verblasste unter seinem silbernen Schimmer."
        },
        UI_WEAPON_DESC_20598 = {
          ContentDE = "Ein Sturmgewehr, mit den neuesten Verfahren zur Oberflächenbehandlung veredelt – beliebt bei den hartgesottenen Pionieren, die an vorderster Front kämpfen."
        },
        UI_WEAPON_DESC_20599 = {
          ContentDE = "Ein Maschinengewehr, gefertigt unter Verwendung der neuesten Schmelz- und Vergoldungstechniken. Dieses Modell ist eine klare Empfehlung von Schmiedemeistern. Die perfekte Balance zwischen Qualität und Erschwinglichkeit macht es zu einer beliebten Wahl bei Reisenden in ganz Atlasia."
        },
        UI_WEAPON_DESC_20601 = {
          ContentDE = "Du, eine einsame Seele, stehst inmitten der lodernden Flamme und wirst doch bereitwillig zu einem Sandkorn, das vom Wind der Veränderung hinweggefegt wird. So beginnt deine Wiedergeburt, und die Wiedererlangung deines Schicksals."
